fn default_authoring_workspace(_book_type: story_core::BookType) -> Workspace {
    // Fiction and non-fiction share the same authoritative hierarchy. Scene
    // Cards remain available as an alternate presentation, not a book-type
    // specific workspace.
    Workspace::Outline
}
const PRIMARY_DESTINATIONS: [Workspace; 3] =
    [Workspace::Editor, Workspace::Outline, Workspace::Reading];

fn is_manuscript_outliner(workspace: Workspace) -> bool {
    matches!(workspace, Workspace::Outline | Workspace::Cards)
}

fn next_primary_destination(current: Workspace, forward: bool) -> Workspace {
    let current = if current == Workspace::Cards {
        Workspace::Outline
    } else {
        current
    };
    let Some(index) = PRIMARY_DESTINATIONS
        .iter()
        .position(|destination| *destination == current)
    else {
        return if forward {
            PRIMARY_DESTINATIONS[0]
        } else {
            PRIMARY_DESTINATIONS[PRIMARY_DESTINATIONS.len() - 1]
        };
    };
    let next = if forward {
        (index + 1) % PRIMARY_DESTINATIONS.len()
    } else {
        (index + PRIMARY_DESTINATIONS.len() - 1) % PRIMARY_DESTINATIONS.len()
    };
    PRIMARY_DESTINATIONS[next]
}

fn destination_title(workspace: Workspace) -> &'static str {
    match workspace {
        Workspace::Editor => "Manuscript",
        Workspace::Reading => "Reference",
        _ => workspace.title(),
    }
}

fn structural_kind_label(kind: story_core::NodeKind) -> &'static str {
    match kind {
        story_core::NodeKind::Section => "Section",
        story_core::NodeKind::Chapter => "Chapter",
        story_core::NodeKind::Group => "Group",
    }
}

fn bulk_node_location(
    state: &AppState,
    kind: BulkItemKind,
) -> Result<(Option<story_core::NodeId>, u32), Box<dyn std::error::Error>> {
    let nodes = state.app.list_structural_nodes()?;
    let selected_row = outline_rows(state).get(state.selected).cloned();
    if kind == BulkItemKind::Scene {
        let scenes = state.app.list_scenes(false)?;
        return match selected_row {
            Some(OutlineRow::Scene(id)) => {
                let scene = state.app.get_scene(id)?;
                if let Some(chapter) = scene.chapter_id {
                    Ok((Some(chapter), scene.position.unwrap_or(0).saturating_add(1)))
                } else {
                    Ok((
                        None,
                        scenes
                            .iter()
                            .filter(|item| item.chapter_id.is_none())
                            .count() as u32,
                    ))
                }
            }
            Some(OutlineRow::Chapter { id, .. }) => Ok((
                Some(id),
                scenes
                    .iter()
                    .filter(|item| item.chapter_id == Some(id))
                    .count() as u32,
            )),
            _ => Ok((
                None,
                scenes
                    .iter()
                    .filter(|item| item.chapter_id.is_none())
                    .count() as u32,
            )),
        };
    }
    let selected_node = match selected_row.as_ref() {
        Some(OutlineRow::Section { id, .. } | OutlineRow::Chapter { id, .. }) => Some(*id),
        Some(OutlineRow::ContentUnit(id)) => state.app.get_content_unit(*id)?.parent_id,
        Some(OutlineRow::Scene(id)) => state.app.get_scene(*id)?.chapter_id,
        None => None,
    }
    .and_then(|id| nodes.iter().find(|node| node.id == id));
    let sibling_count = |parent: Option<story_core::NodeId>| {
        nodes.iter().filter(|node| node.parent_id == parent).count() as u32
    };
    match selected_node {
        Some(node) if node.kind == "section" => {
            let children = sibling_count(Some(node.id));
            Ok((Some(node.id), children))
        }
        Some(node) => Ok((node.parent_id, node.position.saturating_add(1))),
        None => Ok((None, sibling_count(None))),
    }
}
