#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum BulkItemKind {
    Section,
    Chapter,
    Scene,
}

impl BulkItemKind {
    fn next(self) -> Self {
        match self {
            Self::Chapter => Self::Section,
            Self::Section => Self::Scene,
            Self::Scene => Self::Chapter,
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::Section => "Section",
            Self::Chapter => "Chapter",
            Self::Scene => "Scene",
        }
    }
}

