struct TerminalSpellingFinding {
    entity_kind: String,
    title: String,
    candidates: BTreeMap<String, u32>,
}

#[cfg(test)]
fn spellcheck_terminal_project(
    app: &WriterApp,
    language: &str,
    dictionary: Option<&str>,
    executable: &str,
) -> Result<Vec<TerminalSpellingFinding>, Box<dyn std::error::Error>> {
    spellcheck_terminal_project_with_engine(
        app,
        language,
        dictionary,
        executable,
        story_document::SpellcheckEngine::Aspell,
    )
}

fn spellcheck_terminal_project_with_engine(
    app: &WriterApp,
    language: &str,
    dictionary: Option<&str>,
    executable: &str,
    engine: story_document::SpellcheckEngine,
) -> Result<Vec<TerminalSpellingFinding>, Box<dyn std::error::Error>> {
    if language.trim().is_empty() {
        return Err("spellcheck language tag cannot be empty".into());
    }
    let root = app.project_root().canonicalize()?;
    let allowed = if let Some(relative) = dictionary {
        let path = root.join(relative).canonicalize()?;
        if !path.starts_with(&root) || !path.is_file() {
            return Err("personal dictionary must be a regular project-local file".into());
        }
        story_document::parse_personal_dictionary(&fs::read_to_string(path)?)?
    } else {
        std::collections::BTreeSet::new()
    };
    let input = app.processing_input()?;
    let allowed = &allowed;
    let prose = input
        .scenes
        .into_iter()
        .map(|scene| ("scene".to_owned(), scene.title, scene.text))
        .chain(
            input
                .content_units
                .into_iter()
                .map(|unit| ("content-unit".to_owned(), unit.title, unit.text)),
        );
    let mut findings = Vec::new();
    for (kind, title, text) in prose {
        if let Some(finding) =
            spellcheck_text_with_engine(&text, &title, language, allowed, executable, engine)?
        {
            let mut finding = finding;
            finding.entity_kind = kind;
            findings.push(finding);
        }
    }
    Ok(findings)
}

fn project_spelling_dictionary_path(
    project_root: &Path,
    language: &str,
) -> Result<PathBuf, Box<dyn std::error::Error>> {
    if language.is_empty()
        || !language
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_'))
    {
        return Err("invalid spelling dictionary language tag".into());
    }
    let root = project_root.canonicalize()?;
    let metadata_dir = root.join(".writers-ide");
    let dictionaries_dir = metadata_dir.join("dictionaries");
    for directory in [&metadata_dir, &dictionaries_dir] {
        match fs::symlink_metadata(directory) {
            Ok(metadata) if metadata.file_type().is_symlink() => {
                return Err("project dictionary directory must not be a symlink".into());
            }
            Ok(metadata) if !metadata.is_dir() => {
                return Err("project dictionary path is not a directory".into());
            }
            Ok(_) => {}
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
            Err(error) => return Err(error.into()),
        }
    }
    Ok(dictionaries_dir.join(format!("{language}.txt")))
}

fn load_project_spelling_dictionary(
    project_root: &Path,
    language: &str,
) -> Result<BTreeSet<String>, Box<dyn std::error::Error>> {
    let path = project_spelling_dictionary_path(project_root, language)?;
    if fs::symlink_metadata(&path).is_ok_and(|metadata| metadata.file_type().is_symlink()) {
        return Err("project dictionary file must not be a symlink".into());
    }
    match fs::read_to_string(path) {
        Ok(source) => Ok(story_document::parse_personal_dictionary(&source)?
            .into_iter()
            .map(|word| word.to_lowercase())
            .collect()),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(BTreeSet::new()),
        Err(error) => Err(error.into()),
    }
}

fn add_word_to_project_spelling_dictionary(
    project_root: &Path,
    language: &str,
    word: &str,
) -> Result<bool, Box<dyn std::error::Error>> {
    use std::io::Write;

    if word.is_empty()
        || word.chars().any(|character| {
            character.is_whitespace() || character.is_control() || matches!(character, '/' | '\\')
        })
    {
        return Err("select a single word to add to the project dictionary".into());
    }
    let path = project_spelling_dictionary_path(project_root, language)?;
    let words = load_project_spelling_dictionary(project_root, language)?;
    if words.iter().any(|known| known.eq_ignore_ascii_case(word)) {
        return Ok(false);
    }
    let directory = path
        .parent()
        .ok_or("project dictionary has no parent directory")?;
    fs::create_dir_all(directory)?;
    let existing = match fs::read_to_string(&path) {
        Ok(source) => source,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => String::new(),
        Err(error) => return Err(error.into()),
    };
    let mut temporary = tempfile::NamedTempFile::new_in(directory)?;
    temporary.write_all(existing.as_bytes())?;
    if !existing.is_empty() && !existing.ends_with('\n') {
        temporary.write_all(b"\n")?;
    }
    temporary.write_all(word.as_bytes())?;
    temporary.write_all(b"\n")?;
    temporary.as_file().sync_all()?;
    temporary.persist(&path)?;
    if let Ok(directory_handle) = fs::File::open(directory) {
        directory_handle.sync_all()?;
    }
    Ok(true)
}

fn spellcheck_text_with_engine(
    text: &str,
    title: &str,
    language: &str,
    allowed: &std::collections::BTreeSet<String>,
    executable: &str,
    engine: story_document::SpellcheckEngine,
) -> Result<Option<TerminalSpellingFinding>, Box<dyn std::error::Error>> {
    let mut child = Command::new(executable)
        .args(engine.command_arguments(language))
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()?;
    use std::io::Write;
    child
        .stdin
        .take()
        .ok_or("spell checker stdin unavailable")?
        .write_all(text.as_bytes())?;
    let output = child.wait_with_output()?;
    if !output.status.success() {
        return Err(format!(
            "{} failed for {title}: {}",
            match engine {
                story_document::SpellcheckEngine::Aspell => "Aspell",
                story_document::SpellcheckEngine::Hunspell => "Hunspell",
            },
            String::from_utf8_lossy(&output.stderr)
        )
        .into());
    }
    let mut candidates = BTreeMap::new();
    for word in String::from_utf8(output.stdout)?
        .lines()
        .map(str::trim)
        .filter(|word| !word.is_empty())
    {
        let normalized = word.to_lowercase();
        if !allowed.contains(&normalized) {
            *candidates.entry(normalized).or_insert(0) += 1;
        }
    }
    Ok((!candidates.is_empty()).then(|| TerminalSpellingFinding {
        entity_kind: "document".to_owned(),
        title: title.to_owned(),
        candidates,
    }))
}

fn spelling_suggestions(
    word: &str,
    language: &str,
    executable: &str,
) -> Result<Vec<String>, Box<dyn std::error::Error>> {
    let mut child = Command::new(executable)
        .arg(format!("--lang={language}"))
        .arg("pipe")
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()?;
    use std::io::Write;
    child
        .stdin
        .take()
        .ok_or("spell checker stdin unavailable")?
        .write_all(format!("^{word}\n").as_bytes())?;
    let output = child.wait_with_output()?;
    if !output.status.success() {
        return Err(format!(
            "Aspell could not suggest a correction: {}",
            String::from_utf8_lossy(&output.stderr)
        )
        .into());
    }
    let response = String::from_utf8(output.stdout)?;
    let Some((_, list)) = response
        .lines()
        .find(|line| line.starts_with('&'))
        .and_then(|line| line.split_once(':'))
    else {
        return Ok(Vec::new());
    };
    Ok(list
        .split(", ")
        .map(str::trim)
        .filter(|candidate| !candidate.is_empty())
        .take(10)
        .map(str::to_owned)
        .collect())
}

fn spelling_occurrences(
    text: &str,
    candidates: &BTreeMap<String, u32>,
) -> Vec<SpellCheckOccurrence> {
    let mut occurrences = text
        .split_word_bound_indices()
        .filter_map(|(start, word)| {
            let has_letter_or_digit = word.chars().any(char::is_alphanumeric);
            let normalized = word.to_lowercase();
            if !has_letter_or_digit || !candidates.contains_key(&normalized) {
                return None;
            }
            let line = text[..start].bytes().filter(|byte| *byte == b'\n').count();
            let line_start = text[..start].rfind('\n').map_or(0, |index| index + 1);
            let column = text[line_start..start].graphemes(true).count();
            Some(SpellCheckOccurrence {
                word: word.to_owned(),
                byte_range: start..start + word.len(),
                line: line + 1,
                column: column + 1,
            })
        })
        .collect::<Vec<_>>();
    occurrences.sort_by_key(|occurrence| occurrence.byte_range.start);
    occurrences
}

fn spelling_review_text(occurrences: &[SpellCheckOccurrence]) -> String {
    if occurrences.is_empty() {
        return "No spelling candidates found. The manuscript is unchanged.".into();
    }
    occurrences
        .iter()
        .map(|occurrence| {
            format!(
                "{} · line {}, column {}",
                occurrence.word, occurrence.line, occurrence.column
            )
        })
        .collect::<Vec<_>>()
        .join("\n")
}

fn planning_board_bounds(items: &[story_storage::PlanningBoardItemRecord]) -> ([f64; 2], [f64; 2]) {
    fn bounds(values: impl Iterator<Item = f64>) -> [f64; 2] {
        let values = values.collect::<Vec<_>>();
        let Some(minimum) = values.iter().copied().reduce(f64::min) else {
            return [0.0, 10.0];
        };
        let maximum = values.iter().copied().reduce(f64::max).unwrap_or(minimum);
        let padding = ((maximum - minimum) * 0.1).max(1.0);
        [minimum - padding, maximum + padding]
    }
    (
        bounds(items.iter().flat_map(|item| [item.x, item.x + item.width])),
        bounds(items.iter().map(|item| item.y + item.height)),
    )
}

fn planning_canvas_to_world(
    area: Rect,
    x_bounds: [f64; 2],
    y_bounds: [f64; 2],
    column: u16,
    row: u16,
) -> Option<(f64, f64)> {
    if area.width == 0 || area.height == 0 || !area.contains((column, row).into()) {
        return None;
    }
    let x_fraction = (column - area.x) as f64 / area.width as f64;
    let y_fraction = (row - area.y) as f64 / area.height as f64;
    Some((
        x_bounds[0] + x_fraction * (x_bounds[1] - x_bounds[0]),
        y_bounds[1] - y_fraction * (y_bounds[1] - y_bounds[0]),
    ))
}

#[cfg(test)]
fn planning_world_to_canvas(
    area: Rect,
    x_bounds: [f64; 2],
    y_bounds: [f64; 2],
    x: f64,
    y: f64,
) -> Option<(u16, u16)> {
    if area.width == 0 || area.height == 0 {
        return None;
    }
    let x_fraction = ((x - x_bounds[0]) / (x_bounds[1] - x_bounds[0])).clamp(0.0, 0.999_999);
    let y_fraction = ((y_bounds[1] - y) / (y_bounds[1] - y_bounds[0])).clamp(0.0, 0.999_999);
    Some((
        area.x + (x_fraction * area.width as f64).floor() as u16,
        area.y + (y_fraction * area.height as f64).floor() as u16,
    ))
}

fn move_planning_bounds(bounds: [f64; 2], delta: f64) -> [f64; 2] {
    [bounds[0] + delta, bounds[1] + delta]
}

fn zoom_planning_bounds(bounds: [f64; 2], focus: f64, scale: f64) -> [f64; 2] {
    [
        focus + (bounds[0] - focus) * scale,
        focus + (bounds[1] - focus) * scale,
    ]
}

fn handle_planning_board_mouse(
    state: &mut AppState,
    mouse: MouseEvent,
) -> Result<(), Box<dyn std::error::Error>> {
    let Some(board) = state
        .planning_board_id
        .filter(|_| state.workspace == Workspace::PlanningBoards)
    else {
        return Ok(());
    };
    if mouse.kind == MouseEventKind::Up(MouseButton::Left) {
        state.planning_drag = None;
        return Ok(());
    }
    let Some(area) = state.planning_board_area else {
        return Ok(());
    };
    if matches!(
        mouse.kind,
        MouseEventKind::ScrollUp
            | MouseEventKind::ScrollDown
            | MouseEventKind::ScrollLeft
            | MouseEventKind::ScrollRight
    ) && !area.contains((mouse.column, mouse.row).into())
    {
        return Ok(());
    }
    let items = state.app.list_planning_board_items(board)?;
    let default_bounds = planning_board_bounds(&items);
    let (x_bounds, y_bounds) = state
        .planning_board_view
        .as_ref()
        .filter(|view| view.board_id == board)
        .map(|view| (view.x_bounds, view.y_bounds))
        .unwrap_or(default_bounds);
    if matches!(
        mouse.kind,
        MouseEventKind::ScrollUp
            | MouseEventKind::ScrollDown
            | MouseEventKind::ScrollLeft
            | MouseEventKind::ScrollRight
    ) {
        let mut next_x = x_bounds;
        let mut next_y = y_bounds;
        match mouse.kind {
            MouseEventKind::ScrollUp | MouseEventKind::ScrollDown
                if mouse.modifiers.contains(KeyModifiers::CONTROL) =>
            {
                let focus =
                    planning_canvas_to_world(area, x_bounds, y_bounds, mouse.column, mouse.row)
                        .unwrap_or((
                            (x_bounds[0] + x_bounds[1]) / 2.0,
                            (y_bounds[0] + y_bounds[1]) / 2.0,
                        ));
                let scale = if mouse.kind == MouseEventKind::ScrollUp {
                    0.8
                } else {
                    1.25
                };
                next_x = zoom_planning_bounds(x_bounds, focus.0, scale);
                next_y = zoom_planning_bounds(y_bounds, focus.1, scale);
                state.message = if scale < 1.0 {
                    "Planning board zoomed in".into()
                } else {
                    "Planning board zoomed out".into()
                };
            }
            MouseEventKind::ScrollUp => {
                next_y = move_planning_bounds(y_bounds, (y_bounds[1] - y_bounds[0]) * 0.1);
                state.message = "Panned planning board up".into();
            }
            MouseEventKind::ScrollDown => {
                next_y = move_planning_bounds(y_bounds, -(y_bounds[1] - y_bounds[0]) * 0.1);
                state.message = "Panned planning board down".into();
            }
            MouseEventKind::ScrollLeft => {
                next_x = move_planning_bounds(x_bounds, -(x_bounds[1] - x_bounds[0]) * 0.1);
                state.message = "Panned planning board left".into();
            }
            MouseEventKind::ScrollRight => {
                next_x = move_planning_bounds(x_bounds, (x_bounds[1] - x_bounds[0]) * 0.1);
                state.message = "Panned planning board right".into();
            }
            _ => {}
        }
        state.planning_board_view = Some(PlanningBoardView {
            board_id: board,
            x_bounds: next_x,
            y_bounds: next_y,
        });
        return Ok(());
    }
    match mouse.kind {
        MouseEventKind::Down(MouseButton::Left) => {
            let Some((x, y)) =
                planning_canvas_to_world(area, x_bounds, y_bounds, mouse.column, mouse.row)
            else {
                return Ok(());
            };
            if let Some((index, item)) = items.iter().enumerate().rev().find(|(_, item)| {
                x >= item.x && x <= item.x + item.width && y >= item.y && y <= item.y + item.height
            }) {
                state.selected = index;
                state.planning_drag = Some(PlanningBoardDrag {
                    item_id: item.id,
                    origin: (item.x, item.y),
                    pointer_origin: (x, y),
                    x_bounds,
                    y_bounds,
                });
                state.message = format!("Selected {} planning card", item.entity_kind);
            }
        }
        MouseEventKind::Drag(MouseButton::Left) => {
            let Some(drag) = state.planning_drag.clone() else {
                return Ok(());
            };
            let Some((x, y)) = planning_canvas_to_world(
                area,
                drag.x_bounds,
                drag.y_bounds,
                mouse.column,
                mouse.row,
            ) else {
                return Ok(());
            };
            let position = (
                drag.origin.0 + x - drag.pointer_origin.0,
                drag.origin.1 + y - drag.pointer_origin.1,
            );
            state
                .app
                .move_planning_board_item(drag.item_id, position.0, position.1)?;
            if let Some(index) = state
                .app
                .list_planning_board_items(board)?
                .iter()
                .position(|item| item.id == drag.item_id)
            {
                state.selected = index;
            }
            state.message = format!(
                "Moved planning card to ({:.1}, {:.1})",
                position.0, position.1
            );
        }
        _ => {}
    }
    Ok(())
}

fn format_conflict_review(
    conflicts: &[story_import::MergeConflict],
    terminal_width: usize,
) -> String {
    let column_width = (terminal_width / 6).clamp(10, 28);
    let format_cell = |value: &str| {
        let text = value
            .lines()
            .next()
            .unwrap_or_default()
            .chars()
            .take(column_width.saturating_sub(1))
            .collect::<String>();
        format!("{text:<width$}", width = column_width)
    };
    let mut output = String::new();
    for (index, conflict) in conflicts.iter().enumerate() {
        output.push_str(&format!(
            "Conflict {} · base lines {}–{}\n",
            index + 1,
            conflict.base_start_line + 1,
            conflict.base_end_line.max(conflict.base_start_line + 1)
        ));
        output.push_str(&format!(
            "{} │ {} │ {}\n",
            format_cell("BASE"),
            format_cell("LOCAL"),
            format_cell("REVIEWED")
        ));
        let columns = [
            conflict.base.lines().collect::<Vec<_>>(),
            conflict.local.lines().collect::<Vec<_>>(),
            conflict.external.lines().collect::<Vec<_>>(),
        ];
        let row_count = columns.iter().map(Vec::len).max().unwrap_or_default();
        for row in 0..row_count {
            let cells = columns
                .iter()
                .map(|column| format_cell(column.get(row).copied().unwrap_or("")))
                .collect::<Vec<_>>();
            output.push_str(&format!("{} │ {} │ {}\n", cells[0], cells[1], cells[2]));
        }
        output.push('\n');
    }
    output
}

fn format_character_reference(character: &story_core::Character) -> String {
    let mut lines = vec![format!("# {}", character.full_name)];
    if character.preferred_name != character.full_name {
        lines.push(format!("Preferred name: {}", character.preferred_name));
    }
    if !character.aliases.is_empty() {
        lines.push(format!("Aliases: {}", character.aliases.join(", ")));
    }
    for (label, value) in [
        ("Status", character.status.as_str()),
        ("Description", character.description.as_str()),
        ("Background", character.background.as_str()),
        ("Goals", character.goals.as_str()),
        ("Motivations", character.motivations.as_str()),
        ("Secrets", character.secrets.as_str()),
        ("Internal conflict", character.internal_conflict.as_str()),
        ("External conflict", character.external_conflict.as_str()),
    ] {
        if !value.trim().is_empty() {
            lines.push(format!("\n## {label}\n{value}"));
        }
    }
    lines.join("\n")
}

fn proofreading_review_text(review: &ProofreadingReview) -> String {
    let mut lines = review
        .findings
        .iter()
        .map(|finding| {
            let marker = match finding.status {
                ProofreadingActionStatus::Pending => "○",
                ProofreadingActionStatus::Accepted => "✓",
                ProofreadingActionStatus::Ignored => "–",
            };
            let suggestion = finding
                .suggestion
                .as_ref()
                .map(|value| format!(" · Suggestion: {value}"))
                .unwrap_or_default();
            format!(
                "{marker} {} [{}] bytes {}..{} · {}: {}{}",
                finding.scene_title,
                finding.language,
                finding.byte_range.start,
                finding.byte_range.end,
                finding.category,
                finding.message,
                suggestion
            )
        })
        .collect::<Vec<_>>();
    if lines.is_empty() {
        lines.push("No grammar suggestions found.".into());
    }
    if !review.notes.is_empty() {
        lines.push(String::new());
        lines.push("Grammar checking notes:".into());
        lines.extend(review.notes.iter().cloned());
    }
    lines.push(String::new());
    lines.push(
        "↑/↓ Select finding · A Apply suggestion · I Ignore once · Esc Return to manuscript".into(),
    );
    lines.join("\n")
}

fn format_scene_card(record: &story_storage::SceneRecord) -> String {
    format!(
        "Scene: {}\nStatus: {:?}\nWords: {}{}\nPOV: {}\n\nSynopsis\n{}\n\nPurpose\n{}\n\nGoal\n{}\n\nOutcome\n{}",
        record.scene.title,
        record.scene.status,
        record.actual_words,
        record
            .scene
            .target_words
            .map(|target| format!(" / {target} target"))
            .unwrap_or_default(),
        record
            .scene
            .pov_character
            .map(|id| id.to_string())
            .unwrap_or_else(|| "—".into()),
        record.scene.synopsis,
        record.scene.purpose,
        record.scene.goal,
        record.scene.outcome,
    )
}

fn outline_reference_text(app: &WriterApp) -> Result<String, Box<dyn std::error::Error>> {
    let nodes = app.list_structural_nodes()?;
    let scenes = app.list_scenes(false)?;
    let mut output = String::new();
    for node in nodes.iter().filter(|node| node.kind == "section") {
        output.push_str(&format!("{}\n", node.title));
        for chapter in nodes
            .iter()
            .filter(|chapter| chapter.parent_id == Some(node.id))
        {
            output.push_str(&format!("  {}\n", chapter.title));
            for scene in scenes
                .iter()
                .filter(|scene| scene.chapter_id == Some(chapter.id))
            {
                output.push_str(&format!(
                    "    {}  [{}]\n",
                    scene.scene.title, scene.scene.id
                ));
            }
        }
    }
    for chapter in nodes
        .iter()
        .filter(|node| node.kind == "chapter" && node.parent_id.is_none())
    {
        output.push_str(&format!("{}\n", chapter.title));
        for scene in scenes
            .iter()
            .filter(|scene| scene.chapter_id == Some(chapter.id))
        {
            output.push_str(&format!("  {}  [{}]\n", scene.scene.title, scene.scene.id));
        }
    }
    if output.is_empty() {
        output.push_str("No structural outline entries yet.\n");
    }
    Ok(output)
}

fn timeline_reference_text(app: &WriterApp) -> String {
    timeline_items(app)
        .into_iter()
        .map(|item| match item {
            TimelineItem::Scene(scene) => format!(
                "Scene · {} → {} · {}  [{}]",
                format_story_interval(scene.scene.start_time),
                format_story_interval(scene.scene.end_time),
                scene.scene.title,
                scene.scene.id
            ),
            TimelineItem::Event(event) => format!(
                "Event · {} → {} · {} · {}  [{}]",
                format_story_interval(event.start),
                format_story_interval(event.end),
                event.title,
                event.source_time,
                event.id
            ),
        })
        .collect::<Vec<_>>()
        .join("\n")
}

fn search_reference_text(
    app: &WriterApp,
    terms: &str,
) -> Result<String, Box<dyn std::error::Error>> {
    let hits = app.search_project(terms, 200)?;
    if hits.is_empty() {
        return Ok(format!("No project matches for {terms:?}."));
    }
    Ok(hits
        .into_iter()
        .map(|hit| {
            format!(
                "{} · {}  [{}:{}]\n{}",
                hit.entity_kind, hit.title, hit.entity_kind, hit.entity_id, hit.excerpt
            )
        })
        .collect::<Vec<_>>()
        .join("\n\n"))
}

fn compile_diagnostics_reference_text(
    app: &WriterApp,
) -> Result<String, Box<dyn std::error::Error>> {
    let diagnostics = app.compile_diagnostics()?;
    if diagnostics.is_empty() {
        return Ok("No current compile diagnostics.".into());
    }
    Ok(diagnostics
        .into_iter()
        .enumerate()
        .map(|(index, item)| {
            format!(
                "{}. {} [{}] · {:?}{} · {}{}{}{}",
                index + 1,
                item.code,
                item.category,
                item.severity,
                if item.effective_or_original_level()
                    != match item.severity {
                        story_document::DiagnosticSeverity::Error =>
                            story_document::DiagnosticLevel::Error,
                        story_document::DiagnosticSeverity::Warning =>
                            story_document::DiagnosticLevel::Warning,
                        story_document::DiagnosticSeverity::Information =>
                            story_document::DiagnosticLevel::Information,
                    }
                {
                    format!(" promoted to {:?}", item.effective_or_original_level())
                } else {
                    String::new()
                },
                item.message,
                item.suppressed_by
                    .as_deref()
                    .map(|id| format!(" · suppressed by {id}"))
                    .unwrap_or_default(),
                item.source_entity_id
                    .map(|id| format!(" · source {id}"))
                    .unwrap_or_default(),
                item.source_range
                    .map(|range| format!(" · range {}..{}", range.start, range.end))
                    .unwrap_or_default()
            )
        })
        .collect::<Vec<_>>()
        .join("\n"))
}

fn parse_compile_range(line: &str) -> Option<story_document::SourceRange> {
    let (start, end) = line.split_once(" · range ")?.1.split_once("..")?;
    Some(story_document::SourceRange {
        start: start.parse().ok()?,
        end: end.split(':').next()?.parse().ok()?,
    })
}

fn latest_compile_output(app: &WriterApp) -> Result<PathBuf, Box<dyn std::error::Error>> {
    let supported = [
        "html", "htm", "epub", "docx", "pdf", "odt", "rtf", "txt", "md", "mobi", "azw3",
    ];
    let path = app
        .list_compile_results()?
        .into_iter()
        .find(|record| record.succeeded)
        .and_then(|record| {
            record.outputs.into_iter().find(|output| {
                let path = Path::new(output);
                path.extension()
                    .and_then(|extension| extension.to_str())
                    .map(|extension| supported.contains(&extension.to_ascii_lowercase().as_str()))
                    .unwrap_or(false)
                    && !output.ends_with(".source-map.json")
            })
        })
        .ok_or("No successful Compile result contains a previewable artifact")?;
    let path = PathBuf::from(path);
    let path = if path.is_absolute() {
        path
    } else {
        app.project_root().join(path)
    };
    if !path.is_file() {
        return Err(format!("Compile output is no longer available: {}", path.display()).into());
    }
    Ok(path)
}

fn open_with_system_viewer(path: &Path) -> Result<(), Box<dyn std::error::Error>> {
    #[cfg(target_os = "linux")]
    let commands: &[(&str, &[&str])] = &[("xdg-open", &[]), ("gio", &["open"])];
    #[cfg(target_os = "macos")]
    let commands: &[(&str, &[&str])] = &[("open", &[])];
    #[cfg(target_os = "windows")]
    let commands: &[(&str, &[&str])] = &[("explorer", &[])];
    #[cfg(not(any(target_os = "linux", target_os = "macos", target_os = "windows")))]
    let commands: &[(&str, &[&str])] = &[];

    let mut failures = Vec::new();
    for (program, prefix) in commands {
        let mut command = Command::new(program);
        command
            .args(*prefix)
            .arg(path)
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null());
        match command.spawn() {
            Ok(_) => return Ok(()),
            Err(error) => failures.push(format!("{program}: {error}")),
        }
    }
    Err(format!(
        "Could not launch a system viewer for {} ({})",
        path.display(),
        failures.join("; ")
    )
    .into())
}

fn compile_results_reference_text(
    app: &WriterApp,
    filter: &str,
) -> Result<String, Box<dyn std::error::Error>> {
    let filter = if filter.is_empty() { "all" } else { filter };
    if !matches!(
        filter,
        "all" | "errors" | "warnings" | "info" | "failed" | "success" | "stale" | "current"
    ) {
        return Err(
            "Compile Results filter must be all, errors, warnings, info, failed, success, stale, or current".into(),
        );
    }
    let records = app.list_compile_results()?;
    if records.is_empty() {
        return Ok("No Compile runs have been recorded.".into());
    }
    let records = records
        .into_iter()
        .filter(|record| match filter {
            "stale" => record.stale,
            "current" => !record.stale,
            "failed" => !record.succeeded,
            "success" => record.succeeded,
            "errors" => {
                record.error.is_some()
                    || record.diagnostics.iter().any(|item| {
                        item.effective_or_original_level() == story_document::DiagnosticLevel::Error
                    })
            }
            "warnings" => {
                !record.warnings.is_empty()
                    || record.diagnostics.iter().any(|item| {
                        item.effective_or_original_level()
                            == story_document::DiagnosticLevel::Warning
                    })
            }
            "info" => record.diagnostics.iter().any(|item| {
                item.effective_or_original_level() == story_document::DiagnosticLevel::Information
            }),
            _ => true,
        })
        .collect::<Vec<_>>();
    if records.is_empty() {
        return Ok(format!("No Compile results match the '{filter}' filter."));
    }
    let mut lines = Vec::new();
    for (index, record) in records.iter().enumerate() {
        lines.push(format!(
            "{}{}. {} · {} · {} · {} ms · run {}",
            if record.stale { "STALE " } else { "" },
            index + 1,
            record.configuration,
            record.format.as_deref().unwrap_or("unknown target"),
            if record.succeeded {
                "SUCCESS"
            } else {
                "FAILED"
            },
            record.elapsed_millis,
            record.created_unix_millis
        ));
        for output in &record.outputs {
            lines.push(format!("   Output: {output}"));
        }
        for diagnostic in &record.diagnostics {
            lines.push(format!(
                "   {}{:?}{} {} [{}]{}{}{}: {}",
                if record.stale { "STALE " } else { "" },
                diagnostic.severity,
                if diagnostic.effective_or_original_level()
                    != match diagnostic.severity {
                        story_document::DiagnosticSeverity::Error =>
                            story_document::DiagnosticLevel::Error,
                        story_document::DiagnosticSeverity::Warning =>
                            story_document::DiagnosticLevel::Warning,
                        story_document::DiagnosticSeverity::Information =>
                            story_document::DiagnosticLevel::Information,
                    }
                {
                    format!(
                        " promoted to {:?}",
                        diagnostic.effective_or_original_level()
                    )
                } else {
                    String::new()
                },
                diagnostic.code,
                diagnostic.category,
                diagnostic
                    .source_entity_id
                    .as_deref()
                    .map(|id| format!(" · source {id}"))
                    .unwrap_or_default(),
                diagnostic
                    .source_range
                    .map(|range| format!(" · range {}..{}", range.start, range.end))
                    .unwrap_or_default(),
                diagnostic
                    .generated_file
                    .as_deref()
                    .map(|file| {
                        format!(
                            " · generated {file}{}",
                            diagnostic
                                .generated_line
                                .map(|line| format!(":{line}"))
                                .unwrap_or_default()
                        )
                    })
                    .unwrap_or_default(),
                diagnostic.message
            ));
        }
        for warning in &record.warnings {
            if !record
                .diagnostics
                .iter()
                .any(|item| warning.starts_with(&format!("{}:", item.code)))
            {
                lines.push(format!("   Warning: {warning}"));
            }
        }
        if let Some(error) = &record.error {
            lines.push(format!("   Error: {error}"));
        }
    }
    Ok(lines.join("\n"))
}

fn encode_hex(value: &str) -> String {
    value
        .as_bytes()
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect()
}

fn decode_hex(value: &str) -> Option<String> {
    if !value.len().is_multiple_of(2) {
        return None;
    }
    let bytes = value
        .as_bytes()
        .chunks(2)
        .map(|pair| {
            let digit = |byte: u8| match byte {
                b'0'..=b'9' => Some(byte - b'0'),
                b'a'..=b'f' => Some(byte - b'a' + 10),
                b'A'..=b'F' => Some(byte - b'A' + 10),
                _ => None,
            };
            Some(digit(pair[0])? * 16 + digit(pair[1])?)
        })
        .collect::<Option<Vec<_>>>()?;
    String::from_utf8(bytes).ok()
}

fn format_location_reference(location: &story_core::Location) -> String {
    let mut lines = vec![format!("# {}", location.name)];
    if let Some(parent) = location.parent {
        lines.push(format!("Parent location: {parent}"));
    }
    if !location.description.trim().is_empty() {
        lines.push(format!("\n## Description\n{}", location.description));
    }
    lines.join("\n")
}

fn format_planning_board_markdown(
    title: &str,
    items: &[story_storage::PlanningBoardItemRecord],
) -> String {
    let escape = |value: &str| value.replace('|', "\\|").replace('\n', " ");
    let mut output = format!(
        "# {}\n\n| Entity | ID | X | Y | Width | Height | Note |\n|---|---|---:|---:|---:|---:|---|\n",
        escape(title)
    );
    for item in items {
        output.push_str(&format!(
            "| {} | {} | {} | {} | {} | {} | {} |\n",
            escape(&item.entity_kind),
            item.entity_id,
            item.x,
            item.y,
            item.width,
            item.height,
            escape(&item.note),
        ));
    }
    output
}

fn challenge_footer(
    challenge: &ActiveWritingChallenge,
    editor: &[String],
    policy: story_core::WordCountPolicy,
) -> String {
    let current_words = story_core::count_words_with_policy(&editor.join("\n"), policy);
    let written = current_words.saturating_sub(challenge.initial_words);
    let remaining = challenge
        .deadline
        .saturating_duration_since(Instant::now())
        .as_secs();
    if challenge.mode == "kamikaze" {
        let idle_remaining = challenge
            .kamikaze_idle_seconds
            .saturating_sub(challenge.last_activity.elapsed().as_secs());
        format!(
            "Challenge {remaining}s · {written}/{} words · {} grace pause(s) · kamikaze in {idle_remaining}s",
            challenge.target_words, challenge.grace_pauses_remaining
        )
    } else {
        format!(
            "Challenge {remaining}s · {written}/{} words · {} mode",
            challenge.target_words, challenge.mode
        )
    }
}

fn remove_last_words(source: &str, count: u32, policy: story_core::WordCountPolicy) -> String {
    let mut starts = Vec::new();
    match policy {
        story_core::WordCountPolicy::UnicodeWords => {
            let graphemes = source.graphemes(true).collect::<Vec<_>>();
            let mut start = graphemes.len();
            for _ in 0..count {
                while start > 0 && graphemes[start - 1].chars().all(char::is_whitespace) {
                    start -= 1;
                }
                let end = start;
                while start > 0 && !graphemes[start - 1].chars().all(char::is_whitespace) {
                    start -= 1;
                }
                if start == end {
                    break;
                }
            }
            let byte_start = graphemes.iter().take(start).map(|g| g.len()).sum::<usize>();
            return source[..byte_start].to_owned();
        }
        story_core::WordCountPolicy::UnspacedScriptGraphemes => {
            let mut other_run = String::new();
            let mut other_start = 0;
            for (byte, grapheme) in source.grapheme_indices(true) {
                if story_core::is_unspaced_script_grapheme(grapheme) {
                    starts.extend(
                        other_run
                            .unicode_word_indices()
                            .filter(|(_, segment)| segment.chars().any(char::is_alphanumeric))
                            .map(|(start, _)| other_start + start),
                    );
                    other_run.clear();
                    starts.push(byte);
                } else {
                    if other_run.is_empty() {
                        other_start = byte;
                    }
                    other_run.push_str(grapheme);
                }
            }
            starts.extend(
                other_run
                    .unicode_word_indices()
                    .filter(|(_, segment)| segment.chars().any(char::is_alphanumeric))
                    .map(|(start, _)| other_start + start),
            );
        }
    }
    let retained = starts.len().saturating_sub(count as usize);
    let cut = starts.get(retained).copied().unwrap_or(source.len());
    source[..cut].to_owned()
}

fn render_challenge_taunt(template: &str, words: u32, deleted: u32) -> String {
    template
        .replace("{words}", &words.to_string())
        .replace("{deleted}", &deleted.to_string())
}

fn parse_challenge_command(
    command: &str,
) -> Result<Option<ChallengeStart>, Box<dyn std::error::Error>> {
    let parsed = if let Some(rest) = command.strip_prefix("challenge-start ") {
        let mut parts = rest.split_whitespace();
        let target = parts
            .next()
            .ok_or("use challenge-start TARGET_WORDS DURATION_SECONDS [pressure|kamikaze]")?
            .parse::<u32>()?;
        let seconds = parts
            .next()
            .ok_or("missing challenge duration")?
            .parse::<u32>()?;
        let tail = parts.collect::<Vec<_>>();
        let (mode, destination) = parse_challenge_tail(&tail)?;
        (target, seconds, mode, destination)
    } else if let Some(rest) = command.strip_prefix("challenge-preset ") {
        let mut parts = rest.split_whitespace();
        let preset = parts
            .next()
            .ok_or("use challenge-preset short|standard|long [pressure|kamikaze]")?;
        let tail = parts.collect::<Vec<_>>();
        let (mode, destination) = parse_challenge_tail(&tail)?;
        let (target, seconds) = match preset {
            "short" => (250, 5 * 60),
            "standard" => (500, 10 * 60),
            "long" => (1_000, 30 * 60),
            _ => return Err("unknown challenge preset".into()),
        };
        (target, seconds, mode, destination)
    } else {
        return Ok(None);
    };
    if parsed.0 == 0 || parsed.1 == 0 {
        return Err(
            "challenge requires positive target/duration and mode pressure|kamikaze".into(),
        );
    }
    Ok(Some(ChallengeStart {
        target_words: parsed.0,
        duration_seconds: parsed.1,
        mode: parsed.2,
        destination_scene: parsed.3,
    }))
}

fn parse_challenge_tail(
    tail: &[&str],
) -> Result<(String, Option<SceneId>), Box<dyn std::error::Error>> {
    let mut index = 0;
    let mode = if tail
        .first()
        .is_some_and(|mode| matches!(*mode, "pressure" | "steady" | "kamikaze"))
    {
        index = 1;
        tail[0]
    } else {
        "pressure"
    };
    let destination_argument = tail.get(index);
    if tail.len() > index + usize::from(destination_argument.is_some()) {
        return Err("too many challenge options".into());
    }
    let destination = destination_argument
        .map(|item| {
            let id = item
                .strip_prefix("scene=")
                .ok_or("challenge option must use scene=UUID")?;
            Ok::<SceneId, Box<dyn std::error::Error>>(SceneId(uuid::Uuid::parse_str(id)?))
        })
        .transpose()?;
    Ok((mode.to_owned(), destination))
}

fn draw_menu_overlay(f: &mut ratatui::Frame<'_>, s: &AppState) {
    let area = f.area();
    let menu = s.menu.unwrap_or(MenuState {
        top: 0,
        selected: 0,
    });
    let entries = s.menu_visible_entries();
    let popup = menu_dropdown_rect(area, s, menu, entries.len());
    if popup.width == 0 || popup.height == 0 {
        return;
    }
    f.render_widget(Clear, popup);
    let title = format!(" {} · {} ", MENU_CATEGORIES[menu.top], "actions");
    let block = Block::default()
        .title(title)
        .borders(Borders::ALL)
        .border_style(Style::default().fg(Color::Cyan));
    let inner = block.inner(popup);
    f.render_widget(block, popup);
    let row_width = inner.width.saturating_sub(2) as usize;
    let items = if entries.is_empty() {
        vec![ListItem::new("No commands available yet").style(Style::default().fg(Color::DarkGray))]
    } else {
        entries
            .iter()
            .map(|command| {
                let disabled = s.command_disabled_reason(*command);
                let label = menu_command_row(s, *command, row_width);
                ListItem::new(label).style(if disabled.is_some() {
                    Style::default().fg(Color::DarkGray)
                } else {
                    Style::default()
                })
            })
            .collect()
    };
    let selected = if entries.is_empty() {
        None
    } else {
        Some(menu.selected.min(entries.len() - 1))
    };
    let selected_reason = entries
        .get(menu.selected.min(entries.len().saturating_sub(1)))
        .and_then(|command| s.command_disabled_reason(*command));
    let (command_list_area, description_area) = if selected_reason.is_some() && inner.height >= 6 {
        let split = Layout::default()
            .direction(Direction::Vertical)
            .constraints([Constraint::Min(3), Constraint::Length(2)])
            .split(inner);
        (split[0], Some(split[1]))
    } else {
        (inner, None)
    };
    f.render_stateful_widget(
        List::new(items)
            .highlight_symbol("▸ ")
            .highlight_style(Style::default().bg(Color::Blue).fg(Color::White))
            .block(
                Block::default()
                    .title("↑/↓ choose · Enter run · Left/Right menu · Esc close")
                    .borders(Borders::NONE),
            ),
        command_list_area,
        &mut ListState::default().with_selected(selected),
    );
    if let Some(description_area) = description_area {
        let detail =
            selected_reason.map_or_else(String::new, |reason| format!("Unavailable: {reason}"));
        f.render_widget(
            Paragraph::new(detail).wrap(Wrap { trim: true }),
            description_area,
        );
    }
}

fn menu_command_row(state: &AppState, command: CommandSpec, width: usize) -> String {
    if width == 0 {
        return String::new();
    }
    let mnemonic = command
        .mnemonic
        .map(|key| format!(" [{key}]"))
        .unwrap_or_default();
    let arguments = if command.takes_arguments { " …" } else { "" };
    let label = format!(
        "{}{}{}",
        displayed_command_label(state, command),
        mnemonic,
        arguments
    );
    let mut shortcuts = effective_command_shortcuts(state, command);
    if command.id == "scene.toggle-inclusion" && shortcuts.is_empty() {
        shortcuts.push("Space".into());
    }
    let shortcut = match shortcuts.as_slice() {
        [] => String::new(),
        [single] => format!(" ({single})"),
        [first, rest @ ..] => format!(" ({first} +{})", rest.len()),
    };

    let shortcut_width = UnicodeWidthStr::width(shortcut.as_str());
    let (label, shortcut) = if shortcut_width < width {
        let label_width = width - shortcut_width;
        (truncate_display_cells(&label, label_width), shortcut)
    } else {
        (truncate_display_cells(&label, width), String::new())
    };
    format!("{label}{shortcut}")
}

fn displayed_command_label(state: &AppState, command: CommandSpec) -> String {
    if command.id == "view.formatting-marks" {
        return if state.editor_preferences.show_formatting_marks {
            "Hide Formatting Marks".into()
        } else {
            "Show Formatting Marks".into()
        };
    }
    if command.id == "command.palette-open" {
        return "Search All Commands…".into();
    }
    if command.id == "view.rendered-markdown" {
        return if state.editor_preferences.rendered_markdown {
            "Show Markdown Source".into()
        } else {
            "Show Rendered Markdown".into()
        };
    }
    if command.id == "window.maximize"
        && (state.editor_focus_mode || state.restore_pane_layout.is_some())
    {
        return "Restore Windows".into();
    }
    if command.id != "help.resume-tutorial" {
        return command.label.to_owned();
    }
    match onboarding::load(&state.tutorial_preferences_path) {
        Ok(preferences) if preferences.active_tutorial.is_some() => "Resume Tutorial".into(),
        Ok(preferences) if preferences.tutorial_completed => "Restart Tutorial".into(),
        _ => "Start Tutorial".into(),
    }
}

fn truncate_display_cells(text: &str, max_width: usize) -> String {
    if UnicodeWidthStr::width(text) <= max_width {
        return text.to_owned();
    }
    if max_width == 0 {
        return String::new();
    }
    let ellipsis = "…";
    let content_width = max_width.saturating_sub(UnicodeWidthStr::width(ellipsis));
    let mut width = 0;
    let mut result = String::new();
    for grapheme in text.graphemes(true) {
        let grapheme_width = UnicodeWidthStr::width(grapheme);
        if width + grapheme_width > content_width {
            break;
        }
        result.push_str(grapheme);
        width += grapheme_width;
    }
    if UnicodeWidthStr::width(ellipsis) <= max_width {
        result.push_str(ellipsis);
    } else {
        for character in text.chars() {
            let character_width = character.width().unwrap_or(0);
            if UnicodeWidthStr::width(result.as_str()) + character_width > max_width {
                break;
            }
            result.push(character);
        }
    }
    result
}

fn draw_command_palette_overlay(f: &mut ratatui::Frame<'_>, s: &AppState) {
    let Some(palette) = s.command_palette.as_ref() else {
        return;
    };
    let area = f.area();
    if area.width == 0 || area.height == 0 {
        return;
    }
    let width = area.width.clamp(1, 88);
    let height = area.height.clamp(1, 18);
    let popup = Rect {
        x: area.x + area.width.saturating_sub(width) / 2,
        y: area.y + area.height.saturating_sub(height) / 3,
        width,
        height,
    };
    f.render_widget(Clear, popup);
    let block = Block::default()
        .title(if palette.view_only && palette.query.trim().is_empty() {
            " Switch View · recent views first · Esc returns "
        } else if palette.view_only {
            " Switch View · search available views · Esc returns "
        } else if palette.query.trim().is_empty() && !palette.recent_commands.is_empty() {
            " Command Palette · recent actions first · Esc closes "
        } else {
            " Command Palette · search actions · Esc closes "
        })
        .borders(Borders::ALL)
        .border_style(Style::default().fg(Color::Cyan));
    let inner = block.inner(popup);
    f.render_widget(block, popup);
    let rows = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(1),
            Constraint::Min(1),
            Constraint::Length(1),
        ])
        .split(inner);
    f.render_widget(
        Paragraph::new(format!(
            "{} > {}",
            if palette.view_only {
                "Switch View"
            } else {
                "Search"
            },
            palette.query
        ))
        .style(
            Style::default()
                .fg(Color::Yellow)
                .add_modifier(Modifier::BOLD),
        ),
        rows[0],
    );
    let candidates = scoped_palette_candidates(palette);
    let items = if candidates.is_empty() {
        vec![ListItem::new("No registered command matches this search")]
    } else {
        candidates
            .iter()
            .map(|command| {
                let disabled = s.command_disabled_reason(*command);
                let shortcut = effective_command_shortcuts(s, *command);
                let shortcut = if shortcut.is_empty() {
                    String::new()
                } else {
                    format!(" · {}", shortcut.join(", "))
                };
                let availability =
                    disabled.map_or(String::new(), |reason| format!(" · unavailable: {reason}"));
                ListItem::new(format!("{}{}{}", command.label, shortcut, availability)).style(
                    if disabled.is_some() {
                        Style::default().fg(Color::DarkGray)
                    } else {
                        Style::default()
                    },
                )
            })
            .collect()
    };
    let selected = (!candidates.is_empty())
        .then_some(palette.selected.min(candidates.len().saturating_sub(1)));
    f.render_stateful_widget(
        List::new(items)
            .highlight_symbol("▸ ")
            .highlight_style(Style::default().bg(Color::Blue).fg(Color::White)),
        rows[1],
        &mut ListState::default().with_selected(selected),
    );
    let description = candidates
        .get(palette.selected.min(candidates.len().saturating_sub(1)))
        .map_or_else(
            || {
                "Type to search registered commands · Enter runs · Tab prepares arguments"
                    .to_owned()
            },
            |command| {
                s.command_disabled_reason(*command)
                    .map_or(command.description.to_owned(), |reason| {
                        format!("Unavailable: {reason} · {}", command.description)
                    })
            },
        );
    f.render_widget(
        Paragraph::new(description).wrap(Wrap { trim: true }),
        rows[2],
    );
}

fn draw_recent_project_picker_overlay(f: &mut ratatui::Frame<'_>, state: &AppState) {
    let Some(picker) = state.recent_project_picker.as_ref() else {
        return;
    };
    let area = f.area();
    if area.width < 4 || area.height < 3 {
        return;
    }
    let width = area.width.saturating_sub(4).clamp(1, 92);
    let height = (picker.paths.len() as u16)
        .saturating_add(4)
        .min(area.height.saturating_sub(2));
    let popup = Rect {
        x: area.x + area.width.saturating_sub(width) / 2,
        y: area.y + area.height.saturating_sub(height) / 3,
        width,
        height,
    };
    f.render_widget(Clear, popup);
    let block = Block::default()
        .title(" Recent Projects · ↑/↓ choose · Enter open · Esc close ")
        .borders(Borders::ALL)
        .border_style(Style::default().fg(Color::Cyan));
    let inner = block.inner(popup);
    f.render_widget(block, popup);
    let items = picker
        .paths
        .iter()
        .map(|path| {
            let availability = if path.join("project.toml").is_file() {
                ""
            } else {
                "  · unavailable"
            };
            ListItem::new(truncate_display_cells(
                &format!("{}{}", path.display(), availability),
                inner.width as usize,
            ))
            .style(if availability.is_empty() {
                Style::default()
            } else {
                Style::default().fg(Color::DarkGray)
            })
        })
        .collect::<Vec<_>>();
    let selected =
        (!items.is_empty()).then_some(picker.selected.min(items.len().saturating_sub(1)));
    f.render_stateful_widget(
        List::new(items)
            .highlight_symbol("▸ ")
            .highlight_style(Style::default().bg(Color::Blue).fg(Color::White)),
        inner,
        &mut ListState::default().with_selected(selected),
    );
}

