fn draw_structural_node_removal_overlay(f: &mut ratatui::Frame<'_>, s: &AppState) {
    let Some(dialog) = &s.pending_structural_node_removal else {
        return;
    };
    let area = f.area();
    let width = area.width.saturating_sub(4).clamp(1, 78);
    // The lifecycle dialogue includes both the object counts and the compile
    // consequences. Keep enough room for wrapped text at the standard 80x24
    // terminal size so the final action instructions cannot disappear below
    // the border.
    let height = if dialog.content_unit_count > 0 {
        19
    } else {
        16
    }
    .min(area.height.max(1));
    let rect = Rect::new(
        area.x + (area.width - width) / 2,
        area.y + (area.height - height) / 2,
        width,
        height,
    );
    f.render_widget(Clear, rect);
    let mut lines = vec![Line::from(truncate_display_cells(
        &format!("{}: {}", dialog.kind, dialog.title),
        width.saturating_sub(4) as usize,
    ))];
    if dialog.restoring {
        lines.push(Line::from(
            "Restore its original hierarchy, ordering and identity?",
        ));
        lines.push(Line::from(
            "Any moved scenes must still be where this removal placed them.",
        ));
        lines.push(Line::from("Enter restores · Esc cancels"));
    } else {
        lines.push(Line::from(format!(
            "Contains {} scene(s), {} scene words, {} prose document(s), {} prose words.",
            dialog.scene_count,
            dialog.scene_words,
            dialog.content_unit_count,
            dialog.content_unit_words
        )));
        if dialog.scene_count > 0 {
            lines.push(Line::from(format!(
                "Compile impact: {} included, {} excluded scene(s).",
                dialog.included_scene_count, dialog.excluded_scene_count
            )));
        }
        if dialog.descendant_nodes > 0 {
            lines.push(Line::from(format!(
                "Also contains {} subordinate heading(s).",
                dialog.descendant_nodes
            )));
        }
        if dialog.kind == "section" && dialog.owned_content_unit_count > 0 {
            lines.push(Line::from(format!(
                "Direct heading prose: {} document(s), {} words.",
                dialog.owned_content_unit_count, dialog.owned_content_unit_words
            )));
        }
        if dialog.can_rehome_scenes {
            lines.push(Line::from(if dialog.scene_count == 0 {
                "Choose how to handle the chapter prose:"
            } else {
                "Choose how to handle the chapter:"
            }));
            if dialog.scene_count == 0 {
                lines.push(Line::from(format!(
                    "{} Keep prose in another chapter… {}",
                    if dialog.choice == 0 { ">" } else { " " },
                    dialog
                        .target_chapters
                        .get(dialog.target_index)
                        .and_then(|target| s
                            .app
                            .list_structural_nodes()
                            .ok()?
                            .into_iter()
                            .find(|node| node.id == *target)
                            .map(|node| node.title))
                        .unwrap_or_else(|| "No destination chapter".into())
                )));
                lines.push(Line::from(format!(
                    "{} Move prose to Removed Documents",
                    if dialog.choice == 1 { ">" } else { " " }
                )));
            } else {
                lines.push(Line::from(format!(
                    "{} Move scenes to Unplaced",
                    if dialog.choice == 0 { ">" } else { " " }
                )));
                lines.push(Line::from(format!(
                    "{} Move scenes to another chapter… {}",
                    if dialog.choice == 1 { ">" } else { " " },
                    dialog
                        .target_chapters
                        .get(dialog.target_index)
                        .and_then(|target| s
                            .app
                            .list_structural_nodes()
                            .ok()?
                            .into_iter()
                            .find(|node| node.id == *target)
                            .map(|node| node.title))
                        .unwrap_or_else(|| "No destination chapter".into())
                )));
            }
            lines.push(Line::from(format!(
                "{} Delete chapter and all its contents recoverably",
                if dialog.choice == 2 { ">" } else { " " }
            )));
            lines.push(Line::from(
                if dialog.content_unit_count > 0 && dialog.choice == 2 {
                    "The chapter prose stays recoverable with the removed chapter."
                } else if dialog.scene_count == 0 && dialog.choice == 1 {
                    "Chapter prose moves to Removed Documents and is omitted from Compile."
                } else if dialog.content_unit_count > 0 && dialog.keep_chapter_prose {
                    "Chapter prose moves to the selected chapter and stays in Compile."
                } else if dialog.content_unit_count > 0 {
                    "Chapter prose moves to Removed Documents and is omitted from Compile."
                } else {
                    "Unplaced scenes are omitted from Compile. Delete retains the full subtree in Removed Documents."
                },
            ));
            lines.push(Line::from(if dialog.scene_count == 0 {
                match dialog.choice {
                    0 => "Compile: chapter prose moves to the selected chapter and remains included.",
                    1 => "Compile: prose moves to Removed Documents and is omitted; it can be restored.",
                    _ => "Compile: removed chapter prose is omitted; the removal can be restored.",
                }
            } else {
                match dialog.choice {
                0 => "Compile: included scenes become Unplaced and are omitted until placed in a chapter.",
                1 => "Compile: included scenes append to the selected chapter in their current order.",
                _ => "Compile: removed scenes and chapter prose are omitted; the removal can be restored.",
                }
            }));
            if dialog.content_unit_count > 0 {
                let prose_destination = dialog
                    .target_chapters
                    .get(dialog.target_index)
                    .and_then(|target| {
                        s.app
                            .list_structural_nodes()
                            .ok()?
                            .into_iter()
                            .find(|node| node.id == *target)
                            .map(|node| node.title)
                    })
                    .unwrap_or_else(|| "no active destination".into());
                lines.push(Line::from(if dialog.choice == 2 {
                    "Prose: retained with the recoverable chapter; Restore returns it".into()
                } else if dialog.scene_count == 0 && dialog.choice == 1 {
                    "Prose: moved to Removed Documents; Restore returns it".into()
                } else if dialog.keep_chapter_prose {
                    format!(
                        "Prose: keep in ‘{}’ · P moves it to Removed Documents",
                        prose_destination
                    )
                } else {
                    "Prose: move to Removed Documents (recoverable) · P keeps it active".into()
                }));
                if dialog.scene_count > 0 || dialog.choice == 0 {
                    lines.push(Line::from(
                        "Left/Right changes the selected chapter for scenes and prose.",
                    ));
                }
            }
            lines.push(Line::from("Up/Down choose · Enter confirm · Esc cancel"));
        } else if dialog.can_promote_children {
            lines.push(Line::from("Choose how to handle this non-fiction section:"));
            lines.push(Line::from(format!(
                "{} Promote child sections to the current parent level",
                if dialog.choice == 0 { ">" } else { " " }
            )));
            lines.push(Line::from(format!(
                "{} Move child sections to another section… {}",
                if dialog.choice == 1 { ">" } else { " " },
                dialog
                    .target_sections
                    .get(dialog.target_section_index)
                    .and_then(|target| s
                        .app
                        .list_structural_nodes()
                        .ok()?
                        .into_iter()
                        .find(|node| node.id == *target)
                        .map(|node| node.title))
                    .unwrap_or_else(|| "No compatible destination".into())
            )));
            lines.push(Line::from(format!(
                "{} Delete the whole subtree recoverably",
                if dialog.choice == 2 { ">" } else { " " }
            )));
            lines.push(Line::from(
                "Child order and IDs are preserved. The removed heading is recoverable.",
            ));
            if dialog.owned_content_unit_count > 0 {
                let prose_destination = dialog
                    .target_prose_sections
                    .get(dialog.target_prose_section_index)
                    .and_then(|target| {
                        s.app
                            .list_structural_nodes()
                            .ok()?
                            .into_iter()
                            .find(|node| node.id == *target)
                            .map(|node| node.title)
                    })
                    .unwrap_or_else(|| "no compatible section".into());
                lines.push(Line::from(if dialog.choice == 2 {
                    "Owned prose stays with the recoverable heading. Restore returns it.".into()
                } else if dialog.keep_section_prose {
                    format!(
                        "Prose: keep in ‘{}’ and in Compile · Shift+Left/Right changes destination · P archives it",
                        prose_destination
                    )
                } else {
                    "Prose: move to Removed Documents (recoverable) · P keeps it active".into()
                }));
            }
            lines.push(Line::from(match dialog.choice {
                0 => "Compile order may change as child headings move to the current parent level.",
                1 => "Compile order may change as child headings move to the selected section.",
                _ => "Compile: this subtree and its prose are omitted until restored.",
            }));
            lines.push(Line::from(
                "Up/Down choose · Left/Right destination · Enter confirm · Esc cancel",
            ));
        } else if dialog.can_rehome_section_prose {
            let destination = dialog
                .target_prose_sections
                .get(dialog.target_prose_section_index)
                .and_then(|target| {
                    s.app
                        .list_structural_nodes()
                        .ok()?
                        .into_iter()
                        .find(|node| node.id == *target)
                        .map(|node| node.title)
                })
                .unwrap_or_else(|| "No compatible section".into());
            lines.push(Line::from("Choose how to handle this section's prose:"));
            lines.push(Line::from(format!(
                "{} Keep prose in ‘{}’ · remains in Compile",
                if dialog.choice == 0 { ">" } else { " " },
                destination
            )));
            lines.push(Line::from(format!(
                "{} Move prose to Removed Documents",
                if dialog.choice == 1 { ">" } else { " " }
            )));
            lines.push(Line::from(
                "Prose document IDs, text and ordering are preserved. The heading is recoverable.",
            ));
            lines.push(Line::from(
                "Up/Down choose · Left/Right destination · Enter confirm · Esc cancel",
            ));
        } else {
            lines.push(Line::from(
                "The entire heading subtree, scenes and prose will be retained in Removed Documents.",
            ));
            lines.push(Line::from(
                "This changes manuscript inclusion and Compile output.",
            ));
            lines.push(Line::from("Enter removes recoverably · Esc cancels"));
        }
    }
    let text = Text::from(lines);
    f.render_widget(
        Paragraph::new(text).wrap(Wrap { trim: true }).block(
            Block::default()
                .title(if dialog.restoring {
                    " Restore Outline Heading "
                } else if dialog.can_rehome_scenes {
                    " Delete Chapter · Keep or Move Content "
                } else {
                    " Delete Heading and Contents "
                })
                .borders(Borders::ALL),
        ),
        rect,
    );
}

fn book_type_label(book_type: story_core::BookType) -> &'static str {
    match book_type {
        story_core::BookType::Fiction => "Fiction",
        story_core::BookType::Nonfiction => "Non-fiction",
        story_core::BookType::Custom => "Custom",
    }
}

fn draw_book_type_dialog(f: &mut ratatui::Frame<'_>, book_type: story_core::BookType) {
    let outer = f.area();
    let width = 44.min(outer.width.saturating_sub(2));
    let height = 9.min(outer.height.saturating_sub(2));
    let area = Rect {
        x: outer.x + outer.width.saturating_sub(width) / 2,
        y: outer.y + outer.height.saturating_sub(height) / 2,
        width,
        height,
    };
    f.render_widget(Clear, area);
    let choices = [
        story_core::BookType::Fiction,
        story_core::BookType::Nonfiction,
        story_core::BookType::Custom,
    ];
    let lines = choices
        .iter()
        .map(|choice| {
            format!(
                "{} {}",
                if *choice == book_type { "›" } else { " " },
                book_type_label(*choice)
            )
        })
        .collect::<Vec<_>>();
    let content = std::iter::once("Choose the kind of book this project contains".to_owned())
        .chain(std::iter::once(String::new()))
        .chain(lines)
        .chain(std::iter::once(String::new()))
        .chain(std::iter::once(
            "↑/↓ Choose · Enter Apply · Esc Cancel".to_owned(),
        ))
        .collect::<Vec<_>>()
        .join("\n");
    let block = Block::default()
        .title(" Book Type ")
        .borders(Borders::ALL)
        .border_style(Style::default().fg(Color::Cyan));
    f.render_widget(Paragraph::new(content).block(block), area);
}

