    #[test]
    fn nonfiction_outline_reorders_chapters_through_visible_outline_menu_actions() {
        let root = tempfile::tempdir().unwrap();
        let mut app = WriterApp::create_project_with_type(
            root.path().join("Book"),
            "Book",
            story_core::BookType::Nonfiction,
        )
        .unwrap();
        let section = app.create_section("Part One", 0).unwrap();
        let first = app.create_chapter(Some(section), "First", 0).unwrap();
        let second = app.create_chapter(Some(section), "Second", 1).unwrap();
        let prose = app
            .create_content_unit(
                story_core::ContentUnitKind::ChapterBody,
                "First prose",
                Some(first),
                0,
                None,
            )
            .unwrap();
        let (_, hash) = app.load_content_unit_text(prose).unwrap();
        app.save_content_unit_text(prose, Some(&hash), "Prose follows the chapter.")
            .unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.workspace = Workspace::Outline;
        let rows = outline_rows(&state);
        state.selected = rows
            .iter()
            .position(|row| matches!(row, OutlineRow::Chapter { id, .. } if *id == first))
            .unwrap();

        let outline_menu = MENU_CATEGORIES
            .iter()
            .position(|category| *category == "Outline")
            .unwrap();
        state.menu = Some(MenuState {
            top: outline_menu,
            selected: 0,
        });
        let visible = state
            .menu_visible_entries()
            .into_iter()
            .map(|command| command.id)
            .collect::<Vec<_>>();
        assert!(visible.contains(&"outline.move-up"));
        assert!(visible.contains(&"outline.move-down"));
        state.menu.as_mut().unwrap().selected = visible
            .iter()
            .position(|command| *command == "outline.move-down")
            .unwrap();
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE),
        )
        .unwrap();

        let mut siblings = state
            .app
            .list_structural_nodes()
            .unwrap()
            .into_iter()
            .filter(|node| node.parent_id == Some(section) && node.kind == "chapter")
            .collect::<Vec<_>>();
        siblings.sort_by_key(|node| node.position);
        assert_eq!(
            siblings.iter().map(|node| node.id).collect::<Vec<_>>(),
            [second, first]
        );
        assert_eq!(
            state.app.load_content_unit_text(prose).unwrap().0,
            "Prose follows the chapter."
        );
        assert_eq!(state.app.list_scenes(false).unwrap().len(), 0);
        assert!(
            state
                .command_disabled_reason(command_by_id("outline.move-down").unwrap())
                .is_some()
        );

        state.save_session().unwrap();
        drop(state);
        let reopened = WriterApp::open_project(root.path().join("Book")).unwrap();
        let mut siblings = reopened
            .list_structural_nodes()
            .unwrap()
            .into_iter()
            .filter(|node| node.parent_id == Some(section) && node.kind == "chapter")
            .collect::<Vec<_>>();
        siblings.sort_by_key(|node| node.position);
        assert_eq!(
            siblings.iter().map(|node| node.id).collect::<Vec<_>>(),
            [second, first]
        );
        assert_eq!(
            reopened.load_content_unit_text(prose).unwrap().0,
            "Prose follows the chapter."
        );
    }

    #[test]
    fn git_recovery_command_restores_archived_scene_as_new_and_is_registered() {
        let root = tempfile::tempdir().unwrap();
        let app = WriterApp::create_project(root.path().join("Book"), "Book").unwrap();
        let mut state = AppState::new(app, default_bindings());
        let chapter = state.app.create_chapter(None, "Chapter", 0).unwrap();
        let original = state.app.create_scene(chapter, "Missing", 0).unwrap();
        let (_, hash) = state.app.load_scene_text(original).unwrap();
        state
            .app
            .save_scene_text(original, Some(&hash), "Recovered prose.")
            .unwrap();
        let commit = state.app.git_snapshot("Before archive").unwrap().unwrap();
        state.app.archive_scene(original).unwrap();
        assert!(
            command_registry()
                .iter()
                .any(|command| command.id == "git.restore-deleted-scene"
                    && command.category == "File")
        );
        state
            .execute_legacy_palette_command(&format!(
                "git-restore-scene-new {commit} {original} {chapter} 0"
            ))
            .unwrap();
        let active = state.app.list_scenes(false).unwrap();
        assert_eq!(active.len(), 1);
        assert_ne!(active[0].scene.id, original);
        assert_eq!(
            state.app.load_scene_text(active[0].scene.id).unwrap().0,
            "Recovered prose."
        );
        assert!(
            state
                .message
                .contains("review its character, plot and event relationships")
        );
    }

