    fn select_series_menu_action(
        state: &mut AppState,
        command_id: &str,
    ) -> Result<(), Box<dyn std::error::Error>> {
        let top = MENU_CATEGORIES
            .iter()
            .position(|category| *category == "File")
            .ok_or("File menu category is missing")?;
        state.menu = Some(MenuState { top, selected: 0 });
        command_by_id(command_id).ok_or("Series command is not registered")?;
        let direct = state
            .menu_visible_entries()
            .iter()
            .position(|spec| spec.id == command_id);
        if let Some(selected) = direct {
            state.menu.as_mut().unwrap().selected = selected;
            state.handle_menu_key(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE))?;
        } else {
            let search = state
                .menu_visible_entries()
                .iter()
                .position(|spec| spec.id == "command.palette-open")
                .ok_or("File menu has no Search All Commands action")?;
            state.menu.as_mut().unwrap().selected = search;
            state.handle_menu_key(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE))?;
            let palette = state
                .command_palette
                .as_mut()
                .ok_or("command search did not open")?;
            palette.query = command_id.into();
            let candidates =
                command_palette_candidates_with_history(&palette.query, &palette.recent_commands);
            palette.selected = candidates
                .iter()
                .position(|spec| spec.id == command_id)
                .ok_or("command is not discoverable through Search All Commands")?;
            handle_command_palette_key(state, KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE))?;
        }
        Ok(())
    }

    fn enter_series_form_values(
        state: &mut AppState,
        values: &[&str],
    ) -> Result<(), Box<dyn std::error::Error>> {
        for value in values {
            for character in value.chars() {
                handle(
                    state,
                    KeyEvent::new(KeyCode::Char(character), KeyModifiers::NONE),
                )?;
            }
            handle(state, KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE))?;
        }
        Ok(())
    }

    #[test]
    fn sanitized_scrivener_series_wizard_previews_maps_and_imports_without_touching_source() {
        let fixture = Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("../cli/tests/fixtures/scrivener-windows-311/Windows Regression.scriv");
        let root = tempfile::tempdir().unwrap();
        let series_root = root.path().join("Series");
        let initial = WriterApp::create_project(root.path().join("Initial"), "Initial").unwrap();
        let mut state = AppState::new(initial, default_bindings());
        select_series_menu_action(&mut state, "series.create").unwrap();
        enter_series_form_values(&mut state, &[series_root.to_str().unwrap(), "Series"]).unwrap();
        assert_eq!(
            state.selected_series_root.as_deref(),
            Some(series_root.as_path())
        );
        let source_before = story_import::inspect_scrivener_project(&fixture)
            .unwrap()
            .source_fingerprint;
        state
            .start_scrivener_import(fixture.clone(), "Book-01".into(), "Book One".into())
            .unwrap();
        assert_eq!(state.workspace, Workspace::Series);
        assert!(!workspace_items(&state).is_empty());
        assert!(state.scrivener_import.is_some());

        use story_import::ScrivenerDestinationKind as Kind;
        let mapping_items = state
            .scrivener_import
            .as_ref()
            .unwrap()
            .inventory
            .items
            .iter()
            .map(|item| {
                (
                    item.source_document_id.clone(),
                    item.type_code.clone(),
                    item.area.clone(),
                )
            })
            .collect::<Vec<_>>();
        for (source_document_id, type_code, area) in mapping_items {
            let decision = state
                .scrivener_import
                .as_mut()
                .unwrap()
                .plan
                .decisions
                .iter_mut()
                .find(|decision| decision.source_document_id == source_document_id)
                .unwrap();
            match type_code.as_deref() {
                Some("DraftFolder") => decision.destination_kind = Kind::Unmapped,
                Some("Text") if area == "manuscript" => {
                    decision.destination_kind = Kind::Scene;
                }
                Some("ResearchFolder") => decision.destination_kind = Kind::Research,
                _ => {
                    decision.destination_kind = Kind::Skip;
                    decision.include_in_import = false;
                }
            }
        }
        let draft_index = state
            .scrivener_import
            .as_ref()
            .unwrap()
            .inventory
            .items
            .iter()
            .position(|item| item.type_code.as_deref() == Some("DraftFolder"))
            .unwrap();
        state.selected = draft_index;
        while state.scrivener_import.as_ref().unwrap().plan.decisions[draft_index].destination_kind
            != Kind::Chapter
        {
            handle(
                &mut state,
                KeyEvent::new(KeyCode::Right, KeyModifiers::NONE),
            )
            .unwrap();
        }
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Enter, KeyModifiers::CONTROL),
        )
        .unwrap();
        assert!(state.scrivener_import.is_none());
        assert_eq!(state.app.get_project().unwrap().title, "Book One");
        assert_eq!(state.app.list_scenes(false).unwrap().len(), 1);
        let scene = state.app.list_scenes(false).unwrap().remove(0).scene.id;
        let text = state.app.load_scene_text(scene).unwrap().0;
        assert!(text.contains("**bold**"));
        assert!(text.contains("*italic*"));
        assert_eq!(
            story_import::inspect_scrivener_project(&fixture)
                .unwrap()
                .source_fingerprint,
            source_before
        );
        let report = state
            .app
            .project_root()
            .join("exports/scrivener-import-report.json");
        assert!(report.is_file());
        let series = story_series::SeriesStore::open(&series_root).unwrap();
        assert_eq!(series.list_books().unwrap().len(), 1);

        // Book 3 is created through the same menu form and immediately accepts
        // chapter-level prose without requiring a scene or plot metadata.
        select_series_menu_action(&mut state, "series.new-book").unwrap();
        enter_series_form_values(&mut state, &["Book-03", "Book Three"]).unwrap();
        assert_eq!(state.app.get_project().unwrap().title, "Book Three");
        let chapter = state.app.create_chapter(None, "Chapter 1", 0).unwrap();
        let prose = state
            .app
            .create_content_unit(
                story_core::ContentUnitKind::ChapterBody,
                "Chapter prose",
                Some(chapter),
                0,
                None,
            )
            .unwrap();
        let (_, hash) = state.app.load_content_unit_text(prose).unwrap();
        state
            .app
            .save_content_unit_text(prose, Some(&hash), "Book Three begins here.")
            .unwrap();
        drop(state);
        let reopened = WriterApp::open_project(series_root.join("Book-03")).unwrap();
        assert_eq!(reopened.list_scenes(false).unwrap().len(), 0);
        assert_eq!(reopened.list_content_units(false).unwrap().len(), 1);
        assert_eq!(
            reopened.load_content_unit_text(prose).unwrap().0,
            "Book Three begins here."
        );
        assert_eq!(
            story_series::SeriesStore::open(&series_root)
                .unwrap()
                .list_books()
                .unwrap()
                .len(),
            2
        );
    }

    #[test]
    fn standalone_scrivener_import_works_without_series_and_preserves_source() {
        fn copy_tree(source: &Path, destination: &Path) {
            fs::create_dir_all(destination).unwrap();
            for entry in fs::read_dir(source).unwrap() {
                let entry = entry.unwrap();
                let output = destination.join(entry.file_name());
                if entry.file_type().unwrap().is_dir() {
                    copy_tree(&entry.path(), &output);
                } else {
                    fs::copy(entry.path(), output).unwrap();
                }
            }
        }
        let fixture = Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("../cli/tests/fixtures/scrivener-windows-311/Windows Regression.scriv");
        let root = tempfile::tempdir().unwrap();
        let source = root.path().join("Windows Regression.scriv");
        copy_tree(&fixture, &source);
        let before = story_import::inspect_scrivener_project(&source)
            .unwrap()
            .source_fingerprint;
        let initial = WriterApp::create_project(root.path().join("Initial"), "Initial").unwrap();
        let mut state = AppState::new(initial, default_bindings());
        state
            .start_scrivener_import_standalone(source.clone())
            .unwrap();
        assert!(state.selected_series_root.is_none());
        assert!(state.scrivener_import.is_none());
        assert_eq!(state.workspace, Workspace::Outline);
        assert!(state.temporary_project);
        assert!(state.message.contains("temporary workspace"));

        assert_eq!(state.app.get_project().unwrap().title, "Windows Regression");
        let prose_units = state.app.list_content_units(false).unwrap();
        assert_eq!(prose_units.len(), 1);
        let imported_text = state
            .app
            .load_content_unit_text(prose_units[0].id)
            .unwrap()
            .0;
        assert!(
            imported_text.contains("quiet, generic scene"),
            "{imported_text:?}"
        );
        assert_eq!(
            story_import::inspect_scrivener_project(&source)
                .unwrap()
                .source_fingerprint,
            before
        );
        assert!(
            state
                .app
                .project_root()
                .join("exports/scrivener-import-report.json")
                .is_file()
        );
        assert!(is_staged_project(state.app.project_root()));
        assert!(story_series::SeriesStore::open_for_book(state.app.project_root()).is_err());
    }

