    #[test]
    fn context_sequences_allow_configured_menu_chords_but_reject_unknowns_and_prefix_conflicts() {
        let root = tempfile::tempdir().unwrap();
        let project = WriterApp::create_project(root.path().join("Keys"), "Keys").unwrap();
        let config = project.project_root().join(".writers-ide/keybindings.toml");
        fs::write(
            &config,
            "[contexts.unknown]\n\"Ctrl+X Ctrl+S\" = \"file.save\"\n",
        )
        .unwrap();
        assert!(load_context_command_bindings(project.project_root()).is_err());
        fs::write(
            &config,
            "[contexts.editor]\n\"Ctrl+X Ctrl+/\" = \"file.save\"\n",
        )
        .unwrap();
        assert!(load_context_command_bindings(project.project_root()).is_ok());
        fs::write(
            &config,
            "[contexts.editor]\n\"Ctrl+X\" = \"file.save\"\n\"Ctrl+X Ctrl+S\" = \"view.analytics\"\n",
        )
        .unwrap();
        assert!(load_context_command_bindings(project.project_root()).is_err());
        let mut user = KeymapFile::default();
        user.contexts.insert(
            "editor".into(),
            BTreeMap::from([("Ctrl+X".into(), "file.save".into())]),
        );
        let mut project_scope = KeymapFile::default();
        project_scope.contexts.insert(
            "editor".into(),
            BTreeMap::from([("Ctrl+X Ctrl+S".into(), "view.analytics".into())]),
        );
        assert!(merge_context_keymap_configs(vec![user, project_scope]).is_err());
        assert!(parse_key_sequence("Ctrl+X Ctrl+S Ctrl+T Ctrl+O Ctrl+P").is_err());
    }

    #[test]
    fn project_keybinding_commands_validate_persist_and_reload_immediately() {
        let root = tempfile::tempdir().unwrap();
        let project = WriterApp::create_project(root.path().join("Keys"), "Keys").unwrap();
        let mut state = AppState::new(project, default_bindings());
        state
            .execute_legacy_palette_command("keybinding-set Ctrl+Alt+K view.analytics")
            .unwrap();
        assert_eq!(state.command_bindings.len(), 1);
        handle(
            &mut state,
            KeyEvent::new(
                KeyCode::Char('k'),
                KeyModifiers::CONTROL | KeyModifiers::ALT,
            ),
        )
        .unwrap();
        assert_eq!(state.workspace, Workspace::Analytics);
        state
            .execute_legacy_palette_command("keybinding-set Ctrl+/ view.editor")
            .unwrap();
        assert_eq!(
            effective_command_shortcuts(&state, command_by_id("menu.main").unwrap()),
            vec!["Alt+M", "F10"]
        );
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Char('/'), KeyModifiers::CONTROL),
        )
        .unwrap();
        assert_eq!(state.workspace, Workspace::Editor);
        assert!(state.menu.is_none());
        state
            .execute_legacy_palette_command("keybinding-remove Ctrl+/")
            .unwrap();
        state
            .execute_legacy_palette_command("keybinding-set Ctrl+Alt+J compile.selected")
            .unwrap();
        handle(
            &mut state,
            KeyEvent::new(
                KeyCode::Char('j'),
                KeyModifiers::CONTROL | KeyModifiers::ALT,
            ),
        )
        .unwrap();
        assert_eq!(state.mode, Some(':'));
        assert_eq!(state.prompt, "process-only ");
        state
            .execute_legacy_palette_command("keybinding-remove Ctrl+Alt+J")
            .unwrap();
        state
            .execute_legacy_palette_command("keybinding-remove Ctrl+Alt+K")
            .unwrap();
        assert!(state.command_bindings.is_empty());
        let config: KeymapFile = toml::from_str(
            &fs::read_to_string(
                state
                    .app
                    .project_root()
                    .join(".writers-ide/keybindings.toml"),
            )
            .unwrap(),
        )
        .unwrap();
        assert!(config.commands.is_empty());
    }

