    #[test]
    fn command_palette_filters_registry_and_dispatches_the_selected_action() {
        let root = tempfile::tempdir().unwrap();
        let app = WriterApp::create_project(root.path().join("Novel"), "Novel").unwrap();
        let mut state = AppState::new(app, default_bindings());
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Char(':'), KeyModifiers::NONE),
        )
        .unwrap();
        assert!(state.command_palette.is_some());

        for character in "timeline".chars() {
            handle(
                &mut state,
                KeyEvent::new(KeyCode::Char(character), KeyModifiers::NONE),
            )
            .unwrap();
        }
        let matches = command_palette_candidates("timeline");
        assert_eq!(
            matches.first().map(|command| command.id),
            Some("view.timeline")
        );
        assert!(
            command_palette_candidates("vwtim")
                .iter()
                .any(|command| command.id == "view.timeline")
        );
        assert!(
            !command_palette_candidates("+++")
                .iter()
                .any(|command| command.id == "view.timeline")
        );
        let backend = ratatui::backend::TestBackend::new(80, 24);
        let mut terminal = ratatui::Terminal::new(backend).unwrap();
        terminal.draw(|frame| draw(frame, &mut state)).unwrap();
        let screen = terminal
            .backend()
            .buffer()
            .content()
            .iter()
            .map(|cell| cell.symbol())
            .collect::<String>();
        assert!(screen.contains("Command Palette"));
        assert!(screen.contains("Timeline"));
        assert!(!screen.contains("view.timeline"), "{screen:?}");
        handle(&mut state, KeyEvent::new(KeyCode::Tab, KeyModifiers::NONE)).unwrap();
        assert_eq!(state.command_palette.as_ref().unwrap().query, "Timeline");
        for (width, height) in [(20, 6), (40, 10), (80, 24), (93, 36), (142, 60)] {
            let mut resized =
                ratatui::Terminal::new(ratatui::backend::TestBackend::new(width, height)).unwrap();
            resized.draw(|frame| draw(frame, &mut state)).unwrap();
        }

        state
            .dispatch_registered_command_id("help.context")
            .unwrap();
        assert!(state.help_panel.is_some());
        assert!(state.command_palette.is_some());
        handle(&mut state, KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE)).unwrap();
        assert!(state.help_panel.is_none());
        assert!(state.command_palette.is_some());

        handle(
            &mut state,
            KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE),
        )
        .unwrap();
        assert_eq!(state.workspace, Workspace::Timeline);
        assert!(state.command_palette.is_none());

        state
            .execute_legacy_palette_command("keybinding-set Ctrl+Alt+P command.palette-open")
            .unwrap();
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Char('p'), KeyModifiers::CONTROL),
        )
        .unwrap();
        assert!(state.command_palette.is_none());
        handle(
            &mut state,
            KeyEvent::new(
                KeyCode::Char('p'),
                KeyModifiers::CONTROL | KeyModifiers::ALT,
            ),
        )
        .unwrap();
        assert!(state.command_palette.is_some());
    }

