    #[test]
    fn scene_cards_arrow_moves_cross_chapter_and_chapter_assignment_is_a_chooser() {
        let root = tempfile::tempdir().unwrap();
        let mut app = WriterApp::create_project(root.path().join("Novel"), "Novel").unwrap();
        let first_chapter = app.create_chapter(None, "First", 0).unwrap();
        let second_chapter = app.create_chapter(None, "Second", 1).unwrap();
        let moving = app.create_scene(first_chapter, "Moving scene", 0).unwrap();
        let neighbor = app
            .create_scene(second_chapter, "Neighbor scene", 0)
            .unwrap();
        let (_, hash) = app.load_scene_text(moving).unwrap();
        app.save_scene_text(moving, Some(&hash), "This prose stays with the scene.")
            .unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.switch(Workspace::Cards);
        state.refresh().unwrap();
        state.selected = scene_card_ids(&state)
            .iter()
            .position(|id| *id == moving)
            .unwrap();

        handle(
            &mut state,
            KeyEvent::new(KeyCode::Right, KeyModifiers::NONE),
        )
        .unwrap();
        assert_eq!(
            state.app.get_scene(moving).unwrap().chapter_id,
            Some(second_chapter)
        );
        assert_eq!(selected_scene_for_workspace(&state), Some(moving));
        assert_eq!(
            state.app.load_scene_text(moving).unwrap().0,
            "This prose stays with the scene."
        );
        assert_eq!(
            state.app.get_scene(neighbor).unwrap().chapter_id,
            Some(second_chapter)
        );

        state.dispatch_registered_command_id("scene.move").unwrap();
        assert_eq!(state.mode, Some('M'));
        assert!(state.prompt.contains("choose"));
        handle(&mut state, KeyEvent::new(KeyCode::Up, KeyModifiers::NONE)).unwrap();
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE),
        )
        .unwrap();
        assert_eq!(
            state.app.get_scene(moving).unwrap().chapter_id,
            Some(first_chapter)
        );
        assert_eq!(selected_scene_for_workspace(&state), Some(moving));
        assert_eq!(
            state.app.load_scene_text(moving).unwrap().0,
            "This prose stays with the scene."
        );
        assert!(workspace_action_hint(&state).contains("←→ move"));
        assert!(workspace_action_hint(&state).contains("Tab columns"));
    }

    #[test]
    fn outline_and_card_presentation_share_selection_order_and_scene_actions() {
        let root = tempfile::tempdir().unwrap();
        let mut app = WriterApp::create_project(root.path().join("Novel"), "Novel").unwrap();
        let first = app.create_chapter(None, "First chapter", 0).unwrap();
        let second = app.create_chapter(None, "Second chapter", 1).unwrap();
        let opening = app.create_scene(first, "The arrival", 0).unwrap();
        let turning = app.create_scene(second, "A difficult choice", 0).unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.refresh().unwrap();
        state.workspace = Workspace::Outline;
        state.selected = outline_rows(&state)
            .iter()
            .position(|row| matches!(row, OutlineRow::Chapter { id, .. } if *id == second))
            .unwrap();
        assert!(
            matches!(outline_rows(&state).get(state.selected), Some(OutlineRow::Chapter { id, .. }) if *id == second)
        );

        state.switch(Workspace::Cards);
        assert_eq!(state.selected_card_chapter, Some((second, true)));
        assert_eq!(selected_scene_for_workspace(&state), None);
        state.switch(Workspace::Outline);
        assert!(matches!(
            outline_rows(&state).get(state.selected),
            Some(OutlineRow::Chapter { id, .. }) if *id == second
        ));

        state.selected = outline_rows(&state)
            .iter()
            .position(|row| *row == OutlineRow::Scene(turning))
            .unwrap();
        state.dispatch_registered_command_id("view.cards").unwrap();
        assert_eq!(state.workspace, Workspace::Cards);
        assert_eq!(selected_scene_for_workspace(&state), Some(turning));
        state.dispatch_registered_command_id("view.cards").unwrap();
        assert_eq!(state.workspace, Workspace::Outline);
        assert_eq!(selected_scene_for_workspace(&state), Some(turning));

        state.open_menu_category(OUTLINE_MENU_INDEX);
        assert_eq!(state.workspace, Workspace::Outline);
        assert!(state.menu_visible_entries().iter().any(|command| {
            command.id == "scene.toggle-inclusion"
                && state.command_disabled_reason(*command).is_none()
        }));
        state
            .dispatch_registered_command_id("scene.toggle-inclusion")
            .unwrap();
        assert_eq!(state.workspace, Workspace::Outline);
        assert_eq!(selected_scene_for_workspace(&state), Some(turning));
        assert!(!state.app.scene_is_included(turning).unwrap());
        assert_eq!(
            state.app.get_scene(opening).unwrap().chapter_id,
            Some(first)
        );
    }

    #[test]
    fn scene_cards_order_unplaced_scenes_switch_collections_and_move_chapter_blocks() {
        let root = tempfile::tempdir().unwrap();
        let project_path = root.path().join("Novel");
        let mut app = WriterApp::create_project(&project_path, "Novel").unwrap();
        let first_chapter = app.create_chapter(None, "First", 0).unwrap();
        let second_chapter = app.create_chapter(None, "Second", 1).unwrap();
        let unplaced_a = app.create_unplaced_scene("Unplaced A").unwrap();
        let unplaced_b = app.create_unplaced_scene("Unplaced B").unwrap();
        let placed = app.create_scene(first_chapter, "Placed", 0).unwrap();
        let held = app.create_scene(second_chapter, "Held aside", 0).unwrap();
        app.set_scene_included(held, false).unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.switch(Workspace::Cards);
        state.refresh().unwrap();
        state.selected = scene_card_ids(&state)
            .iter()
            .position(|id| *id == unplaced_a)
            .unwrap();

        handle(&mut state, KeyEvent::new(KeyCode::Down, KeyModifiers::NONE)).unwrap();
        assert_eq!(selected_scene_for_workspace(&state), Some(unplaced_b));
        handle(&mut state, KeyEvent::new(KeyCode::Tab, KeyModifiers::NONE)).unwrap();
        assert_eq!(selected_scene_for_workspace(&state), Some(held));
        handle(&mut state, KeyEvent::new(KeyCode::Tab, KeyModifiers::NONE)).unwrap();
        assert!(selected_scene_for_workspace(&state).is_some_and(|scene| scene != held));

        state.selected = scene_card_ids(&state)
            .iter()
            .position(|id| *id == unplaced_a)
            .unwrap();
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Right, KeyModifiers::NONE),
        )
        .unwrap();
        assert_eq!(
            state.app.list_scenes(false).unwrap()[0].scene.id,
            unplaced_b
        );
        assert_eq!(selected_scene_for_workspace(&state), Some(unplaced_a));
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Right, KeyModifiers::NONE),
        )
        .unwrap();
        assert_eq!(
            state.app.get_scene(unplaced_a).unwrap().chapter_id,
            Some(first_chapter)
        );
        assert_eq!(selected_scene_for_workspace(&state), Some(unplaced_a));
        handle(&mut state, KeyEvent::new(KeyCode::Left, KeyModifiers::NONE)).unwrap();
        assert_eq!(state.app.get_scene(unplaced_a).unwrap().chapter_id, None);

        state.selected = scene_card_ids(&state)
            .iter()
            .position(|id| *id == placed)
            .unwrap();
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Right, KeyModifiers::SHIFT),
        )
        .unwrap();
        let chapter_order = state
            .app
            .list_structural_nodes()
            .unwrap()
            .into_iter()
            .filter(|node| node.kind == "chapter")
            .map(|node| node.id)
            .collect::<Vec<_>>();
        assert_eq!(chapter_order, [second_chapter, first_chapter]);
        assert_eq!(selected_scene_for_workspace(&state), Some(placed));

        handle(
            &mut state,
            KeyEvent::new(KeyCode::Insert, KeyModifiers::SHIFT),
        )
        .unwrap();
        assert_eq!(state.mode, Some('H'));
        for character in "New boundary".chars() {
            handle(
                &mut state,
                KeyEvent::new(KeyCode::Char(character), KeyModifiers::NONE),
            )
            .unwrap();
        }
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE),
        )
        .unwrap();
        let new_chapter = state.selected_card_chapter.unwrap().0;
        assert_eq!(
            state.app.get_scene(placed).unwrap().chapter_id,
            Some(first_chapter)
        );
        assert_eq!(
            state
                .app
                .list_structural_nodes()
                .unwrap()
                .into_iter()
                .find(|node| node.id == new_chapter)
                .unwrap()
                .title,
            "New boundary"
        );
        assert_eq!(selected_scene_for_workspace(&state), None);
        drop(state);
        let reopened = WriterApp::open_project(&project_path).unwrap();
        assert_eq!(reopened.get_scene(unplaced_a).unwrap().chapter_id, None);
        assert_eq!(
            reopened.get_scene(placed).unwrap().chapter_id,
            Some(first_chapter)
        );
        assert!(
            reopened
                .list_structural_nodes()
                .unwrap()
                .iter()
                .any(|node| node.id == new_chapter && node.title == "New boundary")
        );
        assert_eq!(reopened.list_scenes(false).unwrap()[0].scene.id, unplaced_b);
    }

    #[test]
    fn recent_commands_persist_and_precede_default_palette_suggestions() {
        let root = tempfile::tempdir().unwrap();
        let project_root = root.path().join("Novel");
        let app = WriterApp::create_project(&project_root, "Novel").unwrap();
        let mut state = AppState::new(app, default_bindings());
        state
            .dispatch_registered_command_id("view.timeline")
            .unwrap();
        state
            .dispatch_registered_command_id("view.characters")
            .unwrap();

        let history = load_command_history(&project_root).unwrap();
        assert_eq!(history, ["view.characters", "view.timeline"]);
        let reopened = WriterApp::open_project(&project_root).unwrap();
        let mut reopened_state = AppState::new(reopened, default_bindings());
        reopened_state
            .dispatch_registered_command_id("command.palette-open")
            .unwrap();
        let palette = reopened_state.command_palette.as_ref().unwrap();
        assert_eq!(palette.recent_commands, history);
        let candidates = command_palette_candidates_with_history("", &palette.recent_commands);
        assert_eq!(candidates[0].id, "view.characters");
        assert_eq!(candidates[1].id, "view.timeline");
        assert_eq!(
            command_palette_candidates_with_history("view.timeline", &palette.recent_commands)[0]
                .id,
            "view.timeline"
        );
    }

