    #[test]
    fn compile_configuration_menu_dispatch_creates_lists_and_runs_profile() {
        let root = tempfile::tempdir().unwrap();
        let mut app = WriterApp::create_project(root.path().join("Compile"), "Compile").unwrap();
        let chapter = app.create_chapter(None, "Chapter", 0).unwrap();
        let scene = app.create_scene(chapter, "Opening", 0).unwrap();
        let (_, hash) = app.load_scene_text(scene).unwrap();
        app.save_scene_text(scene, Some(&hash), "Terminal compile configuration.")
            .unwrap();
        let mut state = AppState::new(app, default_bindings());
        state
            .execute_legacy_palette_command("compile-config create markdown plain")
            .unwrap();
        assert!(
            state
                .message
                .contains("Created Compile Configuration plain")
        );
        state
            .execute_legacy_palette_command("compile-config list")
            .unwrap();
        assert_eq!(state.message, "plain");
        state
            .execute_legacy_palette_command("compile-config run plain")
            .unwrap();
        assert_eq!(
            latest_compile_output(&state.app).unwrap(),
            root.path()
                .join("Compile/exports/compile/plain/manuscript.md")
        );
        assert!(state.message.contains("Compile plain success"));
        state
            .execute_legacy_palette_command("compile-config results")
            .unwrap();
        assert!(state.message.contains("plain success"));
        assert!(
            root.path()
                .join("Compile/exports/compile/plain/manuscript.md")
                .is_file()
        );
        let (_, hash) = state.app.load_scene_text(scene).unwrap();
        state
            .app
            .save_scene_text(scene, Some(&hash), "Mara said said.")
            .unwrap();
        state
            .execute_legacy_palette_command("compile-config run plain -Werror=repeated-word")
            .unwrap();
        assert!(state.message.contains("Compile plain failed"));
        let results = compile_results_reference_text(&state.app, "errors").unwrap();
        assert!(results.contains("promoted to Error"));
        state
            .execute_legacy_palette_command("compile-config run plain -w")
            .unwrap();
        assert!(state.message.contains("Compile plain success"));
        state
            .execute_legacy_palette_command(
                "compile-config run plain --overwrite --short-chapter-under=100 --plotline-gap-at-least=1 -Wextra -Werror",
            )
            .unwrap();
        assert!(state.message.contains("Compile plain failed"));
        assert!(
            compile_results_reference_text(&state.app, "errors")
                .unwrap()
                .contains("short-chapter")
        );
    }

    #[test]
    fn terminal_creates_reviews_and_revokes_diagnostic_suppressions() {
        let root = tempfile::tempdir().unwrap();
        let mut app = WriterApp::create_project(root.path().join("Book"), "Book").unwrap();
        let chapter = app.create_chapter(None, "Chapter", 0).unwrap();
        let scene = app.create_scene(chapter, "Opening", 0).unwrap();
        let (_, hash) = app.load_scene_text(scene).unwrap();
        app.save_scene_text(scene, Some(&hash), "TODO: review.")
            .unwrap();
        let finding = app
            .compile_diagnostics()
            .unwrap()
            .iter()
            .position(|item| item.code == "PUB004")
            .unwrap()
            + 1;
        let mut state = AppState::new(app, default_bindings());
        state
            .execute_legacy_palette_command(&format!(
                "compile-suppress {finding} finding intentional draft marker"
            ))
            .unwrap();
        assert!(state.message.contains("Suppressed PUB004 by finding"));
        let id = state.app.diagnostic_suppressions().unwrap()[0].id.clone();
        let diagnostics = state.app.compile_diagnostics().unwrap();
        assert!(
            diagnostics
                .iter()
                .find(|item| item.code == "PUB004")
                .unwrap()
                .suppressed
        );
        state
            .execute_legacy_palette_command("compile-suppressions")
            .unwrap();
        assert!(state.reference_focused);
        assert!(
            state.reference_panes[state.active_reference]
                .content
                .contains("intentional draft marker")
        );
        state
            .execute_legacy_palette_command(&format!("compile-unsuppress {id}"))
            .unwrap();
        assert_eq!(
            state.app.diagnostic_suppressions().unwrap()[0].status,
            "revoked"
        );
        assert!(
            state
                .app
                .compile_diagnostics()
                .unwrap()
                .iter()
                .find(|item| item.code == "PUB004")
                .is_some_and(|item| !item.suppressed)
        );
    }

    #[test]
    fn terminal_saves_project_structure_as_a_new_portable_template() {
        let root = tempfile::tempdir().unwrap();
        let mut app = WriterApp::create_project(root.path().join("Book"), "Private title").unwrap();
        let chapter = app.create_chapter(None, "Chapter One", 0).unwrap();
        let scene = app.create_scene(chapter, "Opening", 0).unwrap();
        let (_, hash) = app.load_scene_text(scene).unwrap();
        app.save_scene_text(scene, Some(&hash), "PRIVATE MANUSCRIPT TEXT")
            .unwrap();
        let mut state = AppState::new(app, default_bindings());
        let output = root.path().join("novel-template.toml");
        state
            .execute_legacy_palette_command(&format!(
                "project-template-save novel {}",
                output.display()
            ))
            .unwrap();
        let source = fs::read_to_string(&output).unwrap();
        let template: story_core::ProjectTemplate = toml::from_str(&source).unwrap();
        assert_eq!(template.id, "novel");
        assert_eq!(template.name, "novel");
        assert_eq!(template.nodes.len(), 1);
        assert_eq!(template.scenes.len(), 1);
        assert!(!source.contains("PRIVATE MANUSCRIPT TEXT"));
        assert!(!source.contains("Private title"));
        assert!(state.message.contains("excluded"));
        assert!(
            state
                .execute_legacy_palette_command(&format!(
                    "project-template-save novel {}",
                    output.display()
                ))
                .is_err()
        );
    }

    #[test]
    fn terminal_timed_challenge_records_session_and_never_deletes_steady_prose() {
        let root = tempfile::tempdir().unwrap();
        let mut project = WriterApp::create_project(root.path().join("Book"), "Book").unwrap();
        let chapter = project.create_chapter(None, "Chapter", 0).unwrap();
        let scene = project.create_scene(chapter, "Scene", 0).unwrap();
        let (_, original_hash) = project.load_scene_text(scene).unwrap();
        project
            .save_scene_text(scene, Some(&original_hash), "existing manuscript prose")
            .unwrap();
        let today = time::OffsetDateTime::now_utc().date();
        project
            .create_writing_goal(&story_storage::NewWritingGoal {
                title: "Challenge ledger".into(),
                scope_scene_id: Some(scene),
                start_date: format!(
                    "{:04}-{:02}-{:02}",
                    today.year(),
                    u8::from(today.month()),
                    today.day()
                ),
                end_date: format!(
                    "{:04}-{:02}-{:02}",
                    today.year(),
                    u8::from(today.month()),
                    today.day()
                ),
                target_words: 100,
                baseline_words: 0,
                time_zone: "UTC".into(),
                word_count_policy: "unicode-word-boundaries".into(),
                success_metric: "raw".into(),
            })
            .unwrap();
        let mut state = AppState::new(project, default_bindings());
        state.open_scene(scene).unwrap();
        state.prompt = format!("challenge-start 10 60 steady scene={scene}");
        state.command().unwrap();
        assert_eq!(state.active_challenge.as_ref().unwrap().mode, "steady");
        state.editor[0] = "three four".into();
        state.prompt = "challenge-finish".into();
        state.command().unwrap();
        assert_eq!(state.editor[0], "existing manuscript prose");
        assert_eq!(
            state.app.load_scene_text(scene).unwrap().0,
            "existing manuscript prose"
        );
        let challenges = state.app.list_writing_challenges().unwrap();
        assert_eq!(challenges[0].words_written, Some(2));
        assert_eq!(challenges[0].status, "abandoned");
        assert_eq!(challenges[0].outcome, "quit");
        let goal = state.app.list_writing_goals(false).unwrap().remove(0);
        let ledger = state.app.list_writing_goal_events(&goal.id).unwrap();
        assert_eq!(ledger.len(), 1);
        assert_eq!(ledger[0].origin, "write-or-die");
        assert_eq!(ledger[0].raw_delta, 2);
        assert_eq!(ledger[0].real_delta, 0);
        let draft_id = &challenges[0].id;
        assert!(
            list_challenge_drafts(state.app.project_root(), |_| state
                .app
                .get_project()
                .unwrap()
                .word_count_policy,)
            .unwrap()
            .contains(draft_id)
        );
        state.prompt = format!("challenge-save-new {draft_id} {chapter} Challenge draft");
        state.command().unwrap();
        let saved_id = state
            .scenes
            .iter()
            .find(|(_, title, _, _)| title == "Challenge draft")
            .unwrap()
            .0;
        assert_eq!(state.app.load_scene_text(saved_id).unwrap().0, "three four");
    }

