    #[test]
    fn destructive_repeated_macros_preview_then_apply_as_one_undoable_edit() {
        let root = tempfile::tempdir().unwrap();
        let mut project = WriterApp::create_project(root.path().join("Macro"), "Macro").unwrap();
        let chapter = project.create_chapter(None, "Chapter", 0).unwrap();
        let scene = project.create_scene(chapter, "Scene", 0).unwrap();
        let mut state = AppState::new(project, default_bindings());
        state.open_scene(scene).unwrap();
        state.editor = vec!["word".into()];
        state.dirty = true;
        state
            .macros
            .insert("trim".into(), vec![story_core::EditMacroOp::Backspace]);
        state.prompt = "macro-run trim 2".into();
        state.command().unwrap();
        assert_eq!(state.editor, ["word"]);
        assert_eq!(state.macro_preview.as_ref().unwrap().proposed, "wo");
        let backend = ratatui::backend::TestBackend::new(100, 20);
        let mut terminal = ratatui::Terminal::new(backend).unwrap();
        terminal.draw(|frame| draw(frame, &mut state)).unwrap();
        let visible = terminal
            .backend()
            .buffer()
            .content()
            .iter()
            .map(|cell| cell.symbol())
            .collect::<String>();
        assert!(visible.contains("Current manuscript"));
        assert!(visible.contains("Proposed macro result"));
        assert!(visible.contains("word"));
        assert!(visible.contains("wo"));
        handle(&mut state, KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE)).unwrap();
        assert!(state.macro_preview.is_none());
        assert_eq!(state.editor, ["word"]);

        state.prompt = "macro-run trim 2".into();
        state.command().unwrap();
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE),
        )
        .unwrap();
        assert_eq!(state.editor, ["wo"]);
        assert!(
            state
                .app
                .git_history(5)
                .unwrap()
                .iter()
                .any(|commit| { commit.subject == "Before repeated macro trim" })
        );
        state.undo_edit();
        assert_eq!(state.editor, ["word"]);
        assert_eq!(
            parse_macro_run_arguments("trim 101"),
            Err("use macro-run NAME [REPETITIONS], with repetitions from 1 to 100".into())
        );
    }

    #[test]
    fn text_expansion_is_configurable_undoable_contextual_and_not_applied_to_paste() {
        let root = tempfile::tempdir().unwrap();
        let app = WriterApp::create_project(root.path().join("Text Expansion"), "Text Expansion")
            .unwrap();
        let mut config = TextExpansionConfig::default();
        config.triggers.push("tab".into());
        config
            .mappings
            .insert("%DWAP%".into(), "Department of Work and Pensions".into());
        config.mappings.insert("%D%".into(), "short".into());
        save_text_expansion(app.project_root(), &config).unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.user_text_expansion = TextExpansionConfig::default();
        state
            .user_text_expansion
            .mappings
            .insert("%DWAP%".into(), "personal override".into());
        state
            .user_text_expansion
            .mappings
            .insert("%USER%".into(), "personal dictionary".into());

        state.editor = vec!["%DWAP%".into()];
        state.cursor = (0, 6);
        state.push_undo();
        state.insert(' ');
        assert_eq!(state.editor, ["Department of Work and Pensions "]);
        state.undo_edit();
        assert_eq!(state.editor, ["%DWAP%"]);

        state.editor = vec!["word%D%".into()];
        state.cursor = (0, 7);
        state.push_undo();
        state.insert(' ');
        assert_eq!(state.editor, ["word%D% "]);

        state.editor = vec!["%D%".into()];
        state.cursor = (0, 3);
        state.paste_text(" ");
        assert_eq!(state.editor, ["%D% "]);

        state.editor = vec!["%D%".into()];
        state.cursor = (0, 3);
        state.push_undo();
        state.insert('\t');
        assert_eq!(state.editor, ["short\t"]);

        state.editor = vec!["%USER%".into()];
        state.cursor = (0, 6);
        state.insert(' ');
        assert_eq!(state.editor, ["personal dictionary "]);

        state.user_text_expansion.enabled = false;
        state.editor = vec!["%USER%".into()];
        state.cursor = (0, 6);
        state.insert(' ');
        assert_eq!(state.editor, ["%USER% "]);
        state.user_text_expansion.enabled = true;

        state.editor = vec!["%D%".into()];
        state.cursor = (0, 3);
        assert!(state.expand_text_before_cursor("", "", true));
        assert_eq!(state.editor, ["short"]);

        state.editor = vec!["%DWAP%".into()];
        state.cursor = (0, 6);
        state.enter();
        assert_eq!(state.editor, ["Department of Work and Pensions", ""]);
        let reopened = AppState::new(
            WriterApp::open_project(state.app.project_root()).unwrap(),
            default_bindings(),
        );
        assert_eq!(
            reopened.text_expansion.mappings["%DWAP%"],
            "Department of Work and Pensions"
        );
    }

    #[test]
    fn personal_text_expansion_toml_is_portable_and_project_mappings_win() {
        let directory = tempfile::tempdir().unwrap();
        let user_path = directory
            .path()
            .join("config/writers-ide/text-expansion.toml");
        let project_path = directory
            .path()
            .join("project/.writers-ide/text-expansion.toml");
        let mut user = TextExpansionConfig::default();
        user.mappings
            .insert("%DWAP%".into(), "personal value".into());
        user.mappings
            .insert("%USER%".into(), "personal-only value".into());
        save_text_expansion_file(&user_path, &user).unwrap();
        let loaded_user = load_text_expansion_file(&user_path).unwrap();

        let mut project = TextExpansionConfig::default();
        project
            .mappings
            .insert("%DWAP%".into(), "project value".into());
        project
            .mappings
            .insert("%PROJECT%".into(), "project-only value".into());
        save_text_expansion_file(&project_path, &project).unwrap();
        let loaded_project = load_text_expansion_file(&project_path).unwrap();

        let effective = merge_text_expansion_mappings(&loaded_user, &loaded_project);
        assert_eq!(effective["%DWAP%"], "project value");
        assert_eq!(effective["%USER%"], "personal-only value");
        assert_eq!(effective["%PROJECT%"], "project-only value");
        assert_eq!(load_text_expansion_file(&user_path).unwrap(), loaded_user);
    }

