    #[test]
    fn terminal_review_merge_applies_non_overlapping_changes_and_leaves_conflicts_unmodified() {
        let directory = tempfile::tempdir().unwrap();
        let project = directory.path().join("Novel");
        let mut app = WriterApp::create_project(&project, "Novel").unwrap();
        let chapter = app.create_chapter(None, "Chapter", 0).unwrap();
        let scene = app.create_scene(chapter, "Scene", 0).unwrap();
        let base = "One.\nTwo.\nThree.\n";
        let (_, hash) = app.load_scene_text(scene).unwrap();
        app.save_scene_text(scene, Some(&hash), "One local.\nTwo.\nThree.\n")
            .unwrap();
        let base_file = directory.path().join("base.txt");
        let review_file = directory.path().join("review.txt");
        fs::write(&base_file, base).unwrap();
        fs::write(&review_file, "One.\nTwo.\nThree reviewed.\n").unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.refresh().unwrap();
        state.mode = Some(':');
        state.prompt = format!(
            "review-merge {scene} {} {}",
            base_file.display(),
            review_file.display()
        );
        state.command().unwrap();
        assert_eq!(
            state.app.load_scene_text(scene).unwrap().0,
            "One local.\nTwo.\nThree reviewed.\n"
        );
        fs::write(&review_file, "One external.\nTwo.\nThree.\n").unwrap();
        state.mode = Some(':');
        state.prompt = format!(
            "review-merge {scene} {} {}",
            base_file.display(),
            review_file.display()
        );
        state.command().unwrap();
        assert!(state.message.contains("conflict"));
        let review = state.active_reference_pane().unwrap();
        assert_eq!(review.title, "Editorial conflict review");
        assert!(review.content.contains("BASE"));
        assert!(review.content.contains("LOCAL"));
        assert!(review.content.contains("REVIEWED"));
        assert_eq!(
            state.app.load_scene_text(scene).unwrap().0,
            "One local.\nTwo.\nThree reviewed.\n"
        );
        state.mode = Some(':');
        state.prompt = format!(
            "review-resolve {scene} {} {} external",
            base_file.display(),
            review_file.display()
        );
        state.command().unwrap();
        assert_eq!(
            state.app.load_scene_text(scene).unwrap().0,
            "One external.\nTwo.\nThree reviewed.\n"
        );
    }

    #[test]
    fn terminal_accepts_docx_tracked_changes_through_review_merge() {
        use std::io::Write;
        let directory = tempfile::tempdir().unwrap();
        let mut app = WriterApp::create_project(directory.path().join("Novel"), "Novel").unwrap();
        let chapter = app.create_chapter(None, "Chapter", 0).unwrap();
        let scene = app.create_scene(chapter, "Scene", 0).unwrap();
        let base = "The old door.";
        let (_, hash) = app.load_scene_text(scene).unwrap();
        app.save_scene_text(scene, Some(&hash), base).unwrap();
        let docx = directory.path().join("review.docx");
        let file = fs::File::create(&docx).unwrap();
        let mut archive = zip::ZipWriter::new(file);
        archive
            .start_file("word/document.xml", zip::write::FileOptions::default())
            .unwrap();
        archive
            .write_all(b"<w:document><w:body><w:p><w:r><w:t>The </w:t></w:r><w:del><w:r><w:delText>old</w:delText></w:r></w:del><w:ins><w:r><w:t>new</w:t></w:r></w:ins><w:r><w:t> door.</w:t></w:r></w:p></w:body></w:document>")
            .unwrap();
        archive.finish().unwrap();
        let source = fs::read(&docx).unwrap();
        let base_path = directory.path().join("base.md");
        fs::write(&base_path, base).unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.open_scene(scene).unwrap();
        state.prompt = format!(
            "review-docx {scene} {} {} accept",
            base_path.display(),
            docx.display()
        );
        state.command().unwrap();
        assert_eq!(state.app.load_scene_text(scene).unwrap().0, "The new door.");
        assert_eq!(state.editor.join("\n"), "The new door.");
        assert!(state.message.contains("accepted"));
        assert_eq!(fs::read(docx).unwrap(), source);
    }

    #[test]
    fn menu_shortcuts_are_registry_driven_and_plain_slash_remains_prose() {
        let bindings = default_bindings();
        assert!(!bindings.iter().any(|(key, _)| *key == 10));
        assert!(
            bindings
                .iter()
                .any(|(key, workspace)| *key == 9 && *workspace == Workspace::Analytics)
        );
        assert!(
            bindings
                .iter()
                .any(|(key, workspace)| *key == 11 && *workspace == Workspace::Issues)
        );
        let root = tempfile::tempdir().unwrap();
        let mut app = WriterApp::create_project(root.path().join("Novel"), "Novel").unwrap();
        let chapter = app.create_chapter(None, "Chapter", 0).unwrap();
        let scene = app.create_scene(chapter, "Scene", 0).unwrap();
        let mut state = AppState::new(app, bindings);
        state.open_scene(scene).unwrap();
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Char('/'), KeyModifiers::CONTROL),
        )
        .unwrap();
        assert!(state.menu.is_some());
        state.menu = None;
        handle(
            &mut state,
            KeyEvent::new(KeyCode::F(10), KeyModifiers::NONE),
        )
        .unwrap();
        assert!(state.menu.is_some());
        state.menu = None;
        // Slash is ordinary manuscript input when the editor owns focus.
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Char('/'), KeyModifiers::NONE),
        )
        .unwrap();
        assert_eq!(state.editor.join("\n"), "/");
    }

    #[test]
    fn function_key_override_and_menu_chord_sequence_are_registry_driven() {
        let root = tempfile::tempdir().unwrap();
        let mut app = WriterApp::create_project(root.path().join("Novel"), "Novel").unwrap();
        let chapter = app.create_chapter(None, "Chapter", 0).unwrap();
        let scene = app.create_scene(chapter, "Scene", 0).unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.open_scene(scene).unwrap();
        state.function_bindings.push((10, Workspace::Analytics));
        assert_eq!(
            effective_command_shortcuts(&state, command_by_id("menu.main").unwrap()),
            vec!["Ctrl+/", "Alt+M"]
        );
        handle(
            &mut state,
            KeyEvent::new(KeyCode::F(10), KeyModifiers::NONE),
        )
        .unwrap();
        assert_eq!(state.workspace, Workspace::Analytics);
        assert!(state.menu.is_none());

        state.workspace = Workspace::Editor;
        handle(&mut state, KeyEvent::new(KeyCode::F(2), KeyModifiers::NONE)).unwrap();
        assert_eq!(state.workspace, Workspace::Outline);
        state.workspace = Workspace::Editor;
        state.context_command_bindings = vec![ContextCommandBinding {
            context: "editor".into(),
            sequence: parse_key_sequence("Ctrl+/, F").unwrap(),
            command_id: "menu.main".into(),
        }];
        assert_eq!(
            effective_command_shortcuts(&state, command_by_id("menu.main").unwrap()),
            vec!["Ctrl+/, F", "Alt+M"]
        );
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Char('/'), KeyModifiers::CONTROL),
        )
        .unwrap();
        assert!(state.pending_command_sequence.is_some());
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Char('f'), KeyModifiers::NONE),
        )
        .unwrap();
        assert!(state.menu.is_some());
        assert!(state.pending_command_sequence.is_none());

        state.menu = None;
        state.command_bindings = vec![(parse_shortcut("Alt+F").unwrap(), "menu.file".to_owned())];
        assert_eq!(
            effective_command_shortcuts(&state, command_by_id("menu.file").unwrap()),
            vec!["Alt+F"]
        );
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Char('f'), KeyModifiers::ALT),
        )
        .unwrap();
        assert_eq!(state.menu.as_ref().map(|menu| menu.top), Some(0));

        state.menu = None;
        state.command_bindings = vec![(parse_shortcut("F1").unwrap(), "view.analytics".to_owned())];
        assert!(
            effective_command_shortcuts(&state, command_by_id("help.context").unwrap()).is_empty()
        );
        handle(&mut state, KeyEvent::new(KeyCode::F(1), KeyModifiers::NONE)).unwrap();
        assert_eq!(state.workspace, Workspace::Analytics);
        assert!(state.help_panel.is_none());
    }

