        assert_eq!(parse_shortcut("Ctrl+4").unwrap(), prefix);
        assert_eq!(format_key_event(prefix), r"Ctrl+\");
        assert_eq!(
            parse_shortcut("Ctrl+/").unwrap(),
            KeyEvent::new(KeyCode::Char('/'), KeyModifiers::CONTROL)
        );
