    #[test]
    fn focus_mode_hides_reference_panes_but_keeps_the_menu_bar_available() {
        let directory = tempfile::tempdir().unwrap();
        let mut app = WriterApp::create_project(directory.path().join("Novel"), "Novel").unwrap();
        let chapter = app.create_chapter(None, "Chapter", 0).unwrap();
        let scene = app.create_scene(chapter, "Draft", 0).unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.open_scene(scene).unwrap();
        state.editor = vec!["PROSEVISIBLE".into()];
        state.open_reference_buffer(
            "research:fixture".into(),
            None,
            "Pinned reference".into(),
            "REFERENCEHIDDEN".into(),
        );
        let backend = ratatui::backend::TestBackend::new(120, 30);
        let mut terminal = ratatui::Terminal::new(backend).unwrap();
        terminal.draw(|frame| draw(frame, &mut state)).unwrap();
        let visible = terminal
            .backend()
            .buffer()
            .content()
            .iter()
            .map(|cell| cell.symbol())
            .collect::<String>();
        assert!(visible.contains("REFERENCEHIDDEN"));

        state.editor_focus_mode = true;
        terminal.draw(|frame| draw(frame, &mut state)).unwrap();
        let focused = terminal
            .backend()
            .buffer()
            .content()
            .iter()
            .map(|cell| cell.symbol())
            .collect::<String>();
        assert!(focused.contains("PROSEVISIBLE"));
        assert!(!focused.contains("REFERENCEHIDDEN"));
        assert!(focused.contains("File"), "{focused:?}");

        state.reference_focused = true;
        terminal.draw(|frame| draw(frame, &mut state)).unwrap();
        let maximized = terminal
            .backend()
            .buffer()
            .content()
            .iter()
            .map(|cell| cell.symbol())
            .collect::<String>();
        assert!(maximized.contains("REFERENCEHIDDEN"));
        assert!(!maximized.contains("PROSEVISIBLE"));
    }

    #[test]
    fn compact_terminal_focus_and_resize_preserve_open_editor_and_reference_state() {
        let directory = tempfile::tempdir().unwrap();
        let mut app = WriterApp::create_project(directory.path().join("Novel"), "Novel").unwrap();
        let chapter = app.create_chapter(None, "Chapter", 0).unwrap();
        let scene = app.create_scene(chapter, "Draft", 0).unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.refresh().unwrap();
        state.open_scene(scene).unwrap();
        state.editor = vec!["BOOKLENGTHPROSE".into()];
        state.cursor = (0, 6);
        state.open_reference_buffer(
            "research:first".into(),
            None,
            "Pinned first reference".into(),
            "First heading\nFIRSTREFERENCE".into(),
        );
        state.open_reference_buffer(
            "research:second".into(),
            None,
            "Pinned second reference".into(),
            "Second heading\nSECONDREFERENCE".into(),
        );
        state.reference_panes[0].scroll = 1;
        state.reference_panes[1].scroll = 1;
        state.active_reference = 1;

        let backend = ratatui::backend::TestBackend::new(80, 10);
        let mut terminal = ratatui::Terminal::new(backend).unwrap();
        terminal.draw(|frame| draw(frame, &mut state)).unwrap();
        let editor_only = terminal
            .backend()
            .buffer()
            .content()
            .iter()
            .map(|cell| cell.symbol())
            .collect::<String>();
        assert!(editor_only.contains("BOOKLENGTHPROSE"));
        assert!(!editor_only.contains("FIRSTREFERENCE"));
        assert!(!editor_only.contains("SECONDREFERENCE"));

        state.reference_focused = true;
        terminal.draw(|frame| draw(frame, &mut state)).unwrap();
        let reference_only = terminal
            .backend()
            .buffer()
            .content()
            .iter()
            .map(|cell| cell.symbol())
            .collect::<String>();
        assert!(reference_only.contains("SECONDREFERENCE"));
        assert!(!reference_only.contains("BOOKLENGTHPROSE"));

        drop(terminal);
        let backend = ratatui::backend::TestBackend::new(120, 30);
        let mut terminal = ratatui::Terminal::new(backend).unwrap();
        state.width = 120;
        state.reference_focused = false;
        terminal.draw(|frame| draw(frame, &mut state)).unwrap();
        let restored = terminal
            .backend()
            .buffer()
            .content()
            .iter()
            .map(|cell| cell.symbol())
            .collect::<String>();
        assert!(restored.contains("BOOKLENGTHPROSE"));
        assert!(restored.contains("FIRSTREFERENCE"), "{restored:?}");
        assert!(restored.contains("SECONDREFERENCE"), "{restored:?}");
        assert_eq!(state.cursor, (0, 6));
        assert_eq!(state.reference_panes.len(), 2);
        assert_eq!(state.reference_panes[0].source_key, "research:first");
        assert_eq!(state.reference_panes[1].source_key, "research:second");
        assert_eq!(state.reference_panes[0].scroll, 1);
        assert_eq!(state.reference_panes[1].scroll, 1);
        assert_eq!(state.active_reference, 1);
    }

    #[test]
    fn reference_visibility_and_split_orientation_restore_from_session() {
        let directory = tempfile::tempdir().unwrap();
        let project = directory.path().join("Novel");
        let mut app = WriterApp::create_project(&project, "Novel").unwrap();
        let chapter = app.create_chapter(None, "Chapter", 0).unwrap();
        let scene = app.create_scene(chapter, "Draft", 0).unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.open_scene(scene).unwrap();
        state
            .execute_legacy_palette_command(&format!("reference-scene {scene}"))
            .unwrap();
        state
            .execute_legacy_palette_command("reference-layout vertical")
            .unwrap();
        state
            .execute_legacy_palette_command("reference-toggle")
            .unwrap();
        state.execute_legacy_palette_command("window-swap").unwrap();
        assert_eq!(state.reference_layout, ReferenceLayout::Stacked);
        assert!(state.reference_panes_hidden);
        assert!(state.reference_swapped);

        let mut reopened = AppState::new(
            WriterApp::open_project(&project).unwrap(),
            default_bindings(),
        );
        reopened.restore_session().unwrap();
        assert_eq!(reopened.reference_layout, ReferenceLayout::Stacked);
        assert!(reopened.reference_panes_hidden);
        assert!(reopened.reference_swapped);
        assert_eq!(reopened.reference_panes.len(), 1);
        reopened
            .execute_legacy_palette_command("reference-toggle")
            .unwrap();
        assert!(!reopened.reference_panes_hidden);
        reopened
            .execute_legacy_palette_command("window-maximize")
            .unwrap();
        assert!(reopened.editor_focus_mode);
        reopened
            .execute_legacy_palette_command("window-restore")
            .unwrap();
        assert!(!reopened.editor_focus_mode);
        reopened.open_reference_buffer(
            "fixture:two".into(),
            None,
            "Second reference".into(),
            "second reference text".into(),
        );
        reopened.active_reference = 0;
        reopened.reference_focused = true;
        handle(
            &mut reopened,
            KeyEvent::new(KeyCode::PageDown, KeyModifiers::CONTROL),
        )
        .unwrap();
        assert_eq!(reopened.active_reference, 1);
        assert!(reopened.reference_focused);
        handle(
            &mut reopened,
            KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE),
        )
        .unwrap();
        assert!(!reopened.reference_focused);
        assert_eq!(ReferenceLayout::Stacked.direction(120), Direction::Vertical);
        assert_eq!(
            ReferenceLayout::SideBySide.direction(80),
            Direction::Horizontal
        );
        assert_eq!(ReferenceLayout::Auto.direction(80), Direction::Vertical);
    }

    #[test]
    fn recursive_window_splits_close_and_restore_without_losing_documents() {
        let directory = tempfile::tempdir().unwrap();
        let project = directory.path().join("Novel");
        let mut app = WriterApp::create_project(&project, "Novel").unwrap();
        let chapter = app.create_chapter(None, "Chapter", 0).unwrap();
        let scene = app.create_scene(chapter, "Draft", 0).unwrap();
        let (_, hash) = app.load_scene_text(scene).unwrap();
        app.save_scene_text(scene, Some(&hash), "The manuscript remains intact.")
            .unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.open_scene(scene).unwrap();
        state.pane_bounds = pane_layout::PaneRect {
            x: 0,
            y: 1,
            width: 160,
            height: 50,
        };

        let view_menu = MENU_CATEGORIES
            .iter()
            .position(|category| *category == "View")
            .unwrap();
        state.open_menu_category(view_menu);
        let split_command = state
            .menu_commands()
            .iter()
            .position(|command| command.id == "window.split-side-by-side")
            .expect("View menu exposes side-by-side split");
        state.menu.as_mut().unwrap().selected = split_command;
        state
            .handle_menu_key(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE))
            .unwrap();
        assert_eq!(state.pane_layout.as_ref().unwrap().panes(), vec![1, 2]);
        state.dispatch_registered_command_id("window.grow").unwrap();
        let pane_layout::PaneNode::Split { ratio, .. } = state.pane_layout.as_ref().unwrap().root()
        else {
            panic!("window split should remain active after resize");
        };
        assert_eq!(*ratio, 4_500);
        state
            .split_focused_window(pane_layout::Orientation::Horizontal)
            .unwrap();
        assert_eq!(state.pane_layout.as_ref().unwrap().panes(), vec![1, 2, 3]);
        state
            .split_focused_window(pane_layout::Orientation::Vertical)
            .unwrap();
        assert_eq!(
            state.pane_layout.as_ref().unwrap().panes(),
            vec![1, 2, 3, 4]
        );
        assert!(
            state
                .reference_panes
                .iter()
                .all(|pane| pane.layout_id.is_some())
        );
        state.open_reference_buffer(
            "timeline:project".into(),
            None,
            "Story Timeline".into(),
            "A different view in the focused window".into(),
        );
        assert_eq!(state.reference_panes.len(), 3);
        assert_eq!(
            state
                .reference_panes
                .iter()
                .find(|pane| pane.layout_id == Some(4))
                .unwrap()
                .source_key,
            "timeline:project"
        );

        let mut reopened = AppState::new(
            WriterApp::open_project(&project).unwrap(),
            default_bindings(),
        );
        reopened.restore_session().unwrap();
        assert_eq!(reopened.pane_layout, state.pane_layout);
        assert_eq!(reopened.reference_panes.len(), 3);
        for (width, height) in [(80, 24), (177, 60), (201, 60)] {
            let mut terminal =
                ratatui::Terminal::new(ratatui::backend::TestBackend::new(width, height)).unwrap();
            terminal.draw(|frame| draw(frame, &mut reopened)).unwrap();
        }
        reopened
            .execute_legacy_palette_command("reference-return")
            .unwrap();
        assert_eq!(reopened.pane_layout.as_ref().unwrap().focused(), 1);
        reopened.pane_layout.as_mut().unwrap().focus(4).unwrap();
        reopened.sync_focused_window(4);
        reopened.close_focused_window().unwrap();
        assert_eq!(
            reopened.pane_layout.as_ref().unwrap().panes(),
            vec![1, 2, 3]
        );
        reopened.keep_only_focused_window().unwrap();
        assert_eq!(reopened.pane_layout.as_ref().unwrap().panes().len(), 1);
        assert_eq!(
            reopened.app.load_scene_text(scene).unwrap().0,
            "The manuscript remains intact."
        );
    }

    #[test]
    fn maximize_menu_action_toggles_and_restores_the_exact_recursive_layout() {
        let directory = tempfile::tempdir().unwrap();
        let mut app = WriterApp::create_project(directory.path().join("Novel"), "Novel").unwrap();
        let chapter = app.create_chapter(None, "Chapter", 0).unwrap();
        let scene = app.create_scene(chapter, "Draft", 0).unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.open_scene(scene).unwrap();
        state.pane_bounds = pane_layout::PaneRect {
            x: 0,
            y: 1,
            width: 180,
            height: 50,
        };
        state
            .split_focused_window(pane_layout::Orientation::Vertical)
            .unwrap();
        state
            .split_focused_window(pane_layout::Orientation::Horizontal)
            .unwrap();
        state.pane_layout.as_mut().unwrap().focus(2).unwrap();
        state.sync_focused_window(2);
        state.editor = vec!["Unsaved pane text".into()];
        state.dirty = true;
        let before = state.pane_layout.clone().unwrap();
        let view = MENU_CATEGORIES
            .iter()
            .position(|category| *category == "View")
            .unwrap();
        state.open_menu_category(view);
        let maximize = state
            .menu_commands()
            .into_iter()
            .find(|command| command.id == "window.maximize")
            .unwrap();
        assert_eq!(
            displayed_command_label(&state, maximize),
            "Maximize Current Window"
        );
        assert!(
            !state
                .menu_commands()
                .iter()
                .any(|command| command.id == "window.restore-layout"),
            "the menu should expose one toggle, not competing maximize/restore rows"
        );
        state.menu = None;
        state
            .execute_legacy_palette_command("window-maximize")
            .unwrap();
        assert_eq!(state.pane_layout.as_ref().unwrap().panes(), [2]);
        assert_eq!(
            displayed_command_label(&state, command_by_id("window.maximize").unwrap()),
            "Restore Windows"
        );
        state
            .execute_legacy_palette_command("window-maximize")
            .unwrap();
        assert_eq!(state.pane_layout.as_ref().unwrap(), &before);
        assert_eq!(state.editor, ["Unsaved pane text"]);
        assert!(state.dirty);
    }

