    #[test]
    fn previous_position_without_history_is_a_nonfatal_menu_action_and_preserves_unsaved_text() {
        let directory = tempfile::tempdir().unwrap();
        let mut app = WriterApp::create_project(directory.path().join("Novel"), "Novel").unwrap();
        let chapter = app.create_chapter(None, "Opening", 0).unwrap();
        let scene = app.create_scene(chapter, "At the Gate", 0).unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.open_scene(scene).unwrap();
        state.editor[0].push_str(" Unsaved changes.");
        state.dirty = true;
        let original_editor = state.editor.clone();
        let original_cursor = state.cursor;

        let navigate = MENU_CATEGORIES
            .iter()
            .position(|category| *category == "Navigate")
            .unwrap();
        state.open_menu_category(navigate);
        let previous = state
            .menu_visible_entries()
            .iter()
            .position(|command| command.id == "search.return-position")
            .unwrap();
        state.menu.as_mut().unwrap().selected = previous;
        state
            .handle_menu_key(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE))
            .unwrap();

        assert_eq!(state.workspace, Workspace::Editor);
        assert_eq!(state.editing_scene, Some(scene));
        assert_eq!(state.editor, original_editor);
        assert_eq!(state.cursor, original_cursor);
        assert!(state.dirty);
        assert_eq!(state.message, "No previous manuscript position");

        assert!(!handle_interactive_result(
            &mut state,
            Err("test recoverable command failure".into())
        ));
        assert!(state.message.contains("test recoverable command failure"));
        assert_eq!(state.editor, original_editor);
        assert!(state.dirty);
    }

    #[test]
    fn previous_and_next_manuscript_positions_form_a_safe_bidirectional_history() {
        let directory = tempfile::tempdir().unwrap();
        let mut app = WriterApp::create_project(directory.path().join("Novel"), "Novel").unwrap();
        let chapter = app.create_chapter(None, "Opening", 0).unwrap();
        let first = app.create_scene(chapter, "The Station", 0).unwrap();
        let second = app.create_scene(chapter, "The Market", 1).unwrap();
        for (scene, text) in [
            (first, "Thomas waits beside the station clock."),
            (second, "A unique lantern-marker glows above the market."),
        ] {
            let (_, hash) = app.load_scene_text(scene).unwrap();
            app.save_scene_text(scene, Some(&hash), text).unwrap();
        }
        let mut state = AppState::new(app, default_bindings());
        state.open_scene(first).unwrap();
        state.cursor = (0, 5);

        state.return_to_next_location().unwrap();
        assert_eq!(state.message, "No next manuscript position");
        assert_eq!(state.editing_scene, Some(first));
        assert_eq!(state.cursor, (0, 5));

        state
            .run_named_text_search("lantern-marker", "all")
            .unwrap();
        assert_eq!(state.editing_scene, Some(second));
        assert_eq!(state.location_history.len(), 1);
        state.find_panel = None;
        state.return_to_previous_location().unwrap();
        assert_eq!(state.editing_scene, Some(first));
        assert_eq!(state.cursor, (0, 5));
        assert_eq!(state.forward_location_history.len(), 1);

        state.return_to_next_location().unwrap();
        assert_eq!(state.editing_scene, Some(second));
        assert_eq!(state.forward_location_history.len(), 0);
        assert_eq!(state.location_history.len(), 1);

        state.return_to_previous_location().unwrap();
        assert_eq!(state.editing_scene, Some(first));
        assert!(state.forward_location_history.len() == 1);
        assert_eq!(state.location_history.len(), 0);
    }

