    #[test]
    fn find_replace_fields_are_editable_before_search_and_wildcard_mode_is_explicit() {
        let directory = tempfile::tempdir().unwrap();
        let mut app = WriterApp::create_project(directory.path().join("Novel"), "Novel").unwrap();
        let chapter = app.create_chapter(None, "Chapter", 0).unwrap();
        let scene = app.create_scene(chapter, "First", 0).unwrap();
        let (_, hash) = app.load_scene_text(scene).unwrap();
        app.save_scene_text(scene, Some(&hash), "cat cot cut")
            .unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.open_scene(scene).unwrap();
        open_find_panel(&mut state, true);

        handle(&mut state, KeyEvent::new(KeyCode::Tab, KeyModifiers::NONE)).unwrap();
        assert_eq!(
            state.find_panel.as_ref().unwrap().field,
            FindPanelField::Replacement
        );
        for character in "replacement first".chars() {
            handle(
                &mut state,
                KeyEvent::new(KeyCode::Char(character), KeyModifiers::NONE),
            )
            .unwrap();
        }
        handle(
            &mut state,
            KeyEvent::new(KeyCode::BackTab, KeyModifiers::NONE),
        )
        .unwrap();
        for character in "missing".chars() {
            handle(
                &mut state,
                KeyEvent::new(KeyCode::Char(character), KeyModifiers::NONE),
            )
            .unwrap();
        }
        assert_eq!(
            state.find_panel.as_ref().unwrap().replacement,
            "replacement first"
        );
        assert_eq!(state.find_panel.as_ref().unwrap().pattern, "missing");
        assert!(state.search_locations.is_empty());

        handle(
            &mut state,
            KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE),
        )
        .unwrap();
        assert!(state.find_panel.is_some());
        assert!(state.pending_replace.is_none());
        assert_eq!(
            state.find_panel.as_ref().unwrap().replacement,
            "replacement first"
        );

        handle(&mut state, KeyEvent::new(KeyCode::F(2), KeyModifiers::NONE)).unwrap();
        assert_eq!(
            state.find_panel.as_ref().unwrap().mode,
            story_core::FindMode::Wildcard
        );
        for character in "c?t".chars() {
            handle(
                &mut state,
                KeyEvent::new(KeyCode::Char(character), KeyModifiers::NONE),
            )
            .unwrap();
        }
        let mut terminal =
            ratatui::Terminal::new(ratatui::backend::TestBackend::new(80, 24)).unwrap();
        terminal.draw(|frame| draw(frame, &mut state)).unwrap();
        let rendered = terminal
            .backend()
            .buffer()
            .content()
            .iter()
            .map(|cell| cell.symbol())
            .collect::<String>();
        assert!(rendered.contains("Wildcards (*, ?)") || rendered.contains("Wildcards"));
        assert!(rendered.contains("Tab/Shift+Tab: fields"));
        assert!(rendered.contains("Alt+R: Replace This"));
        assert!(rendered.contains("Enter: Preview all"));
    }

    #[test]
    fn find_replace_shows_a_visible_caret_and_moves_it_by_unicode_grapheme() {
        let directory = tempfile::tempdir().unwrap();
        let mut app = WriterApp::create_project(directory.path().join("Novel"), "Novel").unwrap();
        let chapter = app.create_chapter(None, "Chapter", 0).unwrap();
        let scene = app.create_scene(chapter, "First", 0).unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.open_scene(scene).unwrap();
        open_find_panel(&mut state, true);
        {
            let panel = state.find_panel.as_mut().unwrap();
            panel.pattern = "café".into();
            panel.pattern_cursor = 3;
            panel.field = FindPanelField::Pattern;
        }

        let render = |state: &mut AppState| {
            let mut terminal =
                ratatui::Terminal::new(ratatui::backend::TestBackend::new(80, 24)).unwrap();
            terminal.draw(|frame| draw(frame, state)).unwrap();
            terminal
                .backend()
                .buffer()
                .content()
                .iter()
                .map(|cell| cell.symbol())
                .collect::<String>()
        };
        assert!(render(&mut state).contains("Find: caf▏é"));

        handle(&mut state, KeyEvent::new(KeyCode::Left, KeyModifiers::NONE)).unwrap();
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Char('X'), KeyModifiers::NONE),
        )
        .unwrap();
        assert_eq!(state.find_panel.as_ref().unwrap().pattern, "caXfé");
        assert_eq!(state.find_panel.as_ref().unwrap().pattern_cursor, 3);
        assert!(render(&mut state).contains("caX▏fé"));

        handle(&mut state, KeyEvent::new(KeyCode::Tab, KeyModifiers::NONE)).unwrap();
        assert!(render(&mut state).contains("Replace with: ▏"));
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Char('é'), KeyModifiers::NONE),
        )
        .unwrap();
        handle(&mut state, KeyEvent::new(KeyCode::Left, KeyModifiers::NONE)).unwrap();
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Char('x'), KeyModifiers::NONE),
        )
        .unwrap();
        assert_eq!(state.find_panel.as_ref().unwrap().replacement, "xé");
        assert!(render(&mut state).contains("Replace with: x▏é"));
    }

    #[test]
    fn registered_argument_prompt_hides_internal_command_name() {
        let directory = tempfile::tempdir().unwrap();
        let app = WriterApp::create_project(directory.path().join("Novel"), "Novel").unwrap();
        let mut state = AppState::new(app, default_bindings());
        let command = command_by_id("search.query-assert-save").unwrap();
        state.prompt_for_registered_command(command).unwrap();
        assert_eq!(state.mode, Some(':'));
        assert!(state.hidden_command_prefix_len.is_some());
        assert!(state.prompt.starts_with("query-assert-save "));

        let render = |state: &mut AppState| {
            let mut terminal =
                ratatui::Terminal::new(ratatui::backend::TestBackend::new(100, 30)).unwrap();
            terminal.draw(|frame| draw(frame, state)).unwrap();
            terminal
                .backend()
                .buffer()
                .content()
                .iter()
                .map(|cell| cell.symbol())
                .collect::<String>()
        };
        let initial = render(&mut state);
        assert!(!initial.contains("query-assert-save"), "{initial}");
        assert!(initial.contains("Persist count assertions"), "{initial}");

        for character in "ideas exactly:1".chars() {
            handle(
                &mut state,
                KeyEvent::new(KeyCode::Char(character), KeyModifiers::NONE),
            )
            .unwrap();
        }
        let entered = render(&mut state);
        assert!(entered.contains("ideas exactly:1"), "{entered}");
        assert!(!entered.contains("query-assert-save"), "{entered}");
        handle(&mut state, KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE)).unwrap();
        assert_eq!(state.mode, None);
        assert_eq!(state.hidden_command_prefix_len, None);
    }

