    #[test]
    fn find_panel_history_persists_and_f11_f12_navigate_older_and_draft_queries() {
        let directory = tempfile::tempdir().unwrap();
        let mut app = WriterApp::create_project(directory.path().join("Novel"), "Novel").unwrap();
        let chapter = app.create_chapter(None, "Chapter", 0).unwrap();
        let scene = app.create_scene(chapter, "Scene", 0).unwrap();
        let (_, hash) = app.load_scene_text(scene).unwrap();
        app.save_scene_text(scene, Some(&hash), "Mara met Mira.")
            .unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.open_scene(scene).unwrap();
        open_find_panel(&mut state, false);

        for query in ["Mara", "Mira"] {
            state.find_panel.as_mut().unwrap().pattern = query.into();
            handle(
                &mut state,
                KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE),
            )
            .unwrap();
        }
        let session = load_find_panel_session(state.app.project_root());
        assert_eq!(session.history, vec!["Mira", "Mara"]);

        handle(
            &mut state,
            KeyEvent::new(KeyCode::F(11), KeyModifiers::NONE),
        )
        .unwrap();
        assert_eq!(state.find_panel.as_ref().unwrap().pattern, "Mara");
        handle(
            &mut state,
            KeyEvent::new(KeyCode::F(12), KeyModifiers::NONE),
        )
        .unwrap();
        assert_eq!(state.find_panel.as_ref().unwrap().pattern, "Mira");
        state.command_bindings.push((
            KeyEvent::new(KeyCode::Char('p'), KeyModifiers::CONTROL),
            "search.history-older".into(),
        ));
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Char('p'), KeyModifiers::CONTROL),
        )
        .unwrap();
        assert_eq!(state.find_panel.as_ref().unwrap().pattern, "Mara");
        handle(
            &mut state,
            KeyEvent::new(KeyCode::F(12), KeyModifiers::NONE),
        )
        .unwrap();
        assert_eq!(state.find_panel.as_ref().unwrap().pattern, "Mira");

        state.find_panel.as_mut().unwrap().pattern = "draft query".into();
        state.find_panel.as_mut().unwrap().history_position = None;
        state.find_panel.as_mut().unwrap().history_draft = None;
        handle(
            &mut state,
            KeyEvent::new(KeyCode::F(11), KeyModifiers::NONE),
        )
        .unwrap();
        assert_eq!(state.find_panel.as_ref().unwrap().pattern, "Mira");
        handle(
            &mut state,
            KeyEvent::new(KeyCode::F(12), KeyModifiers::NONE),
        )
        .unwrap();
        assert_eq!(state.find_panel.as_ref().unwrap().pattern, "draft query");

        state.find_panel = None;
        open_find_panel(&mut state, false);
        assert_eq!(state.find_panel.as_ref().unwrap().pattern, "draft query");
        handle(
            &mut state,
            KeyEvent::new(KeyCode::F(11), KeyModifiers::NONE),
        )
        .unwrap();
        assert_eq!(state.find_panel.as_ref().unwrap().pattern, "Mira");
        assert_eq!(
            load_find_panel_session(state.app.project_root()).history,
            vec!["Mira", "Mara"]
        );
    }

    #[test]
    fn scene_cards_reorder_toggle_preserve_text_and_return_to_cards() {
        let directory = tempfile::tempdir().unwrap();
        let mut app = WriterApp::create_project(directory.path().join("Novel"), "Novel").unwrap();
        let chapter = app.create_chapter(None, "Chapter", 0).unwrap();
        let first = app.create_scene(chapter, "First", 0).unwrap();
        let second = app.create_scene(chapter, "Second", 1).unwrap();
        for scene in [first, second] {
            let (_, hash) = app.load_scene_text(scene).unwrap();
            app.save_scene_text(scene, Some(&hash), &format!("Text for {scene}"))
                .unwrap();
        }
        let mut state = AppState::new(app, default_bindings());
        state.refresh().unwrap();
        state.switch(Workspace::Cards);
        state.selected = 1;

        handle(
            &mut state,
            KeyEvent::new(KeyCode::Up, KeyModifiers::CONTROL),
        )
        .unwrap();
        let order = state.app.list_scenes(false).unwrap();
        assert_eq!(order[0].scene.id, second);
        assert_eq!(order[1].scene.id, first);
        assert_eq!(
            state.app.load_scene_text(second).unwrap().0,
            format!("Text for {second}")
        );

        handle(
            &mut state,
            KeyEvent::new(KeyCode::Char(' '), KeyModifiers::NONE),
        )
        .unwrap();
        assert!(!state.app.scene_is_included(second).unwrap());
        assert_eq!(
            state.app.load_scene_text(second).unwrap().0,
            format!("Text for {second}")
        );
        assert!(state.message.contains("text and metadata are retained"));
        let compiled = story_pipeline::compile_ir(&state.app.processing_input().unwrap());
        assert_eq!(
            compiled
                .units
                .iter()
                .map(|unit| unit.id.clone())
                .collect::<Vec<_>>(),
            vec![first.to_string()]
        );

        handle(
            &mut state,
            KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE),
        )
        .unwrap();
        assert_eq!(state.workspace, Workspace::Editor);
        handle(&mut state, KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE)).unwrap();
        assert_eq!(state.workspace, Workspace::Cards);

        let reopened = WriterApp::open_project(state.app.project_root()).unwrap();
        assert!(!reopened.scene_is_included(second).unwrap());
        assert_eq!(
            reopened.load_scene_text(second).unwrap().0,
            format!("Text for {second}")
        );
        assert_eq!(reopened.get_scene(second).unwrap().scene.title, "Second");

        state.selected = scene_card_ids(&state)
            .iter()
            .position(|id| *id == second)
            .unwrap();
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Char(' '), KeyModifiers::NONE),
        )
        .unwrap();
        assert!(state.app.scene_is_included(second).unwrap());
        let recompiled = story_pipeline::compile_ir(&state.app.processing_input().unwrap());
        assert_eq!(
            recompiled
                .units
                .iter()
                .map(|unit| unit.id.clone())
                .collect::<Vec<_>>(),
            vec![second.to_string(), first.to_string()]
        );
    }

    #[test]
    fn scene_cards_render_two_ordered_collections_at_all_widths() {
        let directory = tempfile::tempdir().unwrap();
        let mut app = WriterApp::create_project(directory.path().join("Novel"), "Novel").unwrap();
        let chapter = app.create_chapter(None, "Chapter", 0).unwrap();
        let second_chapter = app.create_chapter(None, "Later Chapter", 1).unwrap();
        let included = app.create_scene(chapter, "Included Card", 0).unwrap();
        let excluded = app.create_scene(chapter, "Excluded Card", 1).unwrap();
        let later = app.create_scene(second_chapter, "Later Card", 0).unwrap();
        let unplaced = app.create_unplaced_scene("Unplaced Card").unwrap();
        app.set_scene_included(excluded, false).unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.refresh().unwrap();
        state.switch(Workspace::Cards);

        for (width, height) in [(80, 24), (120, 30)] {
            let mut terminal =
                ratatui::Terminal::new(ratatui::backend::TestBackend::new(width, height)).unwrap();
            terminal.draw(|frame| draw(frame, &mut state)).unwrap();
            let screen = terminal
                .backend()
                .buffer()
                .content()
                .iter()
                .map(|cell| cell.symbol())
                .collect::<String>();
            assert!(screen.contains("Included ·"));
            assert!(screen.contains("Excluded ·"));
            assert!(screen.contains("Included Card"));
            assert!(screen.contains("Excluded Card"));
            assert!(screen.contains("Chapter"));
        }
        assert!(state.app.scene_is_included(included).unwrap());
        let included_rows = scene_card_rows(&state, true);
        let excluded_rows = scene_card_rows(&state, false);
        for expected in [
            "── Unplaced ──",
            "Unplaced Card",
            "── Chapter ──",
            "Included Card",
            "── Later Chapter ──",
            "Later Card",
        ] {
            assert!(
                included_rows
                    .iter()
                    .any(|(_, _, row)| row.contains(expected))
            );
        }
        assert!(included_rows.iter().any(|(id, _, _)| *id == Some(unplaced)));
        assert!(included_rows.iter().any(|(id, _, _)| *id == Some(later)));
        assert!(
            excluded_rows
                .iter()
                .any(|(id, _, row)| *id == Some(excluded) && row.contains("Excluded ·"))
        );
        let visible_order = included_rows
            .iter()
            .chain(&excluded_rows)
            .filter_map(|(id, _, _)| *id)
            .collect::<Vec<_>>();
        assert_eq!(visible_order, scene_card_ids(&state));
    }

