    #[test]
    fn empty_chapters_are_visible_selectable_reorderable_and_persist_in_scene_cards() {
        let directory = tempfile::tempdir().unwrap();
        let project_path = directory.path().join("Novel");
        let app = WriterApp::create_project(&project_path, "Novel").unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.switch(Workspace::Cards);

        // Exercise the full menu and title-prompt route reported broken in UAT.
        let outline_menu = MENU_CATEGORIES
            .iter()
            .position(|category| *category == "Outline")
            .unwrap();
        state.menu = Some(MenuState {
            top: outline_menu,
            selected: 0,
        });
        state.menu.as_mut().unwrap().selected = state
            .menu_commands()
            .iter()
            .position(|command| command.id == "structure.chapter")
            .unwrap();
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE),
        )
        .unwrap();
        for character in "Alpha".chars() {
            handle(
                &mut state,
                KeyEvent::new(KeyCode::Char(character), KeyModifiers::NONE),
            )
            .unwrap();
        }
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE),
        )
        .unwrap();
        let alpha = state.selected_card_chapter.unwrap().0;
        assert!(
            scene_card_rows(&state, true)
                .iter()
                .any(|(_, chapter, text)| *chapter == Some(alpha) && text.contains("Alpha"))
        );

        // Shift+Insert's title dialogue must create a second empty chapter and
        // leave it selected, without silently assigning the prior selection.
        state.start_chapter_at_selected_card();
        state.prompt = "Beta".into();
        state.command().unwrap();
        let beta = state.selected_card_chapter.unwrap().0;
        assert_ne!(alpha, beta);
        assert!(state.scenes.is_empty());
        assert!(
            scene_card_rows(&state, true)
                .iter()
                .any(|(_, chapter, text)| *chapter == Some(beta) && text.contains("Beta"))
        );

        handle(
            &mut state,
            KeyEvent::new(KeyCode::Down, KeyModifiers::SHIFT),
        )
        .unwrap();
        assert_eq!(state.selected_card_chapter, Some((alpha, true)));
        handle(&mut state, KeyEvent::new(KeyCode::Up, KeyModifiers::SHIFT)).unwrap();
        assert_eq!(state.selected_card_chapter, Some((beta, true)));

        // An empty chapter header is a real selection target. A new scene is
        // created in that chapter; moving the chapter block preserves IDs.
        state.start_scene_creation().unwrap();
        state.prompt = "First scene".into();
        state.mode = Some('N');
        state.command().unwrap();
        let scene = state.scenes[0].0;
        assert_eq!(state.app.get_scene(scene).unwrap().chapter_id, Some(beta));
        state.selected_card_chapter = Some((alpha, true));
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Right, KeyModifiers::SHIFT),
        )
        .unwrap();
        let chapters = state
            .app
            .list_structural_nodes()
            .unwrap()
            .into_iter()
            .filter(|node| node.kind == "chapter")
            .map(|node| node.title)
            .collect::<Vec<_>>();
        assert_eq!(chapters, ["Beta", "Alpha"]);
        assert_eq!(state.app.get_scene(scene).unwrap().chapter_id, Some(beta));

        for (width, height) in [(80, 24), (120, 30)] {
            let mut terminal =
                ratatui::Terminal::new(ratatui::backend::TestBackend::new(width, height)).unwrap();
            terminal.draw(|frame| draw(frame, &mut state)).unwrap();
            let screen = terminal
                .backend()
                .buffer()
                .content()
                .iter()
                .map(|cell| cell.symbol())
                .collect::<String>();
            assert!(screen.contains("Alpha"), "{width}x{height}");
            assert!(screen.contains("Beta"), "{width}x{height}");
        }

        let reopened = WriterApp::open_project(&project_path).unwrap();
        assert_eq!(
            reopened
                .list_structural_nodes()
                .unwrap()
                .into_iter()
                .filter(|node| node.kind == "chapter")
                .map(|node| node.title)
                .collect::<Vec<_>>(),
            ["Beta", "Alpha"]
        );
        assert_eq!(reopened.get_scene(scene).unwrap().chapter_id, Some(beta));
    }

    #[test]
    fn insert_new_chapter_from_outline_renders_and_selects_empty_sibling() {
        let directory = tempfile::tempdir().unwrap();
        let project_path = directory.path().join("Novel");
        let mut app = WriterApp::create_project(&project_path, "Novel").unwrap();
        let section = app.create_section("Part One", 0).unwrap();
        let existing = app
            .create_chapter(Some(section), "Existing Chapter", 0)
            .unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.workspace = Workspace::Outline;
        state.refresh().unwrap();
        state.selected = outline_rows(&state)
            .iter()
            .position(|row| matches!(row, OutlineRow::Chapter { id, .. } if *id == existing))
            .unwrap();

        let command = command_by_id("structure.chapter").unwrap();
        state.prompt_for_registered_command(command).unwrap();
        for character in "New Chapter".chars() {
            handle(
                &mut state,
                KeyEvent::new(KeyCode::Char(character), KeyModifiers::NONE),
            )
            .unwrap();
        }
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE),
        )
        .unwrap();

        assert_eq!(state.workspace, Workspace::Outline);
        let rows = outline_rows(&state);
        let created = match rows.get(state.selected) {
            Some(OutlineRow::Chapter {
                id,
                title,
                scene_count,
                ..
            }) => {
                assert_eq!(title, "New Chapter");
                assert_eq!(*scene_count, 0);
                *id
            }
            other => panic!("new empty chapter was not selected in Outline: {other:?}"),
        };
        let created_node = state
            .app
            .list_structural_nodes()
            .unwrap()
            .into_iter()
            .find(|node| node.id == created)
            .unwrap();
        assert_eq!(created_node.parent_id, Some(section));
        let siblings = state
            .app
            .list_structural_nodes()
            .unwrap()
            .into_iter()
            .filter(|node| node.parent_id == Some(section))
            .map(|node| node.title)
            .collect::<Vec<_>>();
        assert_eq!(siblings, ["New Chapter", "Existing Chapter"]);

        let reopened = WriterApp::open_project(&project_path).unwrap();
        let reopened_outline = AppState::new(reopened, default_bindings());
        assert!(outline_rows(&reopened_outline).iter().any(
            |row| matches!(row, OutlineRow::Chapter { id, title, scene_count: 0, .. } if *id == created && title == "New Chapter")
        ));
    }

    #[test]
    fn scene_cards_render_sections_and_nested_empty_chapters_in_outline_order() {
        let directory = tempfile::tempdir().unwrap();
        let mut app = WriterApp::create_project(directory.path().join("Novel"), "Novel").unwrap();
        let first_section = app.create_section("Part One", 0).unwrap();
        let second_section = app.create_section("Part Two", 1).unwrap();
        let chapter = app
            .create_chapter(Some(first_section), "Opening", 0)
            .unwrap();
        app.create_chapter(Some(second_section), "Aftermath", 0)
            .unwrap();
        let scene = app.create_scene(chapter, "Arrival", 0).unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.refresh().unwrap();
        state.switch(Workspace::Cards);

        let rows = scene_card_rows(&state, true);
        let labels = rows.iter().map(|row| row.2.as_str()).collect::<Vec<_>>();
        assert!(labels.contains(&"── Section: Part One ──"));
        assert!(labels.contains(&"   ── Opening ──"));
        assert!(labels.contains(&"── Section: Part Two ──"));
        assert!(labels.contains(&"   ── Aftermath ──"));
        let part_one = labels
            .iter()
            .position(|label| *label == "── Section: Part One ──")
            .unwrap();
        let opening = labels
            .iter()
            .position(|label| *label == "   ── Opening ──")
            .unwrap();
        let arrival = rows.iter().position(|row| row.0 == Some(scene)).unwrap();
        let part_two = labels
            .iter()
            .position(|label| *label == "── Section: Part Two ──")
            .unwrap();
        assert!(part_one < opening && opening < arrival && arrival < part_two);
    }

    #[test]
    fn scene_cards_move_between_chapters_without_losing_content_or_metadata() {
        let directory = tempfile::tempdir().unwrap();
        let mut app = WriterApp::create_project(directory.path().join("Novel"), "Novel").unwrap();
        let first_chapter = app.create_chapter(None, "Chapter One", 0).unwrap();
        let second_chapter = app.create_chapter(None, "Chapter Two", 1).unwrap();
        let scene = app
            .create_scene(first_chapter, "Travelling Scene", 0)
            .unwrap();
        let mut metadata = app.get_scene(scene).unwrap().scene;
        metadata.synopsis = "Cross-chapter synopsis".into();
        metadata.purpose = "Preserve metadata".into();
        app.update_scene_metadata(&metadata).unwrap();
        let (_, hash) = app.load_scene_text(scene).unwrap();
        app.save_scene_text(scene, Some(&hash), "The scene stays intact.")
            .unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.refresh().unwrap();
        state.switch(Workspace::Cards);
        state.selected = scene_card_ids(&state)
            .iter()
            .position(|id| *id == scene)
            .unwrap();

        state.dispatch_registered_command_id("scene.move").unwrap();
        assert!(state.message.contains("Chapter Two"));
        handle(&mut state, KeyEvent::new(KeyCode::Down, KeyModifiers::NONE)).unwrap();
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE),
        )
        .unwrap();

        let moved = state.app.get_scene(scene).unwrap();
        assert_eq!(moved.chapter_id, Some(second_chapter));
        assert_eq!(moved.scene.synopsis, "Cross-chapter synopsis");
        assert_eq!(moved.scene.purpose, "Preserve metadata");
        assert_eq!(
            state.app.load_scene_text(scene).unwrap().0,
            "The scene stays intact."
        );
        let reloaded = WriterApp::open_project(state.app.project_root()).unwrap();
        assert_eq!(
            reloaded.get_scene(scene).unwrap().chapter_id,
            Some(second_chapter)
        );
        assert_eq!(
            reloaded.get_scene(scene).unwrap().scene.synopsis,
            "Cross-chapter synopsis"
        );
        assert_eq!(
            reloaded.get_scene(scene).unwrap().scene.purpose,
            "Preserve metadata"
        );
        assert_eq!(
            reloaded.load_scene_text(scene).unwrap().0,
            "The scene stays intact."
        );
    }

