    #[test]
    fn menus_are_flat_curated_lists_and_keep_all_commands_searchable() {
        let directory = tempfile::tempdir().unwrap();
        let mut app = WriterApp::create_project(directory.path().join("Novel"), "Novel").unwrap();
        let chapter = app.create_chapter(None, "Chapter", 0).unwrap();
        let scene = app.create_scene(chapter, "Scene", 0).unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.open_scene(scene).unwrap();
        let registered_ids = command_registry()
            .iter()
            .map(|command| command.id)
            .collect::<BTreeSet<_>>();
        assert_eq!(
            command_registry().len(),
            registered_ids.len(),
            "command registry IDs must remain unique for a complete menu inventory"
        );

        for (top, category) in MENU_CATEGORIES.iter().enumerate() {
            for id in MENU_COMMON_COMMANDS[top] {
                if top == OUTLINE_MENU_INDEX {
                    assert!(
                        command_by_id(id).is_some(),
                        "Scene action {id} is unregistered"
                    );
                    continue;
                }
                assert!(
                    command_by_id(id).is_some_and(|command| menu_category(&command) == *category),
                    "{category} curated action {id} is unregistered or miscategorized"
                );
            }
            if top == OUTLINE_MENU_INDEX {
                state.workspace = Workspace::Cards;
            }
            state.menu = Some(MenuState { top, selected: 0 });
            let entries = state.menu_visible_entries();
            let ids = entries.iter().map(|command| command.id).collect::<Vec<_>>();
            let mut expected = MENU_COMMON_COMMANDS[top]
                .iter()
                .copied()
                .filter(|id| {
                    !matches!(
                        *id,
                        "series.remove-selected-book"
                            | "series.removed-books"
                            | "series.restore-selected-book"
                    )
                })
                .collect::<Vec<_>>();
            if top == 4 {
                expected.retain(|id| {
                    matches!(
                        *id,
                        "view.cards"
                            | "view.formatting-marks"
                            | "view.follow-scene-card"
                            | "view.reference-outline"
                            | "view.reference-timeline"
                            | "view.reference-diagnostics"
                            | "window.prefix"
                            | "window.switch-view"
                            | "window.split-side-by-side"
                            | "window.split-top-bottom"
                            | "window.maximize"
                            | "window.save-layout"
                            | "window.load-layout"
                    )
                });
                if state
                    .pane_layout
                    .as_ref()
                    .is_some_and(|layout| layout.pane_count() > 1)
                    || state.reference_panes.len() > 1
                {
                    let maximize = expected
                        .iter()
                        .position(|id| *id == "window.maximize")
                        .unwrap_or(expected.len());
                    expected.splice(maximize..maximize, ["window.grow", "window.shrink"]);
                }
            }
            if top != OUTLINE_MENU_INDEX && category != &"Tools" && category != &"Help" {
                expected.push("command.palette-open");
            }
            assert_eq!(
                ids, expected,
                "{category} should keep common actions directly accessible"
            );
            if *category == "Review" {
                for id in [
                    "analysis.spellcheck",
                    "analysis.thesaurus",
                    "proofread.grammar-check",
                    "proofread.grammar-settings",
                ] {
                    assert!(ids.contains(&id), "Review menu must expose {id}");
                }
            }
            assert!(
                entries.iter().all(|command| !command.id.is_empty()),
                "{category} contains a non-command menu row"
            );
            if *category == "Publish" {
                assert_eq!(
                    ids.iter().filter(|id| **id == "compile.run").count(),
                    1,
                    "Publish should offer Compile once"
                );
            }

            let all_commands = command_registry()
                .into_iter()
                .filter(|command| {
                    !command.id.starts_with("menu.") && menu_category(command) == *category
                })
                .collect::<Vec<_>>();
            let palette_ids = command_palette_candidates("")
                .iter()
                .map(|command| command.id)
                .collect::<BTreeSet<_>>();
            for command in all_commands {
                assert!(
                    palette_ids.contains(command.id),
                    "{} must remain discoverable in Search All Commands",
                    command.id
                );
            }

            let before_tab = state.menu_visible_entries();
            state
                .handle_menu_key(KeyEvent::new(KeyCode::Tab, KeyModifiers::NONE))
                .unwrap();
            state
                .handle_menu_key(KeyEvent::new(KeyCode::BackTab, KeyModifiers::NONE))
                .unwrap();
            assert_eq!(
                state.menu_visible_entries(),
                before_tab,
                "Tab must not change menu views"
            );
        }
    }

    #[test]
    fn menu_rows_fit_compact_terminals_and_keep_effective_shortcuts_visible() {
        let directory = tempfile::tempdir().unwrap();
        let app = WriterApp::create_project(directory.path().join("Novel"), "Novel").unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.menu = Some(MenuState {
            top: 0,
            selected: 0,
        });

        for command in state.menu_commands() {
            let row = menu_command_row(&state, command, 36);
            assert!(
                UnicodeWidthStr::width(row.as_str()) <= 36,
                "{} exceeds the menu row width: {row:?}",
                command.id
            );
        }

        let save = command_by_id("file.save").unwrap();
        let save_row = menu_command_row(&state, save, 36);
        assert!(save_row.contains("Ctrl+S"), "{save_row}");
        assert!(save_row.starts_with("Save Project"), "{save_row}");

        state.menu.as_mut().unwrap().top = 1;
        for (id, shortcut) in [
            ("edit.undo", "Ctrl+Z"),
            ("edit.redo", "Ctrl+Y"),
            ("edit.cut-selection", "Ctrl+X"),
            ("edit.copy-selection", "Ctrl+C"),
            ("edit.paste-clipboard", "Ctrl+V"),
            ("edit.select-all", "Ctrl+A"),
            ("search.find-next", "F3"),
            ("search.find-previous", "Shift+F3"),
        ] {
            let command = command_by_id(id).unwrap();
            let row = menu_command_row(&state, command, 48);
            assert!(row.contains(shortcut), "{id}: {row}");
        }

        let clipped = truncate_display_cells("e\u{301}😀Novel", 4);
        assert!(UnicodeWidthStr::width(clipped.as_str()) <= 4);
        assert!(!clipped.starts_with('\u{301}'));
    }

    #[test]
    fn menu_dropdown_is_compact_and_anchors_to_the_active_menu_root() {
        let directory = tempfile::tempdir().unwrap();
        let app = WriterApp::create_project(directory.path().join("Novel"), "Novel").unwrap();
        let mut state = AppState::new(app, default_bindings());
        let menu = MenuState {
            top: 4,
            selected: 0,
        };
        let bar = menu_bar_line(&state, 80);
        let expected_x = bar.spans[1..(1 + menu.top * 2)]
            .iter()
            .map(|span| UnicodeWidthStr::width(span.content.as_ref()))
            .sum::<usize>()
            + 1;
        assert_eq!(menu_category_x(&state, menu.top) as usize, expected_x);

        let wide = menu_dropdown_rect(Rect::new(0, 0, 80, 24), &state, menu, 30);
        assert_eq!(wide.x as usize, expected_x);
        assert_eq!(wide.y, 1);
        assert_eq!(wide.width, 48);
        assert!(wide.height <= 16);
        assert!(wide.height < 20);

        let narrow = menu_dropdown_rect(Rect::new(0, 0, 40, 24), &state, menu, 30);
        assert_eq!(narrow.x, 0);
        assert_eq!(narrow.width, 40);
        assert!(narrow.width <= 48);

        let resized = menu_dropdown_rect(Rect::new(0, 0, 30, 6), &state, menu, 1);
        assert_eq!(resized.width, 30);
        assert!(resized.height <= 5);
        assert!(resized.y + resized.height <= 6);

        state.command_bindings = vec![(
            KeyEvent::new(KeyCode::Char('f'), KeyModifiers::ALT),
            "menu.file".into(),
        )];
        let remapped_x = menu_category_x(&state, menu.top);
        assert!(remapped_x > wide.x);
    }

    #[test]
    fn menu_is_flat_and_enter_runs_a_direct_action() {
        let directory = tempfile::tempdir().unwrap();
        let app = WriterApp::create_project(directory.path().join("Novel"), "Novel").unwrap();
        let mut state = AppState::new(app, default_bindings());
        let file_menu = MENU_CATEGORIES
            .iter()
            .position(|category| *category == "File")
            .unwrap();
        state.menu = Some(MenuState {
            top: file_menu,
            selected: 0,
        });
        let entries = state.menu_visible_entries();
        assert!(
            entries
                .iter()
                .any(|command| command.id == "file.new-project")
        );
        assert!(entries.iter().all(|command| !command.id.is_empty()));

        let mut terminal =
            ratatui::Terminal::new(ratatui::backend::TestBackend::new(80, 24)).unwrap();
        terminal.draw(|frame| draw(frame, &mut state)).unwrap();
        let screen = terminal
            .backend()
            .buffer()
            .content()
            .iter()
            .map(|cell| cell.symbol())
            .collect::<String>();
        assert!(screen.contains("Enter run"));
        assert!(!screen.contains("> "));
        state
            .handle_menu_key(KeyEvent::new(KeyCode::Right, KeyModifiers::NONE))
            .unwrap();
        assert_eq!(
            state.menu.unwrap().top,
            (file_menu + 1) % MENU_CATEGORIES.len()
        );
        assert!(state.menu.is_some());
        state
            .handle_menu_key(KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE))
            .unwrap();
        assert!(state.menu.is_none());

        state.open_menu_category(file_menu);
        state.menu.as_mut().unwrap().selected = entries
            .iter()
            .position(|command| command.id == "command.palette-open")
            .unwrap();
        state
            .handle_menu_key(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE))
            .unwrap();
        assert!(state.command_palette.is_some());
    }

