    #[test]
    fn insert_menu_offers_a_snippet_chooser_and_moves_configuration_to_tools() {
        let directory = tempfile::tempdir().unwrap();
        let app = WriterApp::create_project(directory.path().join("Novel"), "Novel").unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.snippets.insert("greeting".into(), "Hello".into());
        state.user_snippets.insert("greeting".into(), "Hi".into());

        let insert = MENU_CATEGORIES
            .iter()
            .position(|category| *category == "Insert")
            .unwrap();
        state.menu = Some(MenuState {
            top: insert,
            selected: 0,
        });
        let insert_ids = state
            .menu_commands()
            .iter()
            .map(|command| command.id)
            .collect::<Vec<_>>();
        assert!(insert_ids.contains(&"edit.snippet-insert"));
        assert!(
            !insert_ids
                .iter()
                .any(|id| id.starts_with("edit.snippet-") && *id != "edit.snippet-insert")
        );
        assert!(
            !insert_ids
                .iter()
                .any(|id| id.starts_with("edit.text-expansion"))
        );
        assert_eq!(
            displayed_command_label(&state, command_by_id("edit.snippet-insert").unwrap()),
            "Insert Snippet…"
        );

        let tools = MENU_CATEGORIES
            .iter()
            .position(|category| *category == "Tools")
            .unwrap();
        state.menu = Some(MenuState {
            top: tools,
            selected: 0,
        });
        let tool_ids = state
            .menu_commands()
            .iter()
            .map(|command| command.id)
            .collect::<Vec<_>>();
        assert!(tool_ids.contains(&"edit.text-expansion"));
        assert!(tool_ids.contains(&"edit.text-expansion-user"));
        assert!(tool_ids.contains(&"edit.preferences"));
        assert!(tool_ids.contains(&"edit.snippet-list"));

        state
            .dispatch_registered_command_id("edit.snippet-list")
            .unwrap();
        let palette = state.command_palette.as_ref().unwrap();
        assert_eq!(palette.query, "snippet");
        assert!(
            palette
                .exclude_command_id
                .is_some_and(|id| id == "edit.snippet-list")
        );
        let palette_commands = command_palette_candidates(&palette.query);
        assert!(
            palette_commands
                .iter()
                .any(|command| command.id == "edit.snippet-save")
        );

        state.menu = None;
        state
            .dispatch_registered_command_id("edit.snippet-insert")
            .unwrap();
        assert_eq!(state.snippet_chooser.as_ref().unwrap().choices.len(), 2);
        state.handle_snippet_chooser_key(KeyEvent::new(KeyCode::Down, KeyModifiers::NONE));
        state.handle_snippet_chooser_key(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE));
        assert!(state.snippet_chooser.is_none());
        assert_eq!(state.prompt, "snippet-user-insert greeting ");
        assert!(state.editor.iter().all(String::is_empty));
        state
            .execute_legacy_palette_command("snippet-user-insert greeting")
            .unwrap();
        assert_eq!(state.editor.join(""), "Hi");
    }

    #[test]
    fn special_character_picker_searches_codepoints_inserts_undoably_and_remembers_recent() {
        let directory = tempfile::tempdir().unwrap();
        let project = directory.path().join("Novel");
        let mut app = WriterApp::create_project(&project, "Novel").unwrap();
        let chapter = app.create_chapter(None, "Chapter", 0).unwrap();
        let scene = app.create_scene(chapter, "Scene", 0).unwrap();
        let hash = app.load_scene_text(scene).unwrap().1;
        app.save_scene_text(scene, Some(&hash), "Hello world")
            .unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.open_scene(scene).unwrap();

        state.open_menu_category(2);
        let selected = state
            .menu_visible_entries()
            .iter()
            .position(|command| command.id == "edit.insert-special-character")
            .expect("Insert menu should expose the character picker");
        state.menu.as_mut().unwrap().selected = selected;
        state
            .handle_menu_key(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE))
            .unwrap();
        assert!(state.special_character_picker.is_some());

        for character in "U+2014".chars() {
            state.handle_special_character_picker_key(KeyEvent::new(
                KeyCode::Char(character),
                KeyModifiers::NONE,
            ));
        }
        assert_eq!(
            state
                .special_character_choices(&state.special_character_picker.as_ref().unwrap().query)
                [0]
            .character,
            '—',
            "U+2014 should resolve as an explicit Unicode code point"
        );
        state
            .handle_special_character_picker_key(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE));
        assert!(state.special_character_picker.is_none());
        assert_eq!(state.editor.join("\n"), "—Hello world");
        assert_eq!(
            state
                .editor_preferences
                .recent_special_characters
                .first()
                .map(String::as_str),
            Some("—")
        );
        assert_eq!(
            load_editor_preferences(state.app.project_root())
                .unwrap()
                .recent_special_characters
                .first()
                .map(String::as_str),
            Some("—")
        );
        let invalid_preferences = EditorPreferences {
            recent_special_characters: vec!["two".into()],
            ..EditorPreferences::default()
        };
        assert!(validate_editor_preferences(&invalid_preferences).is_err());

        state.undo_edit();
        assert_eq!(state.editor.join("\n"), "Hello world");
        let original_hash = state.app.load_scene_text(scene).unwrap().1;
        state
            .app
            .save_scene_text(scene, Some(&original_hash), "…Hello world")
            .unwrap();
        let reopened = WriterApp::open_project(&project).unwrap();
        assert_eq!(reopened.load_scene_text(scene).unwrap().0, "…Hello world");

        let mut reopened_state = AppState::new(reopened, default_bindings());
        reopened_state.open_scene(scene).unwrap();
        reopened_state.open_special_character_picker();
        assert_eq!(
            reopened_state.special_character_choices("")[0].character,
            '—'
        );
        reopened_state
            .special_character_picker
            .as_mut()
            .unwrap()
            .query = "ellipsis".into();
        assert_eq!(
            reopened_state.special_character_choices("ellipsis").len(),
            1
        );
        assert_eq!(
            reopened_state.special_character_choices("ellipsis")[0].character,
            '…'
        );
        reopened_state
            .special_character_picker
            .as_mut()
            .unwrap()
            .query = "U+D800".into();
        assert!(
            reopened_state
                .special_character_choices("U+D800")
                .is_empty()
        );
        reopened_state
            .handle_special_character_picker_key(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE));
        assert!(reopened_state.special_character_picker.is_some());
        assert!(reopened_state.message.contains("No matching character"));
        reopened_state
            .handle_special_character_picker_key(KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE));
        assert!(reopened_state.special_character_picker.is_none());
        assert_eq!(reopened_state.editor.join("\n"), "…Hello world");
    }

    #[test]
    fn series_import_offers_inline_series_creation_while_other_actions_explain_prerequisite() {
        let directory = tempfile::tempdir().unwrap();
        let app = WriterApp::create_project(directory.path().join("Novel"), "Novel").unwrap();
        let mut state = AppState::new(app, default_bindings());
        for id in ["series.add-current", "series.new-book", "series.references"] {
            assert_eq!(
                state.command_disabled_reason(command_by_id(id).unwrap()),
                Some("Select or create a series first"),
                "{id} should explain its missing series context"
            );
        }
        assert_eq!(
            state.command_disabled_reason(command_by_id("series.create").unwrap()),
            None
        );

        select_series_menu_action(&mut state, "series.import-scrivener").unwrap();
        assert!(state.menu.is_none());
        assert_eq!(
            state.series_form.as_ref().unwrap().kind,
            SeriesFormKind::CreateSeriesThenImport
        );
        assert!(state.message.contains("Create a series"));
        let series_path = directory.path().join("New Series");
        enter_series_form_values(&mut state, &[series_path.to_str().unwrap(), "New Series"])
            .unwrap();
        assert_eq!(
            state.file_browser.as_ref().unwrap().purpose,
            FileBrowserPurpose::ImportScrivenerSeries
        );
    }

    #[test]
    fn persistent_menu_bar_adapts_to_available_width_and_effective_menu_keymap() {
        let dir = tempfile::tempdir().unwrap();
        let app = WriterApp::create_project(dir.path().join("Novel"), "Novel").unwrap();
        let mut state = AppState::new(app, default_bindings());
        let wide = menu_bar_line(&state, 80)
            .spans
            .iter()
            .map(|span| span.content.as_ref())
            .collect::<String>();
        for category in MENU_CATEGORIES {
            if category == "Outline" {
                assert!(
                    !wide.contains(category),
                    "Outline is contextual to manuscript outliners"
                );
                continue;
            }
            assert!(wide.contains(category), "missing menu root {category}");
        }
        let chapter = state.app.create_chapter(None, "Chapter", 0).unwrap();
        state.app.create_scene(chapter, "Scene", 0).unwrap();
        state.refresh().unwrap();
        state.workspace = Workspace::Cards;
        let cards = menu_bar_line(&state, 80)
            .spans
            .iter()
            .map(|span| span.content.as_ref())
            .collect::<String>();
        assert!(cards.contains("Outline"), "{cards}");
        assert!(!cards.contains("Publish"), "{cards}");
        state.workspace = Workspace::Dashboard;
        let narrow = menu_bar_line(&state, 40)
            .spans
            .iter()
            .map(|span| span.content.as_ref())
            .collect::<String>();
        assert!(
            narrow.contains("hold Ctrl, press / or Alt+M or F10 Menu"),
            "{narrow:?}"
        );

        state.command_bindings = vec![(
            KeyEvent::new(KeyCode::Char('m'), KeyModifiers::ALT),
            "menu.main".into(),
        )];
        let remapped = menu_bar_line(&state, 40)
            .spans
            .iter()
            .map(|span| span.content.as_ref())
            .collect::<String>();
        assert!(remapped.contains("Alt+M Menu"));
    }

    #[test]
    fn each_top_level_menu_has_a_stable_directly_bindable_command() {
        let directory = tempfile::tempdir().unwrap();
        let app = WriterApp::create_project(directory.path().join("Novel"), "Novel").unwrap();
        let mut state = AppState::new(app, default_bindings());
        for (index, id) in MENU_CATEGORY_COMMAND_IDS.iter().enumerate() {
            let command = command_by_id(id).expect("each menu root has a registered command");
            assert_eq!(command.action, CommandAction::OpenMenuCategory(index));
            assert_eq!(command.category, "Menu");
        }
        state.command_bindings = vec![(
            KeyEvent::new(KeyCode::Char('f'), KeyModifiers::ALT),
            "menu.file".into(),
        )];
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Char('f'), KeyModifiers::ALT),
        )
        .unwrap();
        assert_eq!(state.menu.map(|menu| menu.top), Some(0));
        let bar = menu_bar_line(&state, 80)
            .spans
            .iter()
            .map(|span| span.content.as_ref())
            .collect::<String>();
        assert!(bar.contains("File Alt+F"));

        state.menu = Some(MenuState {
            top: 0,
            selected: 0,
        });
        state.command_bindings.push((
            KeyEvent::new(KeyCode::Char('i'), KeyModifiers::ALT),
            "menu.insert".into(),
        ));
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Char('i'), KeyModifiers::ALT),
        )
        .unwrap();
        assert_eq!(state.menu.map(|menu| menu.top), Some(2));
    }

