    #[test]
    fn new_projects_use_a_single_writing_canvas_with_persistent_menu_and_status() {
        let directory = tempfile::tempdir().unwrap();
        let mut app = WriterApp::create_project(directory.path().join("Novel"), "Novel").unwrap();
        let chapter = app.create_chapter(None, "Chapter One", 0).unwrap();
        let scene = app.create_scene(chapter, "Opening", 0).unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.open_scene(scene).unwrap();
        state.editor = vec!["A sentence ready for drafting.".into()];
        assert!(state.editor_focus_mode);
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Char('s'), KeyModifiers::CONTROL),
        )
        .unwrap();

        let backend = ratatui::backend::TestBackend::new(80, 24);
        let mut terminal = ratatui::Terminal::new(backend).unwrap();
        terminal.draw(|frame| draw(frame, &mut state)).unwrap();
        let rendered = terminal
            .backend()
            .buffer()
            .content()
            .iter()
            .map(|cell| cell.symbol())
            .collect::<String>();
        assert!(rendered.contains("File"));
        assert!(rendered.contains("A sentence ready for drafting."));
        assert!(
            rendered.contains("Novel > Chapter One > Opening"),
            "{rendered:?}"
        );
        assert!(rendered.contains("[SAVED]"));
        assert!(rendered.contains("Saved"));
        assert!(state.message.starts_with("Saved at "));
        assert!(state.message.ends_with(" UTC"));
        assert!(!rendered.contains(&scene.to_string()));
        assert!(!rendered.contains("Scenes"));

        state.dirty = true;
        state.message = "Save conflict/error: the file changed on disk".into();
        terminal.draw(|frame| draw(frame, &mut state)).unwrap();
        let failed = terminal
            .backend()
            .buffer()
            .content()
            .iter()
            .map(|cell| cell.symbol())
            .collect::<String>();
        assert!(failed.contains("[SAVE FAILED]"));

        state.dirty = false;
        state.message = "Autosaved".into();
        terminal.draw(|frame| draw(frame, &mut state)).unwrap();
        let autosaved = terminal
            .backend()
            .buffer()
            .content()
            .iter()
            .map(|cell| cell.symbol())
            .collect::<String>();
        assert!(autosaved.contains("[AUTOSAVED]"));
    }

    #[test]
    fn manuscript_and_reference_text_stay_contiguous_across_resizes_and_view_changes() {
        let directory = tempfile::tempdir().unwrap();
        let mut app = WriterApp::create_project(directory.path().join("Novel"), "Novel").unwrap();
        let chapter = app.create_chapter(None, "Chapter One", 0).unwrap();
        let scene = app.create_scene(chapter, "Opening", 0).unwrap();
        let manuscript = "Maqrara opened the old book and found a note inside.\nA longer paragraph wraps without separating individual words or leaking past its pane.\n\nThe final paragraph remains visible after the blank line.";
        let (_, hash) = app.load_scene_text(scene).unwrap();
        app.save_scene_text(scene, Some(&hash), manuscript).unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.open_scene(scene).unwrap();
        let editor_surface = render_context_key(&state);

        let mut terminal =
            ratatui::Terminal::new(ratatui::backend::TestBackend::new(201, 60)).unwrap();
        for (width, height) in [(177, 60), (80, 24), (201, 60)] {
            terminal.backend_mut().resize(width, height);
            terminal.clear().unwrap();
            terminal.draw(|frame| draw(frame, &mut state)).unwrap();
            let screen = terminal
                .backend()
                .buffer()
                .content()
                .iter()
                .map(|cell| cell.symbol())
                .collect::<String>();
            // Narrow side-by-side layouts legitimately wrap sentences between words.
            // Check that words remain contiguous in terminal cells, which catches the
            // reported letter-spacing corruption without assuming a particular pane width.
            for word in [
                "Maqrara",
                "opened",
                "book",
                "found",
                "inside.",
                "longer",
                "paragraph",
                "wraps",
                "separating",
                "individual",
                "words",
                "leaking",
                "pane.",
            ] {
                assert!(
                    screen.contains(word),
                    "{width}x{height}, missing {word}: {screen:?}"
                );
            }

            state.open_reference_buffer(
                "test:reference-render".into(),
                None,
                "Reference Test".into(),
                "Reference text remains together on resize.".into(),
            );
            state.reference_focused = true;
            terminal.draw(|frame| draw(frame, &mut state)).unwrap();
            let reference_screen = terminal
                .backend()
                .buffer()
                .content()
                .iter()
                .map(|cell| cell.symbol())
                .collect::<String>();
            assert!(
                reference_screen.contains("Reference text remains together on resize."),
                "{width}x{height}: {reference_screen:?}"
            );

            state.reference_focused = false;
            state.workspace = Workspace::Reading;
            state.reading_text = "Library-only text appears in its own reading pane.".into();
            state.message.clear();
            assert_ne!(render_context_key(&state), editor_surface);
            terminal.draw(|frame| draw(frame, &mut state)).unwrap();
            let reading_screen = terminal
                .backend()
                .buffer()
                .content()
                .iter()
                .map(|cell| cell.symbol())
                .collect::<String>();
            assert!(reading_screen.contains("Library-only text appears in its own reading pane."));
            assert!(
                !reading_screen.contains(manuscript),
                "{width}x{height}: {reading_screen:?}"
            );

            state.workspace = Workspace::Editor;
            state.reading_text.clear();
            state.help_panel = Some(HelpPanel {
                title: "Tutorial · Find your way around · 1/6".into(),
                lines: vec![
                    "Lesson 1 complete".into(),
                    "▶ Continue to Lesson 2 · press Enter".into(),
                    "Esc: return to navigation".into(),
                ],
                scroll: 0,
            });
            assert_ne!(render_context_key(&state), editor_surface);
            terminal.draw(|frame| draw(frame, &mut state)).unwrap();
            let tutorial_screen = terminal
                .backend()
                .buffer()
                .content()
                .iter()
                .map(|cell| cell.symbol())
                .collect::<String>();
            assert!(tutorial_screen.contains("Lesson 1 complete"));
            assert!(tutorial_screen.contains("▶ Continue to Lesson 2 · press Enter"));
            state.help_panel = None;
            state.menu = Some(MenuState {
                top: 0,
                selected: 0,
            });
            assert_ne!(render_context_key(&state), editor_surface);
            terminal.draw(|frame| draw(frame, &mut state)).unwrap();
            state.menu = None;
            terminal.draw(|frame| draw(frame, &mut state)).unwrap();
            let after_menu_close = terminal
                .backend()
                .buffer()
                .content()
                .iter()
                .map(|cell| cell.symbol())
                .collect::<String>();
            for word in ["Maqrara", "opened", "book", "found", "note"] {
                assert!(
                    after_menu_close.contains(word),
                    "{width}x{height}, missing {word}: {after_menu_close:?}"
                );
            }
        }

        let (_, saved_hash) = state.app.load_scene_text(scene).unwrap();
        assert_eq!(saved_hash, state.saved_hash);
        assert_eq!(state.app.load_scene_text(scene).unwrap().0, manuscript);
    }

    #[test]
    fn primary_destinations_are_easy_to_cycle_and_card_view_is_an_outline_presentation() {
        let directory = tempfile::tempdir().unwrap();
        let app = WriterApp::create_project(directory.path().join("Novel"), "Novel").unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.workspace = Workspace::Outline;
        handle(&mut state, KeyEvent::new(KeyCode::Tab, KeyModifiers::NONE)).unwrap();
        assert_eq!(state.workspace, Workspace::Reading);
        assert_eq!(destination_title(state.workspace), "Reference");
        handle(&mut state, KeyEvent::new(KeyCode::Tab, KeyModifiers::NONE)).unwrap();
        assert_eq!(state.workspace, Workspace::Editor);
        state.workspace = Workspace::Outline;
        handle(
            &mut state,
            KeyEvent::new(KeyCode::BackTab, KeyModifiers::SHIFT),
        )
        .unwrap();
        assert_eq!(state.workspace, Workspace::Editor);

        state.workspace = Workspace::Analytics;
        handle(&mut state, KeyEvent::new(KeyCode::Tab, KeyModifiers::NONE)).unwrap();
        assert_eq!(state.workspace, Workspace::Editor);

        let navigate = MENU_CATEGORIES
            .iter()
            .position(|name| *name == "Navigate")
            .unwrap();
        state.menu = Some(MenuState {
            top: navigate,
            selected: 0,
        });
        let common = state
            .menu_commands()
            .into_iter()
            .map(|command| command.label)
            .collect::<Vec<_>>();
        assert!(common.starts_with(&["Manuscript", "Outline", "Reference"]));

        let every_view = state
            .menu_commands()
            .into_iter()
            .map(|command| command.id)
            .collect::<Vec<_>>();
        assert!(!every_view.contains(&"view.cards"));
        assert!(!every_view.contains(&"view.analytics"));
        let view_menu = MENU_CATEGORIES
            .iter()
            .position(|name| *name == "View")
            .unwrap();
        state.menu = Some(MenuState {
            top: view_menu,
            selected: 0,
        });
        let card_view = state
            .menu_commands()
            .into_iter()
            .find(|command| command.id == "view.cards")
            .expect("View menu offers the card presentation");
        assert_eq!(card_view.label, "Show Scene Cards");
        state.workspace = Workspace::Cards;
        assert_eq!(Workspace::Cards.title(), "Outline · Scene Cards");
        let tree_view = state
            .menu_commands()
            .into_iter()
            .find(|command| command.id == "view.cards")
            .expect("card view can return to the outline tree");
        assert_eq!(tree_view.label, "Show Outline Tree");
        assert!(
            command_palette_candidates("Analytics")
                .iter()
                .any(|command| command.id == "view.analytics")
        );
    }

