    #[test]
    fn background_grammar_check_runs_off_thread_after_a_successful_save() {
        let directory = tempfile::tempdir().unwrap();
        let mut app = WriterApp::create_project(directory.path().join("Novel"), "Novel").unwrap();
        app.set_project_language("en-GB").unwrap();
        let chapter = app.create_chapter(None, "Chapter", 0).unwrap();
        let scene = app.create_scene(chapter, "Scene", 0).unwrap();
        let mut config = app.proofreading_config().unwrap();
        config.grammar.background_enabled = true;
        app.save_proofreading_config(&config).unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.open_scene(scene).unwrap();
        state.editor = vec!["They is ready.".into()];
        state.dirty = true;
        state.save().unwrap();

        let deadline = Instant::now() + Duration::from_secs(30);
        while Instant::now() < deadline {
            state.poll_background_grammar().unwrap();
            if !state.reference_panes.is_empty() {
                break;
            }
            std::thread::sleep(Duration::from_millis(50));
        }
        assert!(state.reference_panes[0].content.contains("Agreement"));
        assert_eq!(
            state.app.load_scene_text(scene).unwrap().0,
            "They is ready."
        );
    }

    #[test]
    fn superseded_background_grammar_results_are_discarded_by_generation() {
        let directory = tempfile::tempdir().unwrap();
        let project_path = directory.path().join("Novel");
        let mut app = WriterApp::create_project(&project_path, "Novel").unwrap();
        app.set_project_language("en-GB").unwrap();
        let chapter = app.create_chapter(None, "Chapter", 0).unwrap();
        let scene = app.create_scene(chapter, "Scene", 0).unwrap();
        let (_, source_hash) = app.load_scene_text(scene).unwrap();
        let source_hash = app
            .save_scene_text(scene, Some(&source_hash), "They is ready.")
            .unwrap();
        let project_root = project_path.canonicalize().unwrap();
        let project_root_text = project_root.to_string_lossy().into_owned();
        let project_scene_key = format!("{project_root_text}:{scene}");
        let generations = Arc::new(Mutex::new(BTreeMap::new()));
        let stale_generation =
            next_grammar_job_generation(&generations, &project_scene_key).unwrap();
        let current_generation =
            next_grammar_job_generation(&generations, &project_scene_key).unwrap();
        assert!(!grammar_job_generation_is_current(
            &generations,
            &project_scene_key,
            stale_generation
        ));
        assert!(grammar_job_generation_is_current(
            &generations,
            &project_scene_key,
            current_generation
        ));

        let (job_sender, _job_receiver) = mpsc::channel();
        let (result_sender, result_receiver) = mpsc::channel();
        let mut state = AppState::new(app, default_bindings());
        state.grammar_worker = Some(GrammarBackgroundWorker {
            sender: job_sender,
            receiver: result_receiver,
            generations: Arc::clone(&generations),
        });
        let make_result = |result_project_root: String, generation| GrammarBackgroundResult {
            scene_id: scene,
            scene_title: "Scene".into(),
            project_root: result_project_root,
            source_hash: source_hash.clone(),
            generation,
            result: Ok(story_analysis::GrammarCheckReport {
                findings: Vec::new(),
                unsupported_languages: Vec::new(),
            }),
            notes: Vec::new(),
        };
        result_sender
            .send(make_result(project_root_text.clone(), stale_generation))
            .unwrap();
        state.poll_background_grammar().unwrap();
        assert!(state.reference_panes.is_empty());

        let other_project_root = format!("{project_root_text}-other");
        let other_project_scene_key = format!("{other_project_root}:{scene}");
        let other_project_generation =
            next_grammar_job_generation(&generations, &other_project_scene_key).unwrap();
        result_sender
            .send(make_result(other_project_root, other_project_generation))
            .unwrap();
        state.poll_background_grammar().unwrap();
        assert!(state.reference_panes.is_empty());

        result_sender
            .send(make_result(project_root_text.clone(), current_generation))
            .unwrap();
        state.poll_background_grammar().unwrap();
        assert_eq!(state.reference_panes.len(), 1);
    }

    #[test]
    fn grammar_report_acceptance_uses_the_editor_undo_stack_and_ignores_once() {
        let directory = tempfile::tempdir().unwrap();
        let mut app = WriterApp::create_project(directory.path().join("Novel"), "Novel").unwrap();
        app.set_project_language("en-GB").unwrap();
        let chapter = app.create_chapter(None, "Chapter", 0).unwrap();
        let scene = app.create_scene(chapter, "Scene", 0).unwrap();
        let original = "Mara said, \"They is ready.\"";
        let (_, hash) = app.load_scene_text(scene).unwrap();
        app.save_scene_text(scene, Some(&hash), original).unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.open_scene(scene).unwrap();
        state
            .dispatch_registered_command_id("proofread.grammar-check")
            .unwrap();

        assert!(
            !state.reference_panes[0]
                .proofreading
                .as_ref()
                .unwrap()
                .findings
                .is_empty()
        );
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Char('a'), KeyModifiers::NONE),
        )
        .unwrap();
        let accepted = state.app.load_scene_text(scene).unwrap().0;
        assert!(accepted.contains("They are ready."), "{accepted}");
        assert!(!state.reference_focused);
        assert_eq!(state.undo_stack.len(), 1);

        handle(
            &mut state,
            KeyEvent::new(KeyCode::Char('z'), KeyModifiers::CONTROL),
        )
        .unwrap();
        assert_eq!(state.editor.join("\n"), original);
        assert!(state.dirty);
        // Undo is the normal in-memory editor operation; saving it restores
        // the pre-suggestion manuscript through the journalled write path.
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Char('s'), KeyModifiers::CONTROL),
        )
        .unwrap();
        assert_eq!(state.app.load_scene_text(scene).unwrap().0, original);
    }

