    #[test]
    fn external_text_file_opens_read_only_and_copies_visible_line_into_manuscript() {
        let directory = tempfile::tempdir().unwrap();
        let project = directory.path().join("Novel");
        let mut app = WriterApp::create_project(&project, "Novel").unwrap();
        let chapter = app.create_chapter(None, "Chapter", 0).unwrap();
        let scene = app.create_scene(chapter, "Scene", 0).unwrap();
        let external = directory.path().join("outside.org");
        let external_text = "* Research note\n\nA copied paragraph stays external.";
        fs::write(&external, external_text).unwrap();
        let original = fs::read(&external).unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.open_scene(scene).unwrap();
        state
            .start_file_browser(FileBrowserPurpose::OpenTextFile)
            .unwrap();
        let browser = state.file_browser.as_mut().unwrap();
        browser.current_dir = directory.path().to_owned();
        browser.entries = file_browser_entries(directory.path()).unwrap();
        browser.selected = browser
            .entries
            .iter()
            .position(|(name, is_dir)| name == "outside.org" && !is_dir)
            .unwrap();

        state
            .handle_file_browser_key(KeyEvent::new(KeyCode::F(5), KeyModifiers::NONE))
            .unwrap();

        assert!(state.file_browser.is_none());
        assert_eq!(state.workspace, Workspace::Editor);
        assert!(state.reference_focused);
        assert_eq!(
            state.active_reference_pane().unwrap().content,
            external_text
        );
        assert_eq!(state.app.list_reading_documents().unwrap().len(), 0);
        assert!(!state.dirty);
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Char('v'), KeyModifiers::NONE),
        )
        .unwrap();
        handle(&mut state, KeyEvent::new(KeyCode::Down, KeyModifiers::NONE)).unwrap();
        handle(&mut state, KeyEvent::new(KeyCode::Down, KeyModifiers::NONE)).unwrap();
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Char('c'), KeyModifiers::CONTROL),
        )
        .unwrap();
        assert_eq!(
            state.clipboard,
            "* Research note\n\nA copied paragraph stays external."
        );
        assert_eq!(
            state.pending_terminal_clipboard.as_deref(),
            Some("* Research note\n\nA copied paragraph stays external.")
        );
        assert_eq!(
            terminal_clipboard_sequence("A ✓"),
            Some("\x1b]52;c;QSDinJM=\x07".into())
        );
        assert!(
            terminal_clipboard_sequence(&"x".repeat(MAX_OSC52_PAYLOAD_BYTES * 3 / 4 + 1)).is_none()
        );
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Tab, KeyModifiers::CONTROL),
        )
        .unwrap();
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Char('v'), KeyModifiers::CONTROL),
        )
        .unwrap();
        assert!(
            state
                .editor
                .join("\n")
                .contains("* Research note\n\nA copied paragraph stays external.")
        );
        state.save().unwrap();
        assert_eq!(fs::read(&external).unwrap(), original);
    }

    #[test]
    fn org_import_previews_single_or_heading_mode_before_creating_any_content() {
        let directory = tempfile::tempdir().unwrap();
        let project = directory.path().join("Novel");
        let app = WriterApp::create_project(&project, "Novel").unwrap();
        let source = directory.path().join("outline.org");
        let source_text = "* Act One\nIntroduction prose.\n** Opening\nThe door opens.\n** Decision\nMara chooses.";
        fs::write(&source, source_text).unwrap();
        let original = fs::read(&source).unwrap();
        let mut state = AppState::new(app, default_bindings());
        state
            .dispatch_registered_command_id("file.import-document")
            .unwrap();
        let browser = state.file_browser.as_mut().unwrap();
        browser.current_dir = directory.path().to_owned();
        browser.entries = file_browser_entries(directory.path()).unwrap();
        browser.selected = browser
            .entries
            .iter()
            .position(|(name, is_dir)| name == "outline.org" && !is_dir)
            .unwrap();
        let initial_nodes = state.app.list_structural_nodes().unwrap();

        state
            .handle_file_browser_key(KeyEvent::new(KeyCode::F(5), KeyModifiers::NONE))
            .unwrap();
        assert!(
            state
                .file_browser
                .as_ref()
                .unwrap()
                .text_import_preview
                .is_some()
        );
        assert_eq!(
            state.app.list_structural_nodes().unwrap().len(),
            initial_nodes.len()
        );
        let mut terminal =
            ratatui::Terminal::new(ratatui::backend::TestBackend::new(80, 24)).unwrap();
        terminal.draw(|frame| draw(frame, &mut state)).unwrap();
        let screen = terminal
            .backend()
            .buffer()
            .content()
            .iter()
            .map(|cell| cell.symbol())
            .collect::<String>();
        assert!(screen.contains("Import Document · Preview"));
        assert!(screen.contains("Enter Import"));

        state
            .handle_file_browser_key(KeyEvent::new(KeyCode::F(2), KeyModifiers::NONE))
            .unwrap();
        let preview = state
            .file_browser
            .as_ref()
            .unwrap()
            .text_import_preview
            .as_ref()
            .unwrap();
        assert_eq!(preview.units.len(), 3);
        assert_eq!(preview.units[0].heading_level, Some(1));
        assert_eq!(preview.units[1].heading_level, Some(2));
        assert!(state.app.list_structural_nodes().unwrap().is_empty());

        state
            .handle_file_browser_key(KeyEvent::new(KeyCode::F(5), KeyModifiers::NONE))
            .unwrap();
        assert!(state.file_browser.is_none());
        let chapters = state
            .app
            .list_structural_nodes()
            .unwrap()
            .into_iter()
            .filter(|node| node.kind == "chapter")
            .collect::<Vec<_>>();
        assert_eq!(chapters.len(), 1);
        assert_eq!(chapters[0].title, "Act One");
        assert_eq!(state.scenes.len(), 3);
        let imported = state.app.list_scenes(false).unwrap();
        let opening = imported
            .iter()
            .find(|record| record.scene.title == "Act One — opening")
            .unwrap();
        assert!(
            state
                .app
                .load_scene_text(opening.scene.id)
                .unwrap()
                .0
                .contains("Introduction prose.")
        );
        let first_scene = imported
            .iter()
            .find(|record| record.scene.title == "Opening")
            .unwrap();
        assert_eq!(
            state.app.load_scene_text(first_scene.scene.id).unwrap().0,
            "The door opens."
        );
        let second_scene = imported
            .iter()
            .find(|record| record.scene.title == "Decision")
            .unwrap();
        assert_eq!(
            state.app.load_scene_text(second_scene.scene.id).unwrap().0,
            "Mara chooses."
        );
        let reopened = WriterApp::open_project(&project).unwrap();
        assert_eq!(
            reopened.load_scene_text(first_scene.scene.id).unwrap().0,
            "The door opens."
        );
        assert_eq!(fs::read(source).unwrap(), original);
    }

