    #[test]
    fn edit_menu_formatting_actions_indent_reflow_change_case_and_undo() {
        let directory = tempfile::tempdir().unwrap();
        let project = directory.path().join("Novel");
        let mut app = WriterApp::create_project(&project, "Novel").unwrap();
        let chapter = app.create_chapter(None, "Chapter", 0).unwrap();
        let scene = app.create_scene(chapter, "Scene", 0).unwrap();
        let hash = app.load_scene_text(scene).unwrap().1;
        app.save_scene_text(
            scene,
            Some(&hash),
            "the FIRST line wraps\nacross lines but keeps its words",
        )
        .unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.open_scene(scene).unwrap();

        let run_edit_menu = |state: &mut AppState, command_id: &str| {
            state.open_menu_category(1);
            let selected = state
                .menu_visible_entries()
                .iter()
                .position(|command| command.id == command_id)
                .unwrap_or_else(|| panic!("{command_id} is absent from the Edit menu"));
            state.menu.as_mut().unwrap().selected = selected;
            state
                .handle_menu_key(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE))
                .unwrap();
        };

        state.cursor = (0, 0);
        run_edit_menu(&mut state, "edit.indent");
        assert!(
            state.editor[0].starts_with("\tthe FIRST"),
            "{} / {:?}",
            state.message,
            state.editor
        );
        run_edit_menu(&mut state, "edit.unindent");
        assert_eq!(state.editor[0], "the FIRST line wraps");

        state.editor_selection = Some((0, 0));
        state.cursor = (0, 9);
        run_edit_menu(&mut state, "edit.uppercase");
        assert_eq!(state.editor[0], "THE FIRST line wraps");
        run_edit_menu(&mut state, "edit.undo");
        assert_eq!(state.editor[0], "the FIRST line wraps");

        state.editor_selection = None;
        state.cursor = (0, 0);
        run_edit_menu(&mut state, "edit.title-case");
        assert_eq!(state.editor[0], "The First Line Wraps");
        run_edit_menu(&mut state, "edit.lowercase");
        assert_eq!(state.editor[0], "the first line wraps");

        let long_line = format!("{} second line", "word ".repeat(18).trim_end());
        state.editor = vec![long_line.clone()];
        state.cursor = (0, 0);
        state.editor_selection = None;
        run_edit_menu(&mut state, "edit.reflow-paragraph");
        assert!(state.editor.len() > 1);
        assert_eq!(state.editor.join(" ").split_whitespace().count(), 20);
        run_edit_menu(&mut state, "edit.undo");
        assert_eq!(state.editor.join("\n"), long_line);
    }

    #[test]
    fn insert_date_time_and_file_are_menu_driven_undoable_and_leave_sources_unchanged() {
        let directory = tempfile::tempdir().unwrap();
        let project = directory.path().join("Novel");
        let mut app = WriterApp::create_project(&project, "Novel").unwrap();
        let chapter = app.create_chapter(None, "Chapter", 0).unwrap();
        let scene = app.create_scene(chapter, "Scene", 0).unwrap();
        let hash = app.load_scene_text(scene).unwrap().1;
        app.save_scene_text(scene, Some(&hash), "Opening").unwrap();

        let source = directory.path().join("inserted.md");
        let source_text = "\nImported quotation, kept in its source file.";
        fs::write(&source, source_text).unwrap();
        let original_source = fs::read(&source).unwrap();

        let mut state = AppState::new(app, default_bindings());
        state.open_scene(scene).unwrap();
        state.cursor = (0, "Opening".graphemes(true).count());
        state.editor_preferences.time_zone = "utc".into();
        state.open_menu_category(2);
        let date_time = state
            .menu_visible_entries()
            .iter()
            .position(|command| command.id == "edit.insert-date-time")
            .unwrap();
        state.menu.as_mut().unwrap().selected = date_time;
        state
            .handle_menu_key(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE))
            .unwrap();
        assert!(state.editor.join("\n").contains(" UTC"));
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Char('z'), KeyModifiers::CONTROL),
        )
        .unwrap();
        assert_eq!(state.editor.join("\n"), "Opening");

        for (command_id, expected_label) in [
            ("edit.insert-date", "Inserted date"),
            ("edit.insert-time", "Inserted time"),
        ] {
            state.open_menu_category(2);
            let selected = state
                .menu_visible_entries()
                .iter()
                .position(|command| command.id == command_id)
                .unwrap();
            state.menu.as_mut().unwrap().selected = selected;
            state
                .handle_menu_key(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE))
                .unwrap();
            assert!(state.message.contains(expected_label));
            handle(
                &mut state,
                KeyEvent::new(KeyCode::Char('z'), KeyModifiers::CONTROL),
            )
            .unwrap();
            assert_eq!(state.editor.join("\n"), "Opening");
        }

        state.open_menu_category(2);
        let insert_file = state
            .menu_visible_entries()
            .iter()
            .position(|command| command.id == "edit.insert-file")
            .unwrap();
        state.menu.as_mut().unwrap().selected = insert_file;
        state
            .handle_menu_key(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE))
            .unwrap();
        let browser = state.file_browser.as_mut().unwrap();
        browser.current_dir = directory.path().to_owned();
        browser.entries = file_browser_entries(directory.path()).unwrap();
        browser.selected = browser
            .entries
            .iter()
            .position(|(name, is_dir)| name == "inserted.md" && !is_dir)
            .unwrap();
        state
            .handle_file_browser_key(KeyEvent::new(KeyCode::F(5), KeyModifiers::NONE))
            .unwrap();
        assert!(state.file_browser.is_none());
        assert_eq!(
            state.editor.join("\n"),
            "Opening\nImported quotation, kept in its source file."
        );
        assert_eq!(fs::read(&source).unwrap(), original_source);

        handle(
            &mut state,
            KeyEvent::new(KeyCode::Char('z'), KeyModifiers::CONTROL),
        )
        .unwrap();
        assert_eq!(state.editor.join("\n"), "Opening");
    }

