    #[test]
    fn formatting_marks_are_display_only_toggle_and_persist() {
        let directory = tempfile::tempdir().unwrap();
        let mut app = WriterApp::create_project(directory.path().join("Novel"), "Novel").unwrap();
        let chapter = app.create_chapter(None, "Chapter", 10).unwrap();
        let scene = app.create_scene(chapter, "Scene", 0).unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.open_scene(scene).unwrap();
        state.editor = vec!["A line".into(), String::new(), "\tB line".into()];
        state.dirty = true;
        let original = state.editor.clone();

        let view_menu = MENU_CATEGORIES
            .iter()
            .position(|category| *category == "View")
            .unwrap();
        assert!(MENU_COMMON_COMMANDS[view_menu].contains(&"view.formatting-marks"));
        let command = command_by_id("view.formatting-marks").unwrap();
        assert_eq!(command.category, "View");
        assert_eq!(
            displayed_command_label(&state, command),
            "Show Formatting Marks"
        );
        assert_eq!(formatting_line_marker("A line", Some("")), Some("¶"));
        assert_eq!(formatting_line_marker("", Some("B line")), Some("¶"));
        assert_eq!(formatting_line_marker("A line", Some("B line")), Some("↵"));
        assert_eq!(formatting_line_marker("last line", None), None);

        state
            .dispatch_registered(CommandAction::ToggleFormattingMarks)
            .unwrap();
        assert!(state.editor_preferences.show_formatting_marks);
        assert_eq!(
            displayed_command_label(&state, command),
            "Hide Formatting Marks"
        );
        assert_eq!(state.editor, original);
        assert!(state.dirty);
        assert!(!state.message.contains("unsaved"));

        let stored = load_editor_preferences(state.app.project_root()).unwrap();
        assert!(stored.show_formatting_marks);
        state
            .dispatch_registered(CommandAction::ToggleFormattingMarks)
            .unwrap();
        assert!(!state.editor_preferences.show_formatting_marks);
        assert_eq!(state.editor, original);
        assert!(state.dirty);
        assert!(
            !load_editor_preferences(state.app.project_root())
                .unwrap()
                .show_formatting_marks
        );
    }

    #[test]
    fn editor_coalesces_adjacent_graphemes_without_crossing_style_boundaries() {
        let normal = Style::default();
        let cursor = normal.add_modifier(Modifier::REVERSED);
        let mut spans = Vec::new();

        push_coalesced_editor_span(&mut spans, "  ", normal);
        push_coalesced_editor_span(&mut spans, "The ", normal);
        push_coalesced_editor_span(&mut spans, "é", cursor);
        push_coalesced_editor_span(&mut spans, "lan", normal);

        assert_eq!(spans.len(), 3);
        assert_eq!(spans[0].content, "  The ");
        assert_eq!(spans[0].style, normal);
        assert_eq!(spans[1].content, "é");
        assert_eq!(spans[1].style, cursor);
        assert_eq!(spans[2].content, "lan");
        assert_eq!(spans[2].style, normal);
    }

    #[test]
    fn rendered_markdown_view_hides_supported_syntax_without_changing_source() {
        let directory = tempfile::tempdir().unwrap();
        let mut app = WriterApp::create_project(directory.path().join("Novel"), "Novel").unwrap();
        let chapter = app.create_chapter(None, "Chapter", 10).unwrap();
        let scene = app.create_scene(chapter, "Scene", 0).unwrap();
        let original_source = "# Heading\nA **bold** and *italic* line.";
        let (_, hash) = app.load_scene_text(scene).unwrap();
        app.save_scene_text(scene, Some(&hash), original_source)
            .unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.open_scene(scene).unwrap();
        state.dirty = false;

        let view_menu = MENU_CATEGORIES
            .iter()
            .position(|category| *category == "View")
            .unwrap();
        assert!(MENU_COMMON_COMMANDS[view_menu].contains(&"view.rendered-markdown"));
        let command = command_by_id("view.rendered-markdown").unwrap();
        assert_eq!(
            displayed_command_label(&state, command),
            "Show Rendered Markdown"
        );

        state
            .dispatch_registered(CommandAction::ToggleRenderedMarkdown)
            .unwrap();
        let mut terminal =
            ratatui::Terminal::new(ratatui::backend::TestBackend::new(100, 30)).unwrap();
        terminal.draw(|frame| draw(frame, &mut state)).unwrap();
        let screen = terminal
            .backend()
            .buffer()
            .content()
            .iter()
            .map(|cell| cell.symbol())
            .collect::<String>();
        assert!(screen.contains("Heading"));
        assert!(screen.contains("bold"));
        assert!(screen.contains("italic"));
        assert!(!screen.contains("**"));
        assert!(!screen.contains("# Heading"));
        assert!(screen.contains("rendered"));
        assert_eq!(state.editor.join("\n"), original_source);
        assert!(!state.dirty);
        assert_eq!(
            displayed_command_label(&state, command),
            "Show Markdown Source"
        );
        assert!(
            load_editor_preferences(state.app.project_root())
                .unwrap()
                .rendered_markdown
        );

        let database_source = state.app.load_scene_text(scene).unwrap().0;
        assert_eq!(database_source, original_source);
    }

    #[test]
    fn rendered_editor_navigation_and_typing_map_to_canonical_markdown_boundaries() {
        let directory = tempfile::tempdir().unwrap();
        let project = directory.path().join("Novel");
        let mut app = WriterApp::create_project(&project, "Novel").unwrap();
        let chapter = app.create_chapter(None, "Chapter", 0).unwrap();
        let scene = app.create_scene(chapter, "Scene", 0).unwrap();
        let source = "**bold** and *café* 🙂";
        let hash = app.load_scene_text(scene).unwrap().1;
        app.save_scene_text(scene, Some(&hash), source).unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.open_scene(scene).unwrap();
        state.editor_preferences.rendered_markdown = true;

        handle(
            &mut state,
            KeyEvent::new(KeyCode::Backspace, KeyModifiers::NONE),
        )
        .unwrap();
        assert_eq!(state.editor.join("\n"), source);
        assert!(!state.dirty, "backspace at the visible start is a no-op");

        handle(
            &mut state,
            KeyEvent::new(KeyCode::Char('X'), KeyModifiers::NONE),
        )
        .unwrap();
        assert_eq!(state.editor.join("\n"), "**Xbold** and *café* 🙂");
        state.undo_edit();
        assert_eq!(state.editor.join("\n"), source);

        state.editor_selection = None;
        state.cursor = (0, 0);
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Right, KeyModifiers::NONE),
        )
        .unwrap();
        assert_eq!(
            editor_position_byte(&state.editor, state.cursor.0, state.cursor.1),
            3
        );
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Right, KeyModifiers::NONE),
        )
        .unwrap();
        assert_eq!(
            editor_position_byte(&state.editor, state.cursor.0, state.cursor.1),
            4
        );
        handle(&mut state, KeyEvent::new(KeyCode::Left, KeyModifiers::NONE)).unwrap();
        assert_eq!(
            editor_position_byte(&state.editor, state.cursor.0, state.cursor.1),
            3
        );
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Right, KeyModifiers::SHIFT),
        )
        .unwrap();
        assert_eq!(state.selected_text().as_deref(), Some("o"));
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Char('c'), KeyModifiers::CONTROL),
        )
        .unwrap();
        assert_eq!(state.clipboard, "o");
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Backspace, KeyModifiers::NONE),
        )
        .unwrap();
        assert_eq!(state.editor.join("\n"), "**bld** and *café* 🙂");
        state.undo_edit();
        assert_eq!(state.editor.join("\n"), source);

        state.editor_selection = None;
        state.cursor = (0, 0);
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Delete, KeyModifiers::NONE),
        )
        .unwrap();
        assert_eq!(state.editor.join("\n"), "**old** and *café* 🙂");
        state.undo_edit();
        assert_eq!(state.editor.join("\n"), source);

        state.cursor = (0, 0);
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Right, KeyModifiers::NONE),
        )
        .unwrap();
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Right, KeyModifiers::NONE),
        )
        .unwrap();
        handle(
            &mut state,
            KeyEvent::new(KeyCode::Char('Y'), KeyModifiers::NONE),
        )
        .unwrap();
        assert_eq!(state.editor.join("\n"), "**boYld** and *café* 🙂");
        assert!(state.dirty);
    }

    #[test]
    fn semantic_format_commands_edit_selected_prose_and_remain_undoable_in_rendered_view() {
        let directory = tempfile::tempdir().unwrap();
        let project = directory.path().join("Novel");
        let mut app = WriterApp::create_project(&project, "Novel").unwrap();
        let chapter = app.create_chapter(None, "Chapter", 10).unwrap();
        let scene = app.create_scene(chapter, "Scene", 0).unwrap();
        let source = "A **bold** and *italic* line.";
        let (_, hash) = app.load_scene_text(scene).unwrap();
        app.save_scene_text(scene, Some(&hash), source).unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.open_scene(scene).unwrap();
        state.dirty = false;
        state.editor_preferences.rendered_markdown = true;

        let bold = command_by_id("edit.bold-selection").unwrap();
        let italic = command_by_id("edit.italic-selection").unwrap();
        assert_eq!(bold.category, "Edit");
        assert_eq!(italic.category, "Edit");
        let edit_menu = MENU_CATEGORIES
            .iter()
            .position(|category| *category == "Edit")
            .unwrap();
        assert!(MENU_COMMON_COMMANDS[edit_menu].contains(&bold.id));
        assert!(MENU_COMMON_COMMANDS[edit_menu].contains(&italic.id));
        assert!(bold.default_shortcuts.is_empty());
        assert!(italic.default_shortcuts.is_empty());

        let start = source.find("bold").unwrap();
        let end = start + "bold".len();
        state.editor_selection = Some(editor_position_from_byte(source, start).unwrap());
        state.cursor = editor_position_from_byte(source, end).unwrap();
        state
            .dispatch_registered(CommandAction::ToggleItalicSelection)
            .unwrap();
        assert_eq!(state.editor.join("\n"), "A ***bold*** and *italic* line.");
        assert_eq!(state.selection_bounds(), Some(((0, 5), (0, 9))));

        let mut terminal =
            ratatui::Terminal::new(ratatui::backend::TestBackend::new(100, 30)).unwrap();
        terminal.draw(|frame| draw(frame, &mut state)).unwrap();
        let screen = terminal
            .backend()
            .buffer()
            .content()
            .iter()
            .map(|cell| cell.symbol())
            .collect::<String>();
        assert!(screen.contains("bold"));
        assert!(!screen.contains("***"));

        state.undo_edit();
        assert_eq!(state.editor.join("\n"), source);
        assert!(state.dirty, "undo remains an unsaved manuscript change");
        state
            .dispatch_registered(CommandAction::ToggleItalicSelection)
            .unwrap();
        state.save().unwrap();
        assert_eq!(
            state.app.load_scene_text(scene).unwrap().0,
            "A ***bold*** and *italic* line."
        );

        state
            .dispatch_registered(CommandAction::ToggleItalicSelection)
            .unwrap();
        assert_eq!(state.editor.join("\n"), source);
        state.save().unwrap();
        assert_eq!(state.app.load_scene_text(scene).unwrap().0, source);

        state
            .dispatch_registered(CommandAction::ToggleBoldSelection)
            .unwrap();
        assert_eq!(state.editor.join("\n"), "A bold and *italic* line.");
        state.save().unwrap();

        let reopened = WriterApp::open_project(&project).unwrap();
        assert_eq!(
            reopened.load_scene_text(scene).unwrap().0,
            "A bold and *italic* line."
        );
    }

    #[test]
    fn named_window_layouts_persist_split_tree_and_reconnect_views_by_source_key() {
        let directory = tempfile::tempdir().unwrap();
        let project = directory.path().join("Novel");
        let mut app = WriterApp::create_project(&project, "Novel").unwrap();
        let chapter = app.create_chapter(None, "Chapter", 0).unwrap();
        let scene = app.create_scene(chapter, "Scene", 0).unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.open_scene(scene).unwrap();

        let mut layout = pane_layout::PaneLayout::default();
        let reference_id = layout
            .split(
                pane_layout::Orientation::Vertical,
                6_500,
                state.pane_bounds,
                18,
                6,
            )
            .unwrap();
        state.reference_panes.push(ReferencePane {
            layout_id: Some(reference_id),
            source_key: "outline:project".into(),
            scene_id: None,
            title: "Field Notes".into(),
            content: "A persistent reference view.".into(),
            scroll: 3,
            follow_context: false,
            shared_scene: false,
            cursor: (2, 4),
            selection_anchor: None,
            proofreading: None,
            spelling: None,
            thesaurus: None,
        });
        layout.focus(reference_id).unwrap();
        state.reference_focused = true;
        state.active_reference = 0;
        state.pane_layout = Some(layout.clone());

        state
            .save_named_window_layout("  Writing + Research  ")
            .unwrap();
        assert_eq!(
            state.named_window_layout_names().unwrap(),
            ["Writing + Research"]
        );

        // Runtime pane IDs can change as views are reopened. Restore by source
        // identity while retaining the saved split tree and its focused view.
        let mut current = pane_layout::PaneLayout::default();
        current.focus(1).unwrap();
        state.pane_layout = Some(current);
        state.reference_panes[0].layout_id = Some(9);
        state.reference_focused = false;
        state
            .load_named_window_layout("writing + research")
            .unwrap();
        let restored = state.pane_layout.as_ref().unwrap();
        assert_eq!(restored.panes(), [1, 9]);
        assert_eq!(restored.focused(), 9);
        assert_eq!(state.reference_panes[0].layout_id, Some(9));
        assert!(state.reference_focused);
        assert_eq!(state.reference_panes[0].source_key, "outline:project");
        assert_eq!(state.reference_panes[0].scroll, 3);

        let reopened_app = WriterApp::open_project(&project).unwrap();
        let mut reopened = AppState::new(reopened_app, default_bindings());
        reopened.restore_session().unwrap();
        assert_eq!(reopened.pane_layout.as_ref().unwrap().panes(), [1, 9]);
        assert_eq!(reopened.pane_layout.as_ref().unwrap().focused(), 9);
        assert_eq!(reopened.reference_panes[0].source_key, "outline:project");
    }

    #[test]
    fn named_window_layout_load_missing_view_or_invalid_name_leaves_layout_unchanged() {
        let directory = tempfile::tempdir().unwrap();
        let project = directory.path().join("Novel");
        let mut app = WriterApp::create_project(&project, "Novel").unwrap();
        let chapter = app.create_chapter(None, "Chapter", 0).unwrap();
        let scene = app.create_scene(chapter, "Scene", 0).unwrap();
        let mut state = AppState::new(app, default_bindings());
        state.open_scene(scene).unwrap();
        let mut saved = pane_layout::PaneLayout::default();
        let reference_id = saved
            .split(
                pane_layout::Orientation::Vertical,
                5_000,
                state.pane_bounds,
                18,
                6,
            )
            .unwrap();
        state.reference_panes.push(ReferencePane {
            layout_id: Some(reference_id),
            source_key: "research:missing-later".into(),
            scene_id: None,
            title: "Reference".into(),
            content: "Reference text.".into(),
            scroll: 0,
            follow_context: false,
            shared_scene: false,
            cursor: (0, 0),
            selection_anchor: None,
            proofreading: None,
            spelling: None,
            thesaurus: None,
        });
        state.pane_layout = Some(saved);
        state.save_named_window_layout("Research").unwrap();

        assert!(validate_window_layout_name("../outside").is_err());
        let before = state.pane_layout.clone();
        state.reference_panes.clear();
        assert!(state.load_named_window_layout("Research").is_err());
        assert_eq!(state.pane_layout, before);
    }

    #[test]
    fn spelling_occurrences_map_each_unicode_match_to_grapheme_columns() {
        let source = "e\u{301} café café.\nWrong.";
        let candidates = BTreeMap::from([("café".to_owned(), 2), ("wrong".to_owned(), 1)]);

        let occurrences = spelling_occurrences(source, &candidates);

        assert_eq!(occurrences.len(), 3);
        assert_eq!(
            occurrences
                .iter()
                .map(|occurrence| (occurrence.word.as_str(), occurrence.line, occurrence.column))
                .collect::<Vec<_>>(),
            [("café", 1, 3), ("café", 1, 8), ("Wrong", 2, 1)]
        );
        for occurrence in &occurrences {
            assert_eq!(
                source.get(occurrence.byte_range.clone()),
                Some(occurrence.word.as_str())
            );
        }
    }
